--
-- Name: advance_round(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_round(r uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  g public.jobs;
  p public.jobs;
  w public.jobs;
  lead uuid;
  tk uuid;
  st integer;
  part jsonb;
  s uuid;
  workers integer;
  one uuid;
begin
  perform pg_advisory_xact_lock(hashtext(r::text));
  if exists (select 1 from public.jobs where round = r and kind = 'combine') then
    return;
  end if;
  select * into w from public.jobs where round = r and kind in ('plan', 'work') order by created_at, (kind = 'plan') desc limit 1;
  if not found then
    return;
  end if;
  lead := w.member_id;
  tk := w.task_id;
  -- A lead taken off the table, or whose AI is gone, hands the rest of the round on to someone still here.
  if not public.seat_alive(lead) then
    lead := coalesce(public.final_seat_now(w.table_id), lead);
  end if;

  -- The first step waits for the others to have their say.
  select * into g from public.jobs where round = r and status = 'waiting' and kind in ('plan', 'work') limit 1;
  if found then
    if not exists (select 1 from public.jobs v where v.round = r and v.kind = 'view' and v.status in ('queued', 'running'))
       or g.created_at < now() - interval '90 seconds' then
      update public.jobs set status = 'skipped', error = 'did not answer in time' where round = r and kind = 'view' and status = 'queued';
      update public.jobs set status = 'queued', created_at = now() where id = g.id;
    end if;
    return;
  end if;

  -- The plan, then one piece of work for each person it names.
  select * into p from public.jobs where round = r and kind = 'plan' limit 1;
  if found and not exists (select 1 from public.jobs where round = r and kind = 'work') then
    if p.status = 'queued' and p.created_at > now() - interval '5 minutes' then
      return;
    end if;
    if p.status = 'running' and p.lease_until > now() - interval '2 minutes' then
      return;
    end if;
    if p.status in ('queued', 'running') then
      update public.jobs set status = 'skipped', lease_until = null, error = 'the plan never came' where id = p.id;
      p.status := 'skipped';
    end if;
    if p.status = 'failed' and not exists (select 1 from public.connections cn where cn.member_id = lead and cn.revoked_at is null) then
      insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id)
        values (p.table_id, p.chat_id, coalesce(public.final_seat_now(p.table_id), lead), p.question_id, 'combine', r, tk);
      return;
    end if;
    if p.status = 'done' then
      for part in select * from jsonb_array_elements(coalesce(p.outcome -> 'parts', '[]'::jsonb)) loop
        insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id, brief)
          values (p.table_id, p.chat_id,
                  case when public.seat_alive((part ->> 'member')::uuid) then (part ->> 'member')::uuid else lead end,
                  p.question_id, 'work', r, tk, part ->> 'brief');
      end loop;
    end if;
    if not exists (select 1 from public.jobs where round = r and kind = 'work') then
      insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id)
        values (p.table_id, p.chat_id, lead, p.question_id, 'work', r, tk);
    end if;
    return;
  end if;

  select max(stage) into st from public.jobs where round = r and kind = 'work';
  if st is null then
    return;
  end if;
  -- Work has no time limit. It is only given up on when its computer never took it, or stopped saying it is alive.
  update public.jobs set status = 'skipped', lease_until = null,
         error = case when status = 'queued' then 'its computer never picked it up' else 'it stopped answering' end
   where round = r and kind = 'work' and stage = st
     and ((status = 'queued' and created_at < now() - interval '10 minutes'
           and not exists (select 1 from public.jobs b where b.member_id = jobs.member_id and b.id <> jobs.id and b.status = 'running' and b.kind in ('work', 'answer') and b.lease_until > now()))
       or (status = 'running' and lease_until < now() - interval '10 minutes'));
  if exists (select 1 from public.jobs where round = r and kind = 'work' and stage = st and status in ('queued', 'running')) then
    return;
  end if;

  if exists (select 1 from public.jobs where round = r and kind = 'work' and stage = st and status = 'done'
              and coalesce((outcome ->> 'changed')::boolean, false)) then
    if not exists (select 1 from public.jobs where round = r and kind = 'review' and stage = st) then
      if st < 2 then
        select count(distinct member_id), min(member_id::text)::uuid into workers, one
          from public.jobs where round = r and kind = 'work' and stage = st and status = 'done';
        -- One worker: the others look it over. Several: everyone looks over the whole of it, the others' parts included.
        for s in select distinct cn.member_id from public.connections cn
                  join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer')
                 where cn.table_id = w.table_id and cn.revoked_at is null
                   and cn.last_seen > now() - interval '60 seconds' and (workers > 1 or cn.member_id <> one) loop
          insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, stage, task_id)
            values (w.table_id, w.chat_id, s, w.question_id, 'review', r, st, tk);
        end loop;
        if exists (select 1 from public.jobs where round = r and kind = 'review' and stage = st) then
          return;
        end if;
      end if;
    else
      update public.jobs set status = 'skipped', error = 'did not answer in time', lease_until = null
        where round = r and kind = 'review' and stage = st
          and ((status = 'queued' and created_at < now() - interval '2 minutes'
                and not exists (select 1 from public.jobs b where b.member_id = jobs.member_id and b.id <> jobs.id and b.status = 'running' and b.kind not in ('work', 'answer') and b.lease_until > now()))
            or (status = 'running' and lease_until < now() - interval '2 minutes'));
      if exists (select 1 from public.jobs where round = r and kind = 'review' and stage = st and status in ('queued', 'running')) then
        return;
      end if;
      if st < 2 and exists (select 1 from public.jobs where round = r and kind = 'review' and stage = st
                             and status = 'done' and not coalesce((outcome ->> 'ok')::boolean, true)) then
        insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, stage, task_id)
          values (w.table_id, w.chat_id, lead, w.question_id, 'work', r, st + 1, tk);
        return;
      end if;
    end if;
  end if;

  insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id)
    values (w.table_id, w.chat_id, coalesce(public.final_seat_now(w.table_id), lead), w.question_id, 'combine', r, tk);
end;
$$;

--
-- Name: advance_rounds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_rounds() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r uuid;
begin
  for r in select distinct w.round from public.jobs w
            where w.round is not null and w.kind in ('plan', 'work') and w.created_at > now() - interval '30 days'
              and not exists (select 1 from public.jobs c where c.round = w.round and c.kind = 'combine')
              and not exists (select 1 from public.chats ch where ch.id = w.chat_id and ch.answers = 'off') loop
    begin
      perform public.advance_round(r);
    exception when others then
      raise warning 'tripwire: a round could not move on: %', sqlerrm;
    end;
  end loop;
end;
$$;

--
-- Name: answer_join(uuid, boolean, public.member_role); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.answer_join(r uuid, let_in boolean, as_role public.member_role DEFAULT 'developer'::public.member_role) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  q public.join_requests;
  was public.members;
  me uuid;
begin
  select * into q from public.join_requests where id = r for update;
  if not found or not public.is_owner(q.table_id) then raise exception 'only an owner answers this'; end if;
  if q.status <> 'waiting' then raise exception 'someone already answered this'; end if;
  if not let_in then
    update public.join_requests set status = 'no', decided_at = now(), decided_by = public.my_member_id(q.table_id) where id = r;
    perform public.log_activity(q.table_id, public.my_member_id(q.table_id), 'join.answered', r, jsonb_build_object('name', q.name, 'in', false));
    return;
  end if;
  if as_role not in ('developer', 'client') then raise exception 'let them in as a developer, then make them a co-owner'; end if;
  if public.table_is_locked(q.table_id) then raise exception 'the table is locked: unlock it first'; end if;
  -- Locked in the same order as remove_member and transfer_ownership: the table first.
  perform 1 from public.tables where id = q.table_id for update;
  select * into was from public.members m where m.table_id = q.table_id and m.user_id = q.user_id;
  if found and was.removed_at is null then
    me := was.id;
  elsif found then
    update public.members set removed_at = null, role = as_role, can_settings = false, can_invite = false, can_clients = false,
           display_name = q.name,
           bubble = case when exists (select 1 from public.members o where o.table_id = was.table_id and o.bubble = was.bubble
           and o.id <> was.id and o.removed_at is null) then public.free_bubble(was.table_id) else bubble end
     where id = was.id returning id into me;
  else
    insert into public.members (table_id, user_id, role, display_name, color)
      values (q.table_id, q.user_id, as_role, q.name, public.next_color(q.table_id)) returning id into me;
  end if;
  update public.join_requests set status = 'in', role = as_role, decided_at = now(), decided_by = public.my_member_id(q.table_id) where id = r;
  perform public.log_activity(q.table_id, me, 'member.joined', me, jsonb_build_object('role', as_role, 'name', q.name, 'code', true));
end;
$$;

--
-- Name: answer_question(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.answer_question(a uuid, words text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r public.approvals;
  clean text := btrim(coalesce(words, ''));
begin
  select * into r from public.approvals where id = a for update;
  if not found or r.member_id <> public.my_member_id(r.table_id) then
    raise exception 'only the person whose AI asked can answer';
  end if;
  if r.kind <> 'question' then
    raise exception 'that is a request to allow, not a question';
  end if;
  if r.status <> 'waiting' then
    raise exception 'this question was already answered, or its work has ended';
  end if;
  if clean = '' then
    raise exception 'an answer cannot be empty';
  end if;
  update public.approvals set status = 'allowed', answer = left(clean, 2000), decided_at = now() where id = a;
  perform realtime.send(jsonb_build_object('table', 'approvals', 'record', jsonb_build_object('id', a, 'member_id', r.member_id)),
    'UPDATE', 'team:' || r.table_id::text, true);
end;
$$;

--
-- Name: answer_waiting_clients(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.answer_waiting_clients() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  w record;
  seat uuid;
  n integer := 0;
begin
  for w in
    select l.* from public.client_lines l join public.members m on m.id = l.member_id and m.removed_at is null
     where l.waiting and l.who = 'client'
       and public.client_desk_seat(l.table_id) is not null
       and not exists (select 1 from public.jobs j where j.line_id = l.id and j.status in ('queued', 'running'))
     order by l.created_at limit 20
     for update of l skip locked
  loop
    seat := public.client_desk_seat(w.table_id);
    continue when seat is null;
    insert into public.jobs (table_id, member_id, kind, line_id, subject) values (w.table_id, seat, 'client', w.id, w.member_id);
    update public.client_lines set waiting = false where id = w.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;

--
-- Name: ask_table(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ask_table(c uuid, body text, files jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid;
  me uuid;
  q uuid;
  words text := btrim(coalesce(body, ''));
  got jsonb;
begin
  select ch.table_id into t from public.chats ch where ch.id = c;
  if t is null or not public.can_see_chat(c) or not (select ch.set_up from public.chats ch where ch.id = c) then
    raise exception 'only the team can ask the table';
  end if;
  me := public.my_member_id(t);
  if char_length(words) = 0 and coalesce(jsonb_array_length(files), 0) = 0 then
    raise exception 'ask something';
  end if;
  if char_length(words) > 8000 then
    raise exception 'that is a lot for one message; keep it to 8,000 characters or fewer';
  end if;
  -- A message that is only attachments still needs words to be found by: their names.
  if char_length(words) = 0 then
    words := left((select string_agg(f ->> 'name', ', ') from jsonb_array_elements(files) f), 500);
  end if;
  perform set_config('longtable.asked', '1', true);
  insert into public.messages (table_id, chat_id, member_id, body) values (t, c, me, words) returning id into q;
  if coalesce(jsonb_array_length(files), 0) > 0 then
    got := public.take_files(t, me, files, q);
    update public.messages set meta = meta || jsonb_build_object('files', got) where id = q;
  end if;
  -- In a chat no AI hears, asking is only saying.
  if (select ch.answers from public.chats ch where ch.id = c) = 'off' then
    return jsonb_build_object('message_id', q, 'answered_by', null);
  end if;
  return public.start_round(t, c, q, me);
end;
$$;

--
-- Name: ask_to_join(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ask_to_join(code text, my_name text, note text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c text := upper(regexp_replace(coalesce(code, ''), '[^A-Za-z0-9]', '', 'g'));
  j public.table_joining;
  tname text;
  was public.members;
  r public.join_requests;
  words text := left(btrim(coalesce(my_name, '')), 60);
begin
  if auth.uid() is null then raise exception 'sign in first'; end if;
  if (select count(*) from public.join_tries where user_id = auth.uid() and at > now() - interval '1 hour') >= 10 then
    raise exception 'Too many wrong codes. Try again in an hour.';
  end if;
  select * into j from public.table_joining where table_joining.code = c;
  if not found then
    -- Answered, not raised: raising would undo the record of this try along with everything else.
    insert into public.join_tries (user_id) values (auth.uid());
    return jsonb_build_object('status', 'wrong');
  end if;
  select name into tname from public.tables where id = j.table_id;
  select * into was from public.members m where m.table_id = j.table_id and m.user_id = auth.uid();
  if found and was.removed_at is null then
    return jsonb_build_object('status', 'member', 'table_id', j.table_id, 'table_name', tname);
  end if;
  if j.locked then raise exception '% is not taking new people right now.', tname; end if;
  select * into r from public.join_requests where table_id = j.table_id and user_id = auth.uid() and status = 'waiting';
  if found then
    return jsonb_build_object('status', 'waiting', 'table_id', j.table_id, 'table_name', tname, 'request', r.id);
  end if;
  if exists (select 1 from public.join_requests where table_id = j.table_id and user_id = auth.uid() and status = 'no'
             and decided_at > now() - interval '7 days') then
    raise exception 'The owners of % did not let you in. Ask one of them directly.', tname;
  end if;
  if words = '' then raise exception 'add your name'; end if;
  if (select count(*) from public.join_requests where user_id = auth.uid() and status = 'waiting') >= 5 then
    raise exception 'You are already waiting on five tables. Cancel one first.';
  end if;
  if (select count(*) from public.join_requests where table_id = j.table_id and status = 'waiting') >= 50 then
    raise exception '% has too many people waiting. Ask an owner to answer them first.', tname;
  end if;
  insert into public.join_requests (table_id, user_id, name, email, note)
    values (j.table_id, auth.uid(), words, coalesce((select email from auth.users where id = auth.uid()), ''),
            left(btrim(coalesce(note, '')), 200))
    returning * into r;
  perform public.log_activity(j.table_id, null, 'join.asked', r.id, jsonb_build_object('name', words));
  return jsonb_build_object('status', 'waiting', 'table_id', j.table_id, 'table_name', tname, 'request', r.id);
end;
$$;

--
-- Name: broadcast_chat_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_chat_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c uuid;
  t uuid;
begin
  if tg_op = 'DELETE' then
    return null;
  end if;
  t := new.table_id;
  if tg_table_name = 'chats' then
    c := new.id;
    -- Everyone hears that a private chat changed, never its name or what it is about: their screens read the list
    -- again and see it only if they are in it.
    if new.private or (tg_op = 'UPDATE' and old.private) then
      perform realtime.send(jsonb_build_object('table', 'chats', 'record', jsonb_build_object('id', new.id, 'table_id', t, 'private', true)),
        tg_op, 'team:' || t::text, true);
      if new.private then
        perform realtime.broadcast_changes('room:' || c::text, tg_op, tg_op, tg_table_name, tg_table_schema, new, old);
      end if;
      return null;
    end if;
  elsif tg_table_name in ('page_comments', 'page_state') then
    select p.chat_id into c from public.pages p where p.id = new.page_id;
  else
    c := new.chat_id;
  end if;
  perform realtime.broadcast_changes(public.chat_topic(t, c), tg_op, tg_op, tg_table_name, tg_table_schema, new, old);
  return null;
end;
$$;

