begin
  perform realtime.broadcast_changes('client:' || new.table_id::text || ':' || new.member_id::text, tg_op, tg_op, tg_table_name, tg_table_schema, new, null);
  return null;
end;
$$;

--
-- Name: broadcast_client_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_client_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  asker uuid;
begin
  if new.request_id is not null then
    select r.member_id into asker from public.requests r where r.id = new.request_id;
  end if;
  perform realtime.broadcast_changes('client:' || new.table_id::text || coalesce(':' || asker::text, ''),
    tg_op, tg_op, tg_table_name, tg_table_schema, new, old);
  return null;
end;
$$;

--
-- Name: broadcast_client_wrote(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_client_wrote() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'client_lines' then
    if not (new.who = 'client' and new.by_table) then return null; end if;
  end if;
  perform realtime.send(jsonb_build_object('table', 'client_wrote', 'record', jsonb_build_object('id', new.member_id)),
    'INSERT', 'team:' || new.table_id::text, true);
  return null;
end;
$$;

--
-- Name: broadcast_connection_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_connection_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  rec jsonb := jsonb_build_object('table', 'connections', 'record', to_jsonb(new) - 'token_hash' - 'commands' - 'local');
begin
  perform realtime.send(rec, tg_op, 'team:' || new.table_id::text, true);
  if exists (select 1 from public.members m where m.id = new.member_id and m.role = 'client') then
    perform realtime.send(rec, tg_op, 'client:' || new.table_id::text || ':' || new.member_id::text, true);
  end if;
  return null;
end;
$$;

--
-- Name: broadcast_job_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.broadcast_job_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.kind = 'client' and new.subject is not null and new.subject <> new.member_id then
    -- Answered by the team's assistant: the client hears it on their own channel, and only which job and its state.
    perform realtime.send(jsonb_build_object('table', 'jobs', 'record', jsonb_build_object('id', new.id, 'kind', new.kind, 'status', new.status, 'member_id', new.subject, 'created_at', new.created_at, 'stage', coalesce(new.stage, 0))),
      tg_op, 'client:' || new.table_id::text || ':' || new.subject::text, true);
  elsif new.kind = 'client' then
    perform realtime.broadcast_changes('client:' || new.table_id::text || ':' || new.member_id::text, tg_op, tg_op, tg_table_name, tg_table_schema, new, null);
  else
    perform realtime.broadcast_changes(public.chat_topic(new.table_id, new.chat_id), tg_op, tg_op, tg_table_name, tg_table_schema, new, old);
  end if;
  return null;
end;
$$;

