--
-- Name: can_see_chat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_see_chat(c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.chats ch
                  where ch.id = c and public.is_team(ch.table_id)
                    and (not ch.private or exists (select 1 from public.chat_people p where p.chat_id = c and p.member_id = public.my_member_id(ch.table_id))));
$$;

--
-- Name: cancel_join(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_join(r uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.join_requests set status = 'cancelled', decided_at = now()
   where id = r and user_id = auth.uid() and status = 'waiting';
end;
$$;

--
-- Name: chat_is_private(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_is_private(c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select ch.private from public.chats ch where ch.id = c), false);
$$;

--
-- Name: chat_off_ends_work(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_off_ends_work() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.tasks set status = 'stopped', finished_at = now() where chat_id = new.id and status = 'working';
  return new;
end;
$$;

--
-- Name: chat_topic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.chat_topic(t uuid, c uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when c is not null and public.chat_is_private(c) then 'room:' || c::text else 'team:' || t::text end;
$$;

--
-- Name: clear_tasks(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_tasks(t uuid) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  at timestamptz := now();
begin
  if not public.is_team(t) then
    raise exception 'only the team has this list';
  end if;
  update public.members set tasks_cleared_at = at where id = public.my_member_id(t);
  return at;
end;
$$;

--
-- Name: client_ask(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_ask(t uuid, body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  words text := btrim(coalesce(body, ''));
begin
  select * into me from public.members where table_id = t and user_id = auth.uid() and removed_at is null;
  if not found or me.role <> 'client' then
    raise exception 'only the client asks here';
  end if;
  if char_length(words) = 0 then
    raise exception 'ask for something';
  end if;
  if public.client_said_lately(me.id) >= 30 then
    raise exception 'that is a lot of requests in one hour, try again a little later';
  end if;
  return public.pass_on_request(me.id, words, null, null, true);
end;
$$;

--
-- Name: client_chat_hears(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_chat_hears() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.client_chat is not null and exists (select 1 from public.chats ch where ch.id = new.client_chat and ch.answers = 'off') then
    raise exception 'clients'' requests cannot go to a chat no AI hears';
  end if;
  return new;
end;
$$;

--
-- Name: client_chat_read(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_chat_read(m uuid, upto timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
begin
  select * into who from public.members where id = m and role = 'client';
  if not found or not public.may(who.table_id, 'clients') then raise exception 'only someone who may write in this chat keeps a place in it'; end if;
  insert into public.client_chat_reads (member_id, client_id, read_at)
  values (public.my_member_id(who.table_id), m, least(upto, now()))
  on conflict (member_id, client_id) do update set read_at = greatest(public.client_chat_reads.read_at, excluded.read_at);
end;
$$;

--
-- Name: client_desk_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_desk_seat(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select cn.member_id
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and m.removed_at is null
   where cn.table_id = t and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds'
   order by (cn.member_id = public.final_seat_now(t)) desc, cn.created_at limit 1;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    chat_id uuid,
    member_id uuid NOT NULL,
    question_id uuid,
    status public.job_status DEFAULT 'queued'::public.job_status NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    lease_until timestamp with time zone,
    connection_id uuid,
    result_message_id uuid,
    error text,
    usage jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    kind text DEFAULT 'answer'::text NOT NULL,
    round uuid,
    line_id uuid,
    stage integer DEFAULT 0 NOT NULL,
    outcome jsonb DEFAULT '{}'::jsonb NOT NULL,
    progress text,
    task_id uuid,
    brief text,
    change_id uuid,
    subject uuid,
    approval_key text,
    taking boolean DEFAULT false NOT NULL,
    early boolean DEFAULT false NOT NULL,
    CONSTRAINT jobs_client_shape CHECK (((kind = 'client'::text) = ((line_id IS NOT NULL) AND (chat_id IS NULL)))),
    CONSTRAINT jobs_kind_check CHECK ((kind = ANY (ARRAY['answer'::text, 'view'::text, 'combine'::text, 'intro'::text, 'client'::text, 'work'::text, 'review'::text, 'listen'::text, 'look'::text, 'plan'::text, 'sandbox'::text, 'notes'::text])))
);

--
-- Name: client_job_payload(public.jobs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_job_payload(j public.jobs) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'job_id', j.id,
    'kind', 'client', 'for_team', j.subject is not null,
    -- A deeper look (stage 1): the question the team's assistant wrote, for a team Claude that reads the code.
    'stage', coalesce(j.stage, 0), 'brief', case when coalesce(j.stage, 0) = 1 then j.brief end,
    'can_look', j.subject is not null and coalesce(j.stage, 0) = 0 and public.client_look_seat(j.table_id) is not null,
    -- They have a copy of their own: a change they ask for can be tried in it (the team's assistant decides).
    'has_copy', j.subject is not null and coalesce(j.stage, 0) = 0
      and exists (select 1 from public.sandboxes s where s.member_id = j.subject and s.mode = 'sandbox'),
    -- A person on the team wrote in this chat in the last 15 minutes: the two of them may be talking, and the team's
    -- assistant may then stay out of it (quiet).
    'team_talking', j.subject is not null and coalesce(j.stage, 0) = 0 and exists (select 1 from public.client_lines l
      where l.member_id = j.subject and l.who = 'team' and l.created_at > now() - interval '15 minutes'),
    -- Their words already reached the team as a request: answer, and never pass them on again.
    'already_passed', (select l.request_id is not null from public.client_lines l where l.id = j.line_id),
    -- What the team's AIs took on at this table, by title only: what is finished and what is under way. The owner
    -- chose to let a client hear this. Nothing of how it was done, who asked, or what was said about it.
    'work', coalesce((
      select jsonb_agg(jsonb_build_object('title', public.hide_secrets(left(w.title, 120)), 'status', w.status) order by w.created_at desc)
        from (select * from public.tasks t2 where t2.table_id = j.table_id and t2.status in ('working', 'done') and not public.chat_is_private(t2.chat_id)
                 -- Work the team took from a client's own copy is titled with that client's name and words:
                 -- it is not for another client's side to carry. The client it came from still hears of it,
                 -- and is known by their copy's own branch, which the work keeps.
                 and (t2.reference ->> 'branch' = (select s.branch from public.sandboxes s where s.member_id = coalesce(j.subject, j.member_id))
                      -- Everything else the team took on, except work whose title names another client at the
                      -- table: one client never hears of work about another.
                      or (t2.reference ->> 'client' is null
                          and not exists (select 1 from public.members o where o.table_id = j.table_id and o.role = 'client'
                                            and o.id <> coalesce(j.subject, j.member_id)
                                            and char_length(regexp_replace(split_part(btrim(o.display_name), ' ', 1), '[^[:alnum:]]', '', 'g')) > 1
                                            and lower(' ' || regexp_replace(t2.title, '[^[:alnum:]]+', ' ', 'g') || ' ')
                                                like '% ' || lower(regexp_replace(split_part(btrim(o.display_name), ' ', 1), '[^[:alnum:]]', '', 'g')) || ' %')))
                 order by t2.created_at desc limit 30) w), '[]'::jsonb),
    'table_name', (select name from public.tables where id = j.table_id),
    'me', (select display_name from public.members where id = coalesce(j.subject, j.member_id)),
    'question', (select body from public.client_lines where id = j.line_id),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object(
               'title', r.title, 'status', r.status, 'asked', r.created_at,
               'timeline', coalesce((select jsonb_agg(e.label order by e.id) from public.request_events e where e.request_id = r.id), '[]'::jsonb))
             order by r.created_at desc)
        from (select * from public.requests r2 where r2.member_id = coalesce(j.subject, j.member_id) order by r2.created_at desc limit 30) r), '[]'::jsonb),
    'told', coalesce((
      select jsonb_agg(jsonb_build_object('when', u.created_at, 'words', u.body, 'their_answer', u.answer) order by u.created_at desc)
        from (select * from public.client_updates u2
               where u2.table_id = j.table_id
                 and (u2.request_id is null or exists (select 1 from public.requests r3 where r3.id = u2.request_id and r3.member_id = coalesce(j.subject, j.member_id)))
               order by u2.created_at desc limit 30) u), '[]'::jsonb),
    'history', coalesce((
      select jsonb_agg(jsonb_build_object('who', l.who, 'body', l.body, 'name', l.from_name) order by l.created_at)
        from (select * from public.client_lines l2 where l2.member_id = coalesce(j.subject, j.member_id) and l2.id <> j.line_id
                 -- One of the team's AIs is only handed what was said to the team's assistant. What a client said to
                 -- an assistant they connected themselves is theirs, and the team does not read it.
                 and (j.subject is null or l2.by_table)
               order by l2.created_at desc limit 20) l), '[]'::jsonb));
$$;

--
-- Name: client_job_timeouts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_job_timeouts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  stale record;
  n integer := 0;
begin
  perform public.answer_waiting_clients();
  for stale in
    select id, status from public.jobs
     where kind = 'client'
       and ((status = 'queued' and created_at < now() - interval '180 seconds')
         or (status = 'running' and coalesce(started_at, created_at) < now() - (case when stage = 1 then interval '240 seconds' else interval '100 seconds' end)))
  loop
    perform public.give_up_client_job(stale.id, case when stale.status = 'queued' then 'not picked up in 3 minutes' else 'no answer in 100 seconds' end);
    n := n + 1;
  end loop;
  return n;
end;
$$;

--
-- Name: client_look_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_look_seat(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select cn.member_id
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and m.removed_at is null
   where cn.table_id = t and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
   order by (cn.member_id = public.final_seat_now(t)) desc, cn.created_at limit 1;
$$;

--
-- Name: client_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_overview(t uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me uuid := public.client_seat(t);
begin
  if me is null then
    raise exception 'that is not a table you are a client at';
  end if;
  return jsonb_build_object(
    'team', (select coalesce(jsonb_agg(jsonb_build_object('name', m.display_name, 'color', m.color, 'avatar', m.avatar, 'role', m.role,
               'ai_on', exists (select 1 from public.connections c where c.member_id = m.id and c.revoked_at is null and c.last_seen > now() - interval '90 seconds'))
               order by (m.role = 'owner') desc, m.created_at), '[]'::jsonb)
              from public.members m where m.table_id = t and m.role in ('owner', 'developer') and m.removed_at is null),
    'requests', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'title', r.title, 'status', r.status, 'at', r.updated_at) order by r.updated_at desc), '[]'::jsonb)
                  from (select * from public.requests r2 where r2.member_id = me order by r2.updated_at desc limit 30) r),
    'work', (select coalesce(jsonb_agg(jsonb_build_object('title', public.hide_secrets(left(w.title, 120)), 'status', w.status) order by w.created_at desc), '[]'::jsonb)
              from (select * from public.tasks t2 where t2.table_id = t and t2.status in ('working', 'done') and not public.chat_is_private(t2.chat_id)
                       and (t2.reference ->> 'branch' = (select s.branch from public.sandboxes s where s.member_id = me)
                            or (t2.reference ->> 'client' is null
                                and not exists (select 1 from public.members o where o.table_id = t and o.role = 'client' and o.id <> me
                                                  and char_length(regexp_replace(split_part(btrim(o.display_name), ' ', 1), '[^[:alnum:]]', '', 'g')) > 1
                                                  and lower(' ' || regexp_replace(t2.title, '[^[:alnum:]]+', ' ', 'g') || ' ')
                                                      like '% ' || lower(regexp_replace(split_part(btrim(o.display_name), ' ', 1), '[^[:alnum:]]', '', 'g')) || ' %')))
                     order by t2.created_at desc limit 12) w));
end;
$$;

--
-- Name: client_refresh_copy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_refresh_copy(t uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  sb public.sandboxes;
  seat uuid;
begin
  select * into me from public.members where id = public.client_seat(t);
  if not found or me.role <> 'client' or me.removed_at is not null then
    return false;
  end if;
  select * into sb from public.sandboxes where member_id = me.id for update;
  if not found or sb.mode <> 'sandbox' or sb.refreshed_at > now() - interval '1 hour'
     or exists (select 1 from public.jobs j where j.subject = me.id and j.kind = 'sandbox' and j.status in ('queued', 'running')) then
    return false;
  end if;
  seat := public.copy_seat(t);
  if seat is null then
    return false;
  end if;
  update public.sandboxes set refreshed_at = now() where member_id = me.id;
  insert into public.jobs (table_id, member_id, kind, subject, brief) values (t, seat, 'sandbox', me.id, 'refresh');
  return true;
end;
$$;

--
-- Name: client_reply(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_reply(u uuid, choice integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  upd public.client_updates;
  me public.members;
  req public.requests;
  dec public.decisions;
  picked text;
  landing uuid;
begin
  select * into upd from public.client_updates where id = u for update;
  if not found then
    raise exception 'that question is not here';
  end if;
  select * into me from public.members where id = public.client_seat(upd.table_id);
  if not found or me.role <> 'client' then
    raise exception 'only the client answers here';
  end if;
  -- Only ever a question about this client's own request: an answer is never shared between clients.
  if upd.request_id is null then
    raise exception 'that question is not here';
  end if;
  select * into req from public.requests where id = upd.request_id;
  if req.member_id <> me.id then
    raise exception 'that question is not here';
  end if;
  if cardinality(upd.replies) = 0 then
    raise exception 'that is not a question';
  end if;
  if upd.answer is not null then
    raise exception 'already answered';
  end if;
  if choice is null or choice < 1 or choice > cardinality(upd.replies) then
    raise exception 'pick one of the answers';
  end if;
  picked := upd.replies[choice];
  update public.client_updates set answer = picked, answered_at = now(), answered_by = me.id where id = u;
  select * into dec from public.decisions where id = upd.decision_id;
  landing := coalesce(dec.chat_id,
    (select coalesce(tb.client_chat, (select ch.id from public.chats ch where ch.table_id = upd.table_id and ch.is_general))
       from public.tables tb where tb.id = upd.table_id));
  insert into public.messages (table_id, chat_id, member_id, body, kind, meta)
    values (upd.table_id, landing, me.id, picked, 'client',
            jsonb_build_object('request', upd.request_id, 'answers', upd.decision_id, 'question', upd.body));
  if req.id is not null then
    update public.requests set status = 'answered', updated_at = now() where id = req.id;
    perform public.add_request_event(req.id, 'You answered: ' || picked);
  end if;
  insert into public.client_updates (table_id, request_id, body)
    values (upd.table_id, upd.request_id, 'Thanks, passed on to the team.');
  perform public.log_activity(upd.table_id, me.id, 'client.answered', coalesce(req.id, upd.id), jsonb_build_object('answer', picked));
end;
$$;

--
-- Name: client_said_lately(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_said_lately(m uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select ((select count(*) from public.requests r where r.member_id = m and r.from_line is null and r.created_at > now() - interval '1 hour')
        + (select count(*) from public.client_lines l where l.member_id = m and l.who = 'client' and l.created_at > now() - interval '1 hour'))::integer;
$$;

--
-- Name: client_sandbox(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_sandbox(t uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  sb public.sandboxes;
begin
  select * into me from public.members where id = public.client_seat(t);
  if not found or me.role <> 'client' then
    raise exception 'only the client has a sandbox';
  end if;
  select * into sb from public.sandboxes where member_id = me.id;
  return jsonb_build_object(
    'on', coalesce(sb.mode = 'sandbox', false),
    'url', sb.url,
    -- Its newest commit is not online yet (only where the hosting reports its builds, and for twenty minutes at most).
    'building', coalesce(sb.deploys_seen and sb.tip is not null and sb.tip_at > now() - interval '20 minutes'
                  and not public.same_commit(sb.tip, sb.live_sha) and not public.same_commit(sb.tip, sb.failed_sha), false),
    -- Its newest commit did not build: the copy still shows the version before it.
    'broken', coalesce(sb.tip is not null and public.same_commit(sb.tip, sb.failed_sha), false),
    -- It could not take in the team's latest (their changes clash with it), so it shows an older version for now.
    'behind', sb.behind_since is not null,
    'left', (select greatest(0, ts.cap - (select count(*) from public.sandbox_changes c where c.member_id = me.id and c.created_at > now() - interval '24 hours' and not c.test)::integer)
               from public.table_sandbox ts where ts.table_id = t),
    'changes', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'words', c.words, 'status', c.status, 'summary', c.summary,
                  'verdict', c.verdict, 'note', c.note, 'request_id', c.request_id, 'created_at', c.created_at, 'finished_at', c.finished_at,
                  'undone', c.undone, 'did_not_build', public.same_commit(c.commit, sb.failed_sha))
                  order by c.created_at desc), '[]'::jsonb)
                  from (select * from public.sandbox_changes x where x.member_id = me.id and not x.test order by x.created_at desc limit 60) c));
end;
$$;

--
-- Name: client_say(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_say(t uuid, body text, files jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  words text := btrim(coalesce(body, ''));
  ai public.connections;
  sb public.sandboxes;
  line uuid;
  job uuid;
  seat uuid;
  change uuid;
  used integer;
  most integer;
  req uuid;
  has boolean := coalesce(jsonb_array_length(files), 0) > 0;
begin
  -- One of this person's messages at a time, so two sent together cannot both slip under a limit.
  -- Still at the table is checked again once the row is ours: taken off while this waited for it, they are not.
  select * into me from public.members where id = public.client_seat(t) and removed_at is null for update;
  if not found or me.role <> 'client' then
    raise exception 'only the client asks here';
  end if;
  if char_length(words) = 0 and not has then
    raise exception 'ask for something';
  end if;
  if char_length(words) = 0 then
    words := left((select string_agg(f ->> 'name', ', ') from jsonb_array_elements(files) f), 500);
  end if;
  if public.client_said_lately(me.id) + (select count(*) from public.sandbox_changes c where c.member_id = me.id and c.created_at > now() - interval '1 hour' and not c.test)::integer >= 60 then
    raise exception 'that is a lot of requests in one hour, try again a little later';
  end if;
  -- Something attached is for people to look at: it goes straight to the team as a request, with the files on it.
  if has then
    req := public.pass_on_request(me.id, words, null, null, true);
    perform public.take_files(t, me.id, files, (select r.message_id from public.requests r where r.id = req));
    update public.messages mm set meta = mm.meta || jsonb_build_object('files',
        (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'mime', a.mime, 'size', a.size, 'path', a.path, 'kind', a.kind) order by a.created_at), '[]'::jsonb)
           from public.attachments a where a.message_id = mm.id))
     where mm.id = (select r.message_id from public.requests r where r.id = req);
    update public.requests r set files = (select mm.meta -> 'files' from public.messages mm where mm.id = r.message_id) where r.id = req;
    return jsonb_build_object('request', req);
  end if;
  if char_length(words) > 4000 then
    raise exception 'that is a lot for one message; keep it under 4,000 characters';
  end if;

  -- A client with their own copy is answered by the team's assistant like anyone: it answers, looks at the project,
  -- sends a change on to their copy (runner_finish), or passes it to the team. It decides, not a word check.
  select * into sb from public.sandboxes where member_id = me.id and mode = 'sandbox';

  select * into ai from public.connections
   where member_id = me.id and revoked_at is null and last_seen > now() - interval '60 seconds'
   order by last_seen desc limit 1;
  if not found or sb.member_id is not null or coalesce((select cs.answered_by from public.client_settings cs where cs.member_id = me.id), 'own') = 'table' then
    -- The team's assistant answers, from what this client may know. With no team AI on, the words reach the team and
    -- wait for an AI, which answers the moment one comes on (answer_waiting_clients).
    seat := public.client_desk_seat(t);
    insert into public.client_lines (table_id, member_id, who, body, by_table, waiting) values (t, me.id, 'client', words, true, seat is null) returning id into line;
    if seat is null then
      -- Nobody's AI is on: the team still sees it in their chat at once, and an AI answers the client the moment one
      -- comes on.
      perform public.pass_on_request(me.id, words, null, line, false);
      return jsonb_build_object('line', line, 'waiting', true);
    end if;
    insert into public.jobs (table_id, member_id, kind, line_id, subject) values (t, seat, 'client', line, me.id) returning id into job;
    return jsonb_build_object('line', line, 'job', job);
  end if;
  insert into public.client_lines (table_id, member_id, who, body) values (t, me.id, 'client', words) returning id into line;
  insert into public.jobs (table_id, member_id, kind, line_id) values (t, me.id, 'client', line) returning id into job;
  return jsonb_build_object('line', line, 'job', job);
end;
$$;

--
-- Name: client_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_seat(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    (select m.id from public.members m where m.table_id = t and m.user_id = auth.uid() and m.removed_at is null and m.role = 'client'),
    (select x.id from public.members x where x.table_id = t and x.test and x.removed_at is null
       and exists (select 1 from public.members o where o.table_id = t and o.user_id = auth.uid() and o.removed_at is null and o.role = 'owner')));
$$;

--
-- Name: client_topic_is_mine(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_topic_is_mine(topic text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select case
    when topic ~ '^client:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    then exists (select 1 from public.members m
                  where m.table_id = substring(topic from 8 for 36)::uuid
                    and m.id = substring(topic from 45 for 36)::uuid
                    and m.user_id = auth.uid() and m.removed_at is null)
    else false
  end;
$_$;

--
-- Name: client_topic_table_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_topic_table_id(topic text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when topic ~ '^client:[0-9a-f-]{36}$' then substring(topic from 8)::uuid else null end;
$_$;

--
-- Name: client_undo_change(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.client_undo_change(t uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  ch public.sandbox_changes;
begin
  select * into me from public.members where id = public.client_seat(t);
  if not found or me.role <> 'client' or me.removed_at is not null then
    raise exception 'only the client changes their copy';
  end if;
  if exists (select 1 from public.sandbox_changes x where x.member_id = me.id and x.undone = 'undoing') then
    raise exception 'one is already being taken back';
  end if;
  select * into ch from public.sandbox_changes x
   where x.member_id = me.id and x.status = 'ready' and x.undone is null and not x.test and x.commit is not null
   order by x.created_at desc limit 1 for update;
  if not found then
    raise exception 'there is nothing to take back';
  end if;
  if not public.undo_in_copy(ch) then
    raise exception 'the team''s computers are off right now, so it cannot be taken back yet; try again in a while';
  end if;
  perform public.log_activity(t, me.id, 'sandbox.undo', ch.id, '{}'::jsonb);
  return ch.id;
end;
$$;

--
-- Name: clients_wrote(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clients_wrote(t uuid) RETURNS TABLE(client uuid, at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.id, x.at
    from public.members me
    join public.members c on c.table_id = me.table_id and c.role = 'client' and c.removed_at is null
    cross join lateral (select greatest(
      (select max(l.created_at) from public.client_lines l where l.member_id = c.id and l.who = 'client' and l.by_table),
      (select max(r.created_at) from public.requests r where r.member_id = c.id)) as at) x
    left join public.client_chat_reads seen on seen.member_id = me.id and seen.client_id = c.id
   where me.table_id = t and me.user_id = auth.uid() and me.removed_at is null and public.may(t, 'clients')
     and x.at > coalesce(seen.read_at, me.created_at)
   order by x.at;
$$;

--
-- Name: close_failed_tasks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_failed_tasks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.jobs set status = 'skipped', lease_until = null, error = 'its computer never picked it up'
   where kind in ('combine', 'answer') and task_id is not null
     and ((status = 'running' and lease_until < now() - interval '10 minutes')
       or (status = 'queued' and created_at < now() - interval '10 minutes'
           and not exists (select 1 from public.connections cn where cn.member_id = jobs.member_id
                            and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds')));
  -- A round whose table's answer is finished, given up on or failed has nothing left to wait for: what it still has
  -- open (a view nobody took) is closed with it, or it stayed queued for ever and kept its task "working". A step
  -- still waiting its turn is running nothing, so it goes at once; anything else only by the same rule as above: its
  -- lease long run out, or never taken while its computer is gone. A slow view whose AI is still at it is left.
  update public.jobs j set status = 'skipped', lease_until = null, error = 'the round was already over'
   where j.round is not null and j.status in ('queued', 'running', 'waiting') and j.kind <> 'combine'
     and exists (select 1 from public.jobs c where c.round = j.round and c.kind = 'combine' and c.status in ('done', 'failed', 'skipped'))
     and (j.status = 'waiting'
       or (j.status = 'running' and j.lease_until < now() - interval '10 minutes')
       or (j.status = 'queued' and j.created_at < now() - interval '10 minutes'
           and not exists (select 1 from public.connections cn where cn.member_id = j.member_id
                            and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds')));
  -- An introduction whose computer never took it, or stopped answering, is given up on the same way.
  update public.jobs set status = 'skipped', lease_until = null, error = 'its computer never picked it up'
   where kind = 'intro'
     and ((status = 'running' and lease_until < now() - interval '10 minutes')
       or (status = 'queued' and created_at < now() - interval '10 minutes'
           and not exists (select 1 from public.connections cn where cn.member_id = jobs.member_id
                            and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds')));
  update public.tasks t set status = 'stopped', finished_at = now()
   where t.status = 'working' and t.created_at < now() - interval '1 minute'
     and not exists (select 1 from public.jobs j where j.task_id = t.id and j.status in ('queued', 'running', 'waiting'))
     and not exists (select 1 from public.jobs w where w.task_id = t.id and w.round is not null and w.kind in ('plan', 'work')
                      and not exists (select 1 from public.jobs c where c.round = w.round and c.kind = 'combine'));
end;
$$;

--
-- Name: close_job_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_job_approvals() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status in ('done', 'failed', 'skipped') and old.status is distinct from new.status then
    update public.approvals set status = 'expired', decided_at = now() where job_id = new.id and status = 'waiting';
    -- The job's key dies with it.
    update public.jobs set approval_key = null where id = new.id and approval_key is not null;
  end if;
  return null;
end;
$$;

--
-- Name: close_sandbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_sandbox() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.jobs set status = 'skipped', lease_until = null, error = 'its computer never picked it up'
   where kind = 'sandbox'
     and ((status = 'running' and lease_until < now() - interval '10 minutes')
       or (status = 'queued' and created_at < now() - interval '10 minutes'
           and not exists (select 1 from public.connections cn where cn.member_id = jobs.member_id and cn.revoked_at is null
                            and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds')));
  update public.sandbox_changes c
     set status = case when exists (select 1 from public.jobs j where j.change_id = c.id and j.error like 'stopped by %') then 'stopped' else 'failed' end,
         finished_at = now(),
         summary = case when exists (select 1 from public.jobs j where j.change_id = c.id and j.error like 'stopped by %')
                        then 'The team stopped this one.' else 'This one did not get done. Try it again in a while.' end
   where c.status = 'working' and c.created_at < now() - interval '20 seconds'
     and not exists (select 1 from public.jobs j where j.change_id = c.id and j.status in ('queued', 'running', 'waiting'));
  -- Taking one back whose job is gone (its computer went away): nothing came out, so it can be asked again.
  update public.sandbox_changes c set undone = null
   where c.undone = 'undoing'
     and not exists (select 1 from public.jobs j where j.change_id = c.id and j.brief = 'undo' and j.status in ('queued', 'running', 'waiting'));
end;
$$;

--
-- Name: comment_page(uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comment_page(p uuid, body text, anchor text DEFAULT ''::text, parent uuid DEFAULT NULL::uuid, to_ai boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
  me uuid := public.my_member_id(pg.table_id);
  words text := btrim(coalesce(body, ''));
  picked text := left(btrim(coalesce(anchor, '')), 300);
  made uuid;
begin
  if char_length(words) = 0 or char_length(words) > 4000 then
    raise exception 'a comment is between 1 and 4,000 characters';
  end if;
  if parent is not null and not exists (select 1 from public.page_comments where page_comments.id = parent and page_id = pg.id) then
    raise exception 'that reply is not to a comment on this page';
  end if;
  if (select count(*) from public.page_comments where member_id = me and created_at > now() - interval '1 hour') >= 120 then
    raise exception 'that is a lot of comments for one hour; try again a little later';
  end if;
  insert into public.page_comments (page_id, table_id, member_id, parent_id, version, anchor, body, to_ai)
    values (pg.id, pg.table_id, me, parent, pg.version, picked, words, to_ai)
    returning page_comments.id into made;
  update public.pages set touched_at = now() where pages.id = pg.id;
  if to_ai then
    perform public.ask_table(pg.chat_id, left(format('On the handout "%s"%s: %s', pg.title,
      case when picked <> '' then format(', where it says "%s"', picked) else '' end, words), 8000), '[]'::jsonb);
  end if;
  return made;
end;
$$;

--
-- Name: connect_github(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_github(t uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  raw text := encode(extensions.gen_random_bytes(24), 'hex');
begin
  if not public.may(t, 'settings') then
    raise exception 'only the owner connects GitHub';
  end if;
  insert into public.github_hooks (table_id, secret) values (t, raw)
    on conflict (table_id) do update set secret = excluded.secret, repo = '', last_event_at = null;
  perform public.log_activity(t, public.my_member_id(t), 'github.connected', t, '{}'::jsonb);
  return raw;
end;
$$;

--
-- Name: connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    member_id uuid NOT NULL,
    kind text NOT NULL,
    token_hash text NOT NULL,
    label text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen timestamp with time zone,
    revoked_at timestamp with time zone,
    limits jsonb DEFAULT '{}'::jsonb NOT NULL,
    limits_at timestamp with time zone,
    model_choice text,
    open_paths boolean DEFAULT true NOT NULL,
    share_paths boolean DEFAULT true NOT NULL,
    commands jsonb DEFAULT '[]'::jsonb NOT NULL,
    effort text,
    fast boolean DEFAULT false NOT NULL,
    full_claude boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'auto'::text,
    in_folder boolean DEFAULT true NOT NULL,
    push_anywhere boolean DEFAULT false NOT NULL,
    use_repo text,
    browser boolean DEFAULT false NOT NULL,
    local jsonb,
    CONSTRAINT connections_effort_check CHECK ((effort = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'xhigh'::text, 'max'::text]))),
    CONSTRAINT connections_kind_check CHECK ((kind = ANY (ARRAY['claude'::text, 'codex'::text]))),
    CONSTRAINT connections_label_check CHECK ((char_length(label) <= 80)),
    CONSTRAINT connections_mode_check CHECK ((mode = ANY (ARRAY['manual'::text, 'acceptEdits'::text, 'auto'::text, 'plan'::text, 'bypass'::text])))
);

--
-- Name: connection_for(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connection_for(token text) RETURNS public.connections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections;
begin
  select * into c from public.connections
    where token_hash = encode(extensions.digest(token, 'sha256'), 'hex') and revoked_at is null;
  if not found or exists (select 1 from public.members m where m.id = c.member_id and m.removed_at is not null) then
    raise exception 'this connection was removed; connect again from Longtable';
  end if;
  if c.last_seen is null or c.last_seen < now() - interval '15 seconds' then
    update public.connections set last_seen = now()
     where id = (select id from public.connections where id = c.id for update skip locked);
  end if;
  return c;
end;
$$;

--
-- Name: copy_builder(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_builder(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select ts.builder from public.table_sandbox ts
    join public.members m on m.id = ts.builder and m.table_id = t and m.role in ('owner', 'developer') and m.removed_at is null
   where ts.table_id = t;
$$;

--
-- Name: copy_jobs_go_to_builder(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_jobs_go_to_builder() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  b uuid := public.copy_builder(new.table_id);
begin
  if b is not null then
    new.member_id := b;
  end if;
  return new;
end;
$$;

--
-- Name: copy_seat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_seat(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select cn.member_id
    from public.connections cn join public.members mem on mem.id = cn.member_id and mem.role in ('owner', 'developer') and mem.removed_at is null
   where cn.table_id = t and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
     and (public.copy_builder(t) is null or cn.member_id = public.copy_builder(t))
   order by (cn.member_id = public.final_seat_now(t)) desc, cn.created_at limit 1;
$$;

--
-- Name: create_chat(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_chat(t uuid, chat_name text, chat_about text DEFAULT ''::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c uuid;
  me uuid := public.my_member_id(t);
begin
  if not public.is_team(t) then
    raise exception 'only the team can make chats';
  end if;
  if char_length(btrim(coalesce(chat_name, ''))) not between 1 and 60 then
    raise exception 'a chat needs a name of up to 60 characters';
  end if;
  if char_length(btrim(coalesce(chat_about, ''))) > 140 then
    raise exception 'what a chat is about takes up to 140 characters';
  end if;
  insert into public.chats (table_id, name, about, created_by) values (t, btrim(chat_name), btrim(coalesce(chat_about, '')), me)
    returning id into c;
  perform public.log_activity(t, me, 'chat.created', c, jsonb_build_object('name', btrim(chat_name)));
  return c;
end;
$$;

--
-- Name: create_decision(uuid, text, text, text, boolean, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_decision(c uuid, title text, context text, origin text, affects_client boolean, options jsonb, request uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid;
  d uuid;
  me uuid;
  n int := jsonb_array_length(coalesce(options, '[]'::jsonb));
  tells boolean := coalesce(affects_client, false) or request is not null;
  i int;
  o jsonb;
  asking boolean;
  answers text[];
  questions int := 0;
begin
  -- The chat is held while the decision is made, so one deleted at that very moment refuses it in words.
  select ch.table_id into t from public.chats ch where ch.id = c for share;
  if t is null or not public.can_see_chat(c) then
    raise exception 'only the team can ask for a decision';
  end if;
  if n < 2 or n > 4 then
    raise exception 'a decision needs two to four options';
  end if;
  if char_length(btrim(coalesce(title, ''))) not between 1 and 140 then
    raise exception 'a decision needs a title of up to 140 characters';
  end if;
  if request is not null and not exists (select 1 from public.requests r where r.id = request and r.table_id = t) then
    raise exception 'that request is not at this table';
  end if;
  me := public.my_member_id(t);
  insert into public.decisions (table_id, chat_id, title, context, origin, affects_client, created_by, request_id)
    values (t, c, btrim(title), btrim(coalesce(context, '')), btrim(coalesce(origin, '')), tells, me, request)
    returning id into d;
  for i in 0 .. n - 1 loop
    o := options -> i;
    asking := coalesce((o ->> 'asks_client')::boolean, false);
    answers := '{}';
    if asking then
      questions := questions + 1;
      if not tells then
        raise exception 'only a decision the client hears can ask them a question';
      end if;
      -- Answered once, by one client, for their own request: a question to "every client" would be one answer
      -- every client reads.
      if request is null then
        raise exception 'a question for the client has to be about one of their requests';
      end if;
      if btrim(coalesce(o ->> 'client_words', '')) = '' then
        raise exception 'write the question the client will be asked';
      end if;
      select coalesce(array_agg(btrim(x) order by ord), '{}') into answers
        from jsonb_array_elements_text(coalesce(o -> 'replies', '[]'::jsonb)) with ordinality as e(x, ord)
       where btrim(x) <> '';
      if cardinality(answers) not between 2 and 4 or exists (select 1 from unnest(answers) x where char_length(x) > 60) then
        raise exception 'a question for the client needs two to four short answers';
      end if;
      if (select count(distinct lower(x)) from unnest(answers) x) <> cardinality(answers) then
        raise exception 'the answers to a question must differ';
      end if;
    end if;
    insert into public.decision_options (decision_id, position, label, recommended, client_words, asks_client, replies)
      values (d, i + 1, btrim(o ->> 'label'), coalesce((o ->> 'recommended')::boolean, false),
              case when tells then btrim(coalesce(o ->> 'client_words', '')) else '' end, asking, answers);
  end loop;
  if questions > 1 then
    raise exception 'a decision can ask the client one question';
  end if;
  -- A new request, a follow-up on one already decided, or one the client has just answered goes back to being
  -- decided. One waiting on the client's answer, planned, ready to try or done keeps its status.
  if request is not null then
    update public.requests set status = 'being decided', updated_at = now()
     where id = request and status in ('asked', 'decided', 'answered');
    if found then
      perform public.add_request_event(request, 'The team is deciding');
    end if;
  end if;
  perform public.log_activity(t, me, 'decision.created', d, jsonb_build_object('title', btrim(title)));
  return d;
end;
$$;

--
-- Name: create_invite(uuid, public.member_role, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invite(t uuid, invite_role public.member_role, invite_name text DEFAULT ''::text, invite_email text DEFAULT ''::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  raw text;
  inv uuid;
begin
  if not public.may(t, 'invite') then
    raise exception 'only the owner can invite';
  end if;
  if public.table_is_locked(t) then
    raise exception 'This table is locked. An owner can unlock it in Settings, People.';
  end if;
  if invite_role = 'owner' then
    raise exception 'invite them as a developer, then make them a co-owner';
  end if;
  if btrim(coalesce(invite_email, '')) <> '' and btrim(invite_email) !~ '^[^\s@]+@[^\s@]+\.[^\s@]+$' then
    raise exception 'that email does not look right';
  end if;
  raw := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.invites (table_id, role, token_hash, created_by, name, email)
    values (t, invite_role, encode(extensions.digest(raw, 'sha256'), 'hex'), auth.uid(),
            left(btrim(coalesce(invite_name, '')), 60), left(lower(btrim(coalesce(invite_email, ''))), 200))
    returning id into inv;
  perform public.log_activity(t, public.my_member_id(t), 'invite.created', inv,
    jsonb_build_object('role', invite_role, 'name', left(btrim(coalesce(invite_name, '')), 60)));
  return raw;
end;
$_$;

--
-- Name: cursor_topic_table_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cursor_topic_table_id(topic text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when topic ~ '^cursor:[0-9a-f-]{36}$' then substring(topic from 8)::uuid else null end;
$_$;

--
-- Name: decide(uuid, smallint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide(d uuid, choice smallint) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dec public.decisions;
  wait integer;
  me uuid;
begin
  select * into dec from public.decisions where id = d for update;
  if not found or not public.can_see_chat(dec.chat_id) then
    raise exception 'only the team can decide';
  end if;
  if dec.status <> 'open' then
    raise exception 'this decision is already made';
  end if;
  if not exists (select 1 from public.decision_options where decision_id = d and position = choice) then
    raise exception 'that option does not exist';
  end if;
  select undo_seconds into wait from public.tables where id = dec.table_id;
  me := public.my_member_id(dec.table_id);
  update public.decisions
     set status = 'decided', chosen = choice, decided_by = me, decided_at = now(),
         deliver_after = now() + make_interval(secs => wait)
   where id = d;
  perform public.log_activity(dec.table_id, me, 'decision.decided', d,
    jsonb_build_object('title', dec.title, 'option', (select label from public.decision_options where decision_id = d and position = choice)));
  return now() + make_interval(secs => wait);
end;
$$;

--
-- Name: decide_and_send(uuid, smallint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_and_send(d uuid, choice smallint, words text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dec public.decisions;
  opt public.decision_options;
  me uuid;
  said text := btrim(coalesce(words, ''));
begin
  select * into dec from public.decisions where id = d for update;
  if not found or not public.can_see_chat(dec.chat_id) then
    raise exception 'only the team can decide';
  end if;
  if dec.status <> 'open' then
    raise exception 'this decision is already made';
  end if;
  select * into opt from public.decision_options where decision_id = d and position = choice;
  if not found then
    raise exception 'that option does not exist';
  end if;
  if dec.affects_client then
    if said = '' then
      said := btrim(opt.client_words);
    end if;
    if said = '' then
      raise exception 'write what the client will be told';
    end if;
    if char_length(said) > 2000 then
      raise exception 'what the client is told can be at most 2000 characters';
    end if;
    update public.decision_options set client_words = said where decision_id = d and position = choice;
  end if;
  me := public.my_member_id(dec.table_id);
  update public.decisions
     set status = 'decided', chosen = choice, decided_by = me, decided_at = now(), deliver_after = now()
   where id = d;
  perform public.log_activity(dec.table_id, me, 'decision.decided', d,
    jsonb_build_object('title', dec.title, 'option', opt.label, 'edited', dec.affects_client and said <> btrim(opt.client_words)));
  -- Out now, not on the scheduler's next beat.
  perform public.deliver_due();
end;
$$;

--
-- Name: decide_approval(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_approval(a uuid, allow boolean, always_allow boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r public.approvals;
begin
  select * into r from public.approvals where id = a for update;
  if not found or r.member_id <> public.my_member_id(r.table_id) then
    raise exception 'only the person whose AI asked can answer';
  end if;
  if r.kind = 'question' then
    raise exception 'that is a question; answer it with words';
  end if;
  if r.status <> 'waiting' then
    raise exception 'this request was already answered, or its work has ended';
  end if;
  update public.approvals set status = case when allow then 'allowed' else 'denied' end,
    always = allow and coalesce(always_allow, false), decided_at = now() where id = a;
  perform realtime.send(jsonb_build_object('table', 'approvals', 'record', jsonb_build_object('id', a, 'member_id', r.member_id)),
    'UPDATE', 'team:' || r.table_id::text, true);
end;
$$;

--
-- Name: delete_chat(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_chat(c uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.chats;
  me uuid;
begin
  -- The chat is held first, so a decision being made in it at this moment (which holds it too) finishes before the
  -- requests below are read, and its request is seen and sent back like any other.
  select * into ch from public.chats where id = c for update;
  if not found or not public.can_see_chat(c) then
    raise exception 'only the team can delete a chat';
  end if;
  me := public.my_member_id(ch.table_id);
  if ch.is_general then
    raise exception 'the General chat stays';
  end if;
  if not (public.is_owner(ch.table_id) or ch.created_by = me) then
    raise exception 'only the owner or the person who made this chat can delete it';
  end if;
  -- The chat's decisions are held next, before any request: the clock that delivers a decision holds the decision
  -- and then its request, and taking the two the other way round let a delivery and a deletion wait on each other.
  perform 1 from public.decisions where chat_id = c for update;
  -- A request the team was deciding only in this chat goes back to waiting for them: its decision goes with the chat.
  update public.requests r set status = 'asked', updated_at = now()
   where r.status = 'being decided'
     and exists (select 1 from public.decisions d where d.request_id = r.id and d.chat_id = c)
     and not exists (select 1 from public.decisions d where d.request_id = r.id and d.chat_id <> c);
  delete from public.chats where id = c;
  perform public.log_activity(ch.table_id, me, 'chat.deleted', c, jsonb_build_object('name', ch.name));
  -- Everyone at the table sees it go.
  perform realtime.send(jsonb_build_object('table', 'chats', 'record', jsonb_build_object('id', c, 'deleted', true)),
    'UPDATE', 'team:' || ch.table_id::text, true);
end;
$$;

--
-- Name: delete_page(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_page(p uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
begin
  if pg.made_by is distinct from public.my_member_id(pg.table_id) and not public.is_owner(pg.table_id) then
    raise exception 'only the person whose AI made a page, or the owner, deletes it';
  end if;
  delete from public.pages where id = pg.id;
end;
$$;

--
-- Name: delete_page_comment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_page_comment(cm uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  x public.page_comments;
begin
  select * into x from public.page_comments where id = cm;
  if not found or not exists (select 1 from public.pages p where p.id = x.page_id and public.can_see_chat(p.chat_id)) then
    raise exception 'that comment is not at a table you are on';
  end if;
  if x.member_id is distinct from public.my_member_id(x.table_id) and not public.is_owner(x.table_id) then
    raise exception 'only whoever wrote a comment, or the owner, takes it away';
  end if;
  update public.page_comments set deleted_at = now(), body = '', anchor = '' where id = cm;
end;
$$;

--
-- Name: delete_table(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_table(t uuid, confirm_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  n text;
begin
  if not public.is_main_owner(t) then
    raise exception 'only the main owner deletes the table';
  end if;
  select name into n from public.tables where id = t;
  if btrim(coalesce(confirm_name, '')) <> n then
    raise exception 'type the table''s name exactly to delete it';
  end if;
  perform set_config('longtable.deleting_table', 'on', true);
  delete from public.tables where id = t;
end;
$$;

--
-- Name: deliver_due(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deliver_due() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dec public.decisions;
  words text;
  asking boolean;
  answers text[];
  n integer := 0;
begin
  for dec in
    select * from public.decisions
     where status = 'decided' and delivered_at is null and deliver_after <= now()
     order by deliver_after
     for update skip locked
  loop
    select btrim(client_words), asks_client, replies into words, asking, answers
      from public.decision_options where decision_id = dec.id and position = dec.chosen;
    if dec.affects_client and coalesce(words, '') <> '' then
      insert into public.client_updates (table_id, decision_id, request_id, body, replies)
        values (dec.table_id, dec.id, dec.request_id, words, case when asking then answers else '{}' end);
    end if;
    if dec.request_id is not null then
      if asking then
        update public.requests set status = 'question', updated_at = now() where id = dec.request_id;
        perform public.add_request_event(dec.request_id, 'The team has a question for you');
      else
        update public.requests set status = 'decided', updated_at = now() where id = dec.request_id;
        perform public.add_request_event(dec.request_id, coalesce(nullif(words, ''), 'The team decided'));
      end if;
    end if;
    update public.decisions set delivered_at = now() where id = dec.id;
    perform public.log_activity(dec.table_id, null, 'decision.delivered', dec.id,
      jsonb_build_object('title', dec.title, 'told_client', dec.affects_client, 'asked_client', coalesce(asking, false)));
    n := n + 1;
  end loop;
  return n;
end;
$$;

--
-- Name: disconnect(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disconnect(conn uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cn public.connections;
begin
  select * into cn from public.connections where id = conn for update;
  if not found or not (cn.member_id = public.my_member_id(cn.table_id) or public.is_owner(cn.table_id)) then
    raise exception 'not yours to disconnect';
  end if;
  update public.connections set revoked_at = now() where id = conn and revoked_at is null;
  -- Nothing of theirs is left looking busy, unless another connection of theirs is still on.
  if not exists (select 1 from public.connections x where x.member_id = cn.member_id and x.revoked_at is null) then
    -- A client's question it was answering is passed on to the team, not dropped with the connection.
    perform public.give_up_client_job(j.id, 'its AI was disconnected')
       from public.jobs j where j.member_id = cn.member_id and j.kind = 'client' and j.status in ('queued', 'running');
    update public.jobs set status = 'failed', error = 'its AI was disconnected', lease_until = null, finished_at = now()
     where member_id = cn.member_id and status in ('queued', 'running', 'waiting');
  end if;
  perform public.log_activity(cn.table_id, public.my_member_id(cn.table_id), 'connection.removed', conn, jsonb_build_object('kind', cn.kind));
end;
$$;

--
-- Name: disconnect_github(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.disconnect_github(t uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.may(t, 'settings') then
    raise exception 'only the owner disconnects GitHub';
  end if;
  delete from public.github_hooks where table_id = t;
  perform public.log_activity(t, public.my_member_id(t), 'github.disconnected', t, '{}'::jsonb);
end;
$$;

--
-- Name: edit_page(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_page(p uuid, html text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
  me uuid := public.my_member_id(pg.table_id);
begin
  if char_length(coalesce(html, '')) = 0 or char_length(html) > 2000000 then
    raise exception 'a page is between 1 character and 2,000,000';
  end if;
  if (select count(*) from public.page_versions v where v.made_by = me and not v.by_ai and v.created_at > now() - interval '1 hour') >= 60 then
    raise exception 'that is a lot of changes in an hour: try again in a little while';
  end if;
  update public.pages set version = version + 1, touched_at = now() where id = pg.id returning * into pg;
  insert into public.page_versions (page_id, table_id, n, html, made_by, by_ai, note)
    values (pg.id, pg.table_id, pg.version, public.hide_secrets(html), me, false, 'Edited by hand');
  return pg.version;
end;
$$;

--
-- Name: export_mine(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_mine(t uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
begin
  select * into me from public.members where table_id = t and user_id = auth.uid() and removed_at is null;
  if not found then
    raise exception 'you are not at this table';
  end if;
  return jsonb_build_object(
    'exported_at', now(),
    'table', (select name from public.tables where id = t),
    'you', jsonb_build_object('name', me.display_name, 'role', me.role, 'joined', me.created_at),
    'your_messages', (select coalesce(jsonb_agg(jsonb_build_object('at', m.created_at, 'body', m.body, 'kind', m.kind) order by m.created_at), '[]')
                       from public.messages m where m.member_id = me.id and not m.by_ai),
    'your_requests', (select coalesce(jsonb_agg(jsonb_build_object('at', r.created_at, 'title', r.title, 'body', r.body, 'status', r.status,
                        'timeline', (select coalesce(jsonb_agg(e.label order by e.id), '[]') from public.request_events e where e.request_id = r.id))
                       order by r.created_at), '[]') from public.requests r where r.member_id = me.id),
    'told_you', (select coalesce(jsonb_agg(jsonb_build_object('at', u.created_at, 'words', u.body, 'your_answer', u.answer) order by u.created_at), '[]')
                  from public.client_updates u where me.role = 'client' and u.table_id = t
                   and (u.request_id is null or exists (select 1 from public.requests r where r.id = u.request_id and r.member_id = me.id))),
    'your_chat_with_your_ai', (select coalesce(jsonb_agg(jsonb_build_object('at', l.created_at, 'who', l.who, 'body', l.body) order by l.created_at), '[]')
                                from public.client_lines l where l.member_id = me.id));
end;
$$;

--
-- Name: export_table(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_table(t uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.is_owner(t) then
    raise exception 'only the owner downloads the whole table';
  end if;
  return jsonb_build_object(
    'exported_at', now(),
    'table', (select to_jsonb(x) - 'created_by' from public.tables x where x.id = t),
    'people', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'name', m.display_name, 'role', m.role,
                 'joined', m.created_at, 'removed', m.removed_at) order by m.created_at), '[]') from public.members m where m.table_id = t),
    'chats', (select coalesce(jsonb_agg(to_jsonb(c) - 'search' order by c.created_at), '[]') from public.chats c where c.table_id = t and public.can_see_chat(c.id)),
    'messages', (select coalesce(jsonb_agg(to_jsonb(m) - 'search' order by m.created_at), '[]') from public.messages m where m.table_id = t and public.can_see_chat(m.chat_id)),
    'decisions', (select coalesce(jsonb_agg(to_jsonb(d) || jsonb_build_object('options',
                    (select coalesce(jsonb_agg(to_jsonb(o) order by o.position), '[]') from public.decision_options o where o.decision_id = d.id))
                  order by d.created_at), '[]') from public.decisions d where d.table_id = t and public.can_see_chat(d.chat_id)),
    'requests', (select coalesce(jsonb_agg(to_jsonb(r) || jsonb_build_object('timeline',
                   (select coalesce(jsonb_agg(e.label order by e.id), '[]') from public.request_events e where e.request_id = r.id))
                 order by r.created_at), '[]') from public.requests r where r.table_id = t),
    'told_clients', (select coalesce(jsonb_agg(to_jsonb(u) order by u.created_at), '[]') from public.client_updates u where u.table_id = t),
    'notes', (select coalesce(jsonb_agg(to_jsonb(n) order by n.created_at), '[]') from public.notes n where n.table_id = t),
    -- Pages: each with every version and every comment.
    'pages', (select coalesce(jsonb_agg(to_jsonb(p) || jsonb_build_object(
                'versions', (select coalesce(jsonb_agg(jsonb_build_object('n', v.n, 'html', v.html, 'note', v.note, 'by_ai', v.by_ai, 'made_by', v.made_by, 'at', v.created_at) order by v.n), '[]') from public.page_versions v where v.page_id = p.id),
                'comments', (select coalesce(jsonb_agg(to_jsonb(c) order by c.created_at), '[]') from public.page_comments c where c.page_id = p.id and c.deleted_at is null))
              order by p.created_at), '[]') from public.pages p where p.table_id = t and public.can_see_chat(p.chat_id)),
    'activity', (select coalesce(jsonb_agg(to_jsonb(a) order by a.created_at), '[]') from public.activity a where a.table_id = t and public.log_line_visible(a.table_id, a.chat_id)));
end;
$$;

--
-- Name: file_in_hidden_room(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_in_hidden_room(path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.attachments a left join public.messages m on m.id = a.message_id left join public.jobs j on j.id = a.job_id
                  where a.path = file_in_hidden_room.path
                    and ((m.chat_id is not null and not public.can_see_chat(m.chat_id)) or (j.chat_id is not null and not public.can_see_chat(j.chat_id))));
$$;

--
-- Name: final_seat_now(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.final_seat_now(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select cn.member_id
    from public.connections cn
    join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer')
    join public.tables tb on tb.id = cn.table_id
   where cn.table_id = t and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds'
   order by (cn.member_id = coalesce(tb.final_seat, tb.main_owner)) desc, cn.created_at
   limit 1;
$$;

--
-- Name: forget_client_told(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_client_told() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.role = 'client' then
    delete from public.client_updates u using public.requests r where r.id = u.request_id and r.member_id = old.id;
    update public.decisions d set affects_client = false
      from public.requests r where r.id = d.request_id and r.member_id = old.id and d.delivered_at is null;
  end if;
  return old;
end;
$$;

--
-- Name: forget_commands_on_end(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forget_commands_on_end() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.revoked_at is not null then
    new.commands := '[]'::jsonb;
  end if;
  return new;
end;
$$;

--
-- Name: free_bubble(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.free_bubble(t uuid) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c from unnest(array['rose', 'peach', 'sand', 'lime', 'mint', 'teal', 'sky', 'blue', 'iris', 'lilac', 'pink', 'stone']) c
   where not exists (select 1 from public.members m where m.table_id = t and m.bubble = c and m.removed_at is null)
   order by random() limit 1;
$$;

--
-- Name: github_event(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.github_event(t uuid, signature text, event text, payload text, delivery text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  cmp_key bytea := extensions.gen_random_bytes(32);
  h public.github_hooks;
  p jsonb;
  line text;
  general uuid;
  owner_id uuid;
  ref text;
  n int;
  sha text;
  built uuid;
  asked text;
begin
  select * into h from public.github_hooks where table_id = t;
  if not found or signature is null
     -- Compared in constant time: both sides are hashed again under a key made fresh for this one comparison, so how
     -- long it takes says nothing about how much of a forged signature was right.
     or extensions.hmac(convert_to(signature, 'utf8'), cmp_key, 'sha256')
        <> extensions.hmac(convert_to('sha256=' || encode(extensions.hmac(convert_to(coalesce(payload, ''), 'utf8'), convert_to(h.secret, 'utf8'), 'sha256'), 'hex'), 'utf8'), cmp_key, 'sha256') then
    return 'refused';
  end if;
  begin
    p := payload::jsonb;
  exception when others then
    return 'refused';
  end;
  -- The same delivery a second time is a replay: it is ignored. Deliveries are remembered for a day.
  if coalesce(delivery, '') <> '' then
    delete from public.github_deliveries where at < now() - interval '1 day';
    insert into public.github_deliveries (table_id, delivery) values (t, left(delivery, 100)) on conflict do nothing;
    if not found then
      return 'ignored';
    end if;
  end if;
  update public.github_hooks set last_event_at = now(), repo = coalesce(p #>> '{repository,full_name}', repo) where table_id = t;

  if event = 'ping' then
    line := 'GitHub is connected' || coalesce(' to ' || (p #>> '{repository,full_name}'), '') || '.';
  elsif event = 'push' then
    ref := regexp_replace(coalesce(p ->> 'ref', ''), '^refs/heads/', '');
    if ref <> coalesce(p #>> '{repository,default_branch}', 'main') then
      return 'ignored';
    end if;
    n := jsonb_array_length(coalesce(p -> 'commits', '[]'::jsonb));
    if n = 0 then
      return 'ignored';
    end if;
    line := coalesce(p #>> '{pusher,name}', 'Someone') || ' pushed ' || n || case when n = 1 then ' commit' else ' commits' end
      || ' to ' || ref || ': ' || left(split_part(coalesce(p #>> '{head_commit,message}', ''), E'\n', 1), 140);
  elsif event = 'pull_request' then
    if p ->> 'action' = 'opened' then
      line := coalesce(p #>> '{pull_request,user,login}', 'Someone') || ' opened pull request #' || (p #>> '{pull_request,number}')
        || ': ' || left(coalesce(p #>> '{pull_request,title}', ''), 140);
    elsif p ->> 'action' = 'closed' and (p #>> '{pull_request,merged}')::boolean then
      line := 'Pull request #' || (p #>> '{pull_request,number}') || ' was merged: ' || left(coalesce(p #>> '{pull_request,title}', ''), 140);
    else
      return 'ignored';
    end if;
  elsif event = 'deployment_status' then
    -- Which client's copy this build is of: by its branch, or by a commit pushed to it.
    sha := coalesce(p #>> '{deployment,sha}', '');
    select s.member_id into built from public.sandboxes s
     where s.table_id = t
       and (s.branch = p #>> '{deployment,ref}' or public.same_commit(s.tip, sha)
            or exists (select 1 from public.sandbox_changes c where c.member_id = s.member_id and public.same_commit(c.commit, sha)))
     limit 1;
    if built is null then
      return 'ignored';
    end if;
    if p #>> '{deployment_status,state}' = 'success' then
      -- Online: where it opens (when the hosting says), and that this commit is the one people now see.
      update public.sandboxes s
         set url = case when coalesce(p #>> '{deployment_status,environment_url}', p #>> '{deployment_status,target_url}', '') ~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~/-]*)?$'
                        then left(coalesce(p #>> '{deployment_status,environment_url}', p #>> '{deployment_status,target_url}'), 300) else s.url end,
             live_sha = case when sha ~ '^[0-9a-f]{7,40}$' then sha else s.live_sha end, deploys_seen = true
       where s.member_id = built;
      return 'noted';
    elsif p #>> '{deployment_status,state}' in ('failure', 'error') and sha ~ '^[0-9a-f]{7,40}$' then
      -- It did not build: the client is told in plain words on their change, and the team hears it in General.
      update public.sandboxes s set failed_sha = sha, deploys_seen = true where s.member_id = built;
      select c.words into asked from public.sandbox_changes c where c.member_id = built and public.same_commit(c.commit, sha) order by c.created_at desc limit 1;
      line := (select split_part(m.display_name, ' ', 1) from public.members m where m.id = built) || '''s copy did not build'
        || coalesce(' after "' || left(regexp_replace(asked, '\s+', ' ', 'g'), 80) || '"', '') || '. Their copy still shows the version before it.';
    elsif p #>> '{deployment_status,state}' in ('pending', 'queued', 'in_progress') then
      update public.sandboxes s set deploys_seen = true where s.member_id = built;
      return 'noted';
    else
      return 'ignored';
    end if;
  elsif event = 'workflow_run' then
    if p ->> 'action' <> 'completed' or p #>> '{workflow_run,conclusion}' <> 'failure' then
      return 'ignored';
    end if;
    line := 'CI failed on ' || coalesce(p #>> '{workflow_run,head_branch}', 'a branch') || ': '
      || left(coalesce(p #>> '{workflow_run,name}', 'a workflow'), 80);
  else
    return 'ignored';
  end if;

  select c.id into general from public.chats c where c.table_id = t and c.is_general;
  select m.id into owner_id from public.members m where m.table_id = t and m.role = 'owner';
  insert into public.messages (table_id, chat_id, member_id, body, kind, meta)
    values (t, general, owner_id, public.hide_secrets(line), 'github', jsonb_build_object('event', event));
  return 'posted';
end;
$_$;

--
-- Name: github_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.github_status(t uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case when public.is_team(t) then
    (select jsonb_build_object('connected', true, 'repo', h.repo, 'last_event_at', h.last_event_at)
       from public.github_hooks h where h.table_id = t)
  end;
$$;

--
-- Name: give_bubble(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_bubble() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.bubble is null then
    new.bubble := public.free_bubble(new.table_id);
  end if;
  return new;
end;
$$;

--
-- Name: give_up_client_job(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.give_up_client_job(job uuid, reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs;
  line public.client_lines;
  req uuid;
begin
  select * into j from public.jobs where id = job and kind = 'client' for update;
  if not found or j.status in ('done', 'failed') then
    return;
  end if;
  update public.jobs set status = 'failed', error = public.kept_line(reason, 500), lease_until = null, finished_at = now() where id = j.id;
  select * into line from public.client_lines where id = j.line_id;
  -- The team's assistant: handed to the next team AI that is on, up to three tries, before it becomes a request.
  if j.subject is not null and (select count(*) from public.jobs x where x.line_id = j.line_id) < 3 then
    -- The team sees it now, if it has not yet; the next team AI that is on answers the client.
    if line.request_id is null then
      perform public.pass_on_request(j.subject, line.body, null, line.id, false);
    end if;
    update public.client_lines set waiting = true where id = line.id;
    return;
  end if;
  req := public.pass_on_request(coalesce(j.subject, j.member_id), line.body, null, line.id, false);
  insert into public.client_lines (table_id, member_id, who, body, request_id, by_table)
    values (j.table_id, coalesce(j.subject, j.member_id), 'assistant', 'Passed on to the team, since I could not answer that just now. You will hear here what they decide.', req, j.subject is not null);
end;
$$;

--
-- Name: hear_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hear_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.by_ai or new.no_ai or new.kind <> 'chat' or coalesce(current_setting('longtable.asked', true), '') = '1' then
    return null;
  end if;
  if public.final_seat_now(new.table_id) is null then
    return null;
  end if;
  if exists (select 1 from public.chats ch where ch.id = new.chat_id and (not ch.set_up or ch.answers in ('silent', 'off'))) then
    return null;
  end if;
  insert into public.listens (chat_id, table_id, since, due_at)
    values (new.chat_id, new.table_id, new.created_at, now() + interval '1.5 seconds')
    on conflict (chat_id) do update set due_at = excluded.due_at, since = least(public.listens.since, excluded.since);
  return null;
end;
$$;

--
-- Name: hide_secrets(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hide_secrets(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(t,
    '(sk-ant-[A-Za-z0-9_-]{8,}|sb_secret_[A-Za-z0-9_-]{8,}|sb_publishable_[A-Za-z0-9_-]{8,}|ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}|AKIA[0-9A-Z]{16}|eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}|-----BEGIN [A-Z ]*PRIVATE KEY-----|sk-(proj|svcacct|admin)-[A-Za-z0-9_-]{16,}|sk-[A-Za-z0-9]{32,}|[sr]k_(live|test)_[A-Za-z0-9]{16,}|whsec_[A-Za-z0-9]{16,}|re_[A-Za-z0-9]{8,}_[A-Za-z0-9]{16,}|xox[abprs]-[A-Za-z0-9-]{10,}|npm_[A-Za-z0-9]{30,}|AIza[0-9A-Za-z_-]{35}|gh[ousr]_[A-Za-z0-9]{30,}|glpat-[A-Za-z0-9_-]{20,})',
    '[hidden]', 'g');
$$;

--
-- Name: i_am_here(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.i_am_here(t uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  m uuid := public.my_member_id(t);
begin
  if m is null then return; end if;
  insert into public.member_seen (member_id, table_id, at) values (m, t, now())
    on conflict (member_id) do update set at = now() where public.member_seen.at < now() - interval '30 seconds';
end;
$$;

--
-- Name: invite_preview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invite_preview(token text) RETURNS TABLE(table_name text, role public.member_role, expired boolean, used boolean, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select t.name, i.role, i.expires_at < now(), i.used_at is not null, i.name
  from public.invites i
  join public.tables t on t.id = i.table_id
  where i.token_hash = encode(extensions.digest(token, 'sha256'), 'hex');
$$;

--
-- Name: is_main_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_main_owner(t uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.members m join public.tables tb on tb.id = m.table_id and tb.main_owner = m.id
                 where m.table_id = t and m.user_id = auth.uid() and m.role = 'owner' and m.removed_at is null);
$$;

--
-- Name: is_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_member(t uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.members m where m.table_id = t and m.user_id = auth.uid() and m.removed_at is null);
$$;

--
-- Name: is_operator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_operator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- The address must be one this sign-in really confirmed, never just what the sign-in claims.
  select exists (select 1 from public.operators o join auth.users u on lower(u.email) = o.email
                  where u.id = auth.uid() and u.email_confirmed_at is not null
                    and o.email = lower(coalesce(auth.jwt() ->> 'email', '')));
$$;

--
-- Name: is_owner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_owner(t uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.members m
                 where m.table_id = t and m.user_id = auth.uid() and m.role = 'owner' and m.removed_at is null);
$$;

--
-- Name: is_team(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_team(t uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.members m
                 where m.table_id = t and m.user_id = auth.uid() and m.role in ('owner', 'developer') and m.removed_at is null);
$$;

--
-- Name: job_for_key(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.job_for_key(key text) RETURNS public.jobs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs;
begin
  select * into j from public.jobs
   where approval_key = encode(extensions.digest(coalesce(key, ''), 'sha256'), 'hex') and status = 'running';
  if not found or not exists (select 1 from public.connections cn join public.members m on m.id = cn.member_id
                               where cn.member_id = j.member_id and cn.table_id = j.table_id and cn.revoked_at is null
                                 and cn.full_claude and cn.kind = 'claude' and m.removed_at is null) then
    raise exception 'that key is not for a running job';
  end if;
  return j;
end;
$$;

--
-- Name: jobs_never_in_no_ai_room(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_never_in_no_ai_room() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from public.chats ch where ch.id = new.chat_id and ch.answers = 'off')
     or exists (select 1 from public.messages m where m.id = new.question_id and m.no_ai) then
    raise exception 'tripwire: no AI hears this chat';
  end if;
  return new;
end;
$$;

--
-- Name: jobs_stay_in_room(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jobs_stay_in_room() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  asker uuid;
  inside uuid;
begin
  if new.chat_id is null or not public.chat_is_private(new.chat_id) or public.member_sees_chat(new.chat_id, new.member_id) then
    return new;
  end if;
  if new.kind in ('view', 'review') then
    return null;
  end if;
  select m.member_id into asker from public.messages m where m.id = new.question_id;
  select cn.member_id into inside
    from public.connections cn join public.members mem on mem.id = cn.member_id and mem.role in ('owner', 'developer') and mem.removed_at is null
   where cn.table_id = new.table_id and cn.revoked_at is null and public.member_sees_chat(new.chat_id, cn.member_id)
     and (new.kind not in ('work', 'plan', 'notes') or cn.kind = 'claude')
   order by (cn.member_id = asker) desc, (cn.last_seen > now() - interval '60 seconds') desc, cn.last_seen desc nulls last
   limit 1;
  new.member_id := coalesce(inside, case when public.member_sees_chat(new.chat_id, asker) then asker end,
                            (select ch.created_by from public.chats ch where ch.id = new.chat_id));
  if new.member_id is null or not public.member_sees_chat(new.chat_id, new.member_id) then
    return null;
  end if;
  return new;
end;
$$;

--
-- Name: joining(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.joining(t uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.table_joining;
begin
  if not public.is_owner(t) then raise exception 'only an owner sees the table code'; end if;
  insert into public.table_joining (table_id, code) values (t, public.new_code()) on conflict (table_id) do nothing;
  select * into j from public.table_joining where table_id = t;
  return jsonb_build_object('code', j.code, 'locked', j.locked, 'made_at', j.made_at);
end;
$$;

--
-- Name: judge_change(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.judge_change(change uuid, answer text, said text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.sandbox_changes;
  me uuid;
  who public.members;
  chat uuid;
  msg uuid;
  started jsonb;
  tk uuid;
begin
  select * into ch from public.sandbox_changes where id = change for update;
  if not found or not public.is_team(ch.table_id) then
    raise exception 'that is not yours to decide';
  end if;
  if answer not in ('take', 'differently', 'no') then
    raise exception 'take it, do it differently, or not this';
  end if;
  if ch.test then
    raise exception 'that one was your own test';
  end if;
  if ch.status <> 'ready' then
    raise exception 'there is nothing in that one to decide on';
  end if;
  if ch.verdict = 'take' then
    raise exception 'that one is already being taken';
  end if;
  me := public.my_member_id(ch.table_id);
  select * into who from public.members where id = ch.member_id;
  if answer = 'take' then
    select coalesce(tb.client_chat, (select c.id from public.chats c where c.table_id = ch.table_id and c.is_general))
      into chat from public.tables tb where tb.id = ch.table_id;
    perform set_config('longtable.asked', '1', true);
    insert into public.messages (table_id, chat_id, member_id, body)
      values (ch.table_id, chat, me, left('Build the change from ' || who.display_name || '''s sandbox properly, in the real code.'
        || coalesce(E'\n' || nullif(btrim(coalesce(said, '')), ''), ''), 8000))
      returning id into msg;
    started := public.start_round(ch.table_id, chat, msg, me, null, left('From ' || split_part(who.display_name, ' ', 1) || ': ' || regexp_replace(ch.words, '\s+', ' ', 'g'), 70));
    tk := nullif(started ->> 'task', '')::uuid;
    if tk is null then
      raise exception 'connect an AI first, then take it';
    end if;
    update public.tasks set reference = jsonb_build_object('branch', (select s.branch from public.sandboxes s where s.member_id = ch.member_id),
      'commit', ch.commit, 'client', who.display_name, 'words', ch.words) where id = tk;
  end if;
  update public.sandbox_changes
     set verdict = answer, note = nullif(left(btrim(coalesce(said, '')), 1000), ''), decided_by = me, decided_at = now(), task_id = coalesce(tk, task_id)
   where id = ch.id;
  -- "Not this" takes it back out of their copy too, so what they try is what the team means to keep.
  if answer = 'no' then
    perform public.undo_in_copy(ch);
  end if;
  perform public.log_activity(ch.table_id, me, 'sandbox.' || answer, ch.id, jsonb_build_object('client', who.display_name));
  return tk;
end;
$$;

--
-- Name: kept_line(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kept_line(v text, n integer) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select nullif(public.hide_secrets(left(regexp_replace(btrim(coalesce(v, '')), '//[^/[:space:]:@]+:[^/[:space:]@]+@', '//[hidden]@', 'g'), n)), '');
$$;

--
-- Name: kept_list(jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kept_list(a jsonb, n integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((select jsonb_agg(public.kept_line(x, 300)) from (
    select e #>> '{}' x from jsonb_array_elements(case when jsonb_typeof(a) = 'array' then a else '[]'::jsonb end) e
     where jsonb_typeof(e) = 'string' limit n) s
   where public.kept_line(x, 300) is not null), '[]'::jsonb);
$$;

--
-- Name: kept_usage(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kept_usage(u jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((select jsonb_object_agg(left(k, 40), v) from jsonb_each(case when jsonb_typeof(u) = 'object' then u else '{}'::jsonb end) e(k, v)
                    where jsonb_typeof(v) = 'number'), '{}'::jsonb);
$$;

--
-- Name: last_seen(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.last_seen(t uuid) RETURNS TABLE(member_id uuid, at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.member_id, s.at from public.member_seen s join public.members m on m.id = s.member_id
   where s.table_id = t and m.table_id = t and m.removed_at is null and public.is_team(t);
$$;

--
-- Name: leave_rooms_when_removed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.leave_rooms_when_removed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.removed_at is not null and old.removed_at is null then
    delete from public.chat_people where member_id = new.id;
  end if;
  return null;
end;
$$;

--
-- Name: listen_now(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.listen_now() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  l public.listens;
  who uuid;
  strong boolean;
  weak boolean;
  after_ai boolean;
  latest uuid;
  seat uuid;
  n integer := 0;
  skipped timestamptz;
begin
  update public.jobs set status = 'skipped', lease_until = null, error = 'nobody picked it up'
   where kind in ('listen', 'look')
     and ((status = 'queued' and created_at < now() - interval '45 seconds')
       or (status = 'running' and lease_until < now() - interval '1 minute'));
  for l in select * from public.listens where due_at <= now() for update skip locked loop
    if exists (select 1 from public.jobs j where j.chat_id = l.chat_id and j.status in ('queued', 'running', 'waiting')
                 and j.kind in ('listen', 'look')) then
      continue;
    end if;
    delete from public.listens where chat_id = l.chat_id;
    seat := public.final_seat_now(l.table_id);
    continue when seat is null;
    -- Was the last thing said before these messages said by an AI, a little while ago?
    skipped := null;
    after_ai := coalesce((select p.by_ai from public.messages p
                           where p.chat_id = l.chat_id and p.kind in ('chat', 'answer') and p.created_at < l.since
                             and p.created_at > l.since - interval '15 minutes'
                           order by p.created_at desc limit 1), false);
    -- Each person who wrote is heard on their own: two people asking for two things at the same moment are two
    -- requests, and each goes to its own person's AI.
    for who in select distinct m.member_id from public.messages m
                where m.chat_id = l.chat_id and m.kind = 'chat' and not m.by_ai and m.created_at >= l.since and not public.message_taken(m.id) loop
      -- Their own AI is at work on their request in this chat and taking what they say into it, as at home: it gets
      -- these messages itself. They are heard again once that work ends, so nothing it did not get is lost.
      if exists (select 1 from public.jobs tj join public.messages tq on tq.id = tj.question_id
                  where tj.chat_id = l.chat_id and tj.taking and tj.status = 'running' and tj.lease_until > now() and tq.member_id = who) then
        skipped := least(coalesce(skipped, 'infinity'::timestamptz), (select min(m2.created_at) from public.messages m2
                    where m2.chat_id = l.chat_id and m2.member_id = who and m2.kind = 'chat' and not m2.by_ai and m2.created_at >= l.since));
        continue;
      end if;
      select coalesce(bool_or(char_length(m.body) >= 40
                 or m.body ~ '^\s*/[A-Za-z]' or m.body ~* '\?|@|\m(ai|ais|claude|chatgpt|gpt|codex|table|longtable)\M'
                 or m.body ~* '^\s*(can|could|would|will|please|pls|make|add|fix|change|update|remove|delete|build|write|check|look|why|how|what|where|when|which|who|should|is|are|does|do|did|implement|create|refactor|rename|move|review|explain|tell|show|find|lets|let''s|try|use|set|put|run|test|ship|revert|undo)\M'), false),
             coalesce(bool_or(m.body ~* '^\s*(yes|yeah|yep|no|nah|ok|okay|sure|go)\M'), false)
        into strong, weak
        from public.messages m
       where m.chat_id = l.chat_id and m.kind = 'chat' and not m.by_ai and m.created_at >= l.since and not public.message_taken(m.id) and m.member_id = who;
      -- Anything said straight after an AI spoke is heard, whatever its shape: it is most likely an answer to it.
      -- In a chat whose AIs answer only when named, only a message that names one (or runs a command) is heard.
      if (select ch.answers from public.chats ch where ch.id = l.chat_id) = 'named' then
        continue when not exists (select 1 from public.messages m where m.chat_id = l.chat_id and m.kind = 'chat' and not m.by_ai
          and m.created_at >= l.since and m.member_id = who and not public.message_taken(m.id)
          and (m.body ~ '^\s*/[A-Za-z]' or m.body ~* '@|\m(ai|ais|claude|chatgpt|gpt|codex|table|longtable)\M'));
      else
        continue when not (strong or after_ai);
      end if;
      select m.id into latest from public.messages m
       where m.chat_id = l.chat_id and m.kind = 'chat' and not m.by_ai and m.created_at >= l.since and not public.message_taken(m.id) and m.member_id = who
       order by m.created_at desc limit 1;
      -- A message that was asked outright already has the AIs on it.
      -- A message that was asked outright already has the AIs on it, and one already heard is not heard again (the chat's
      -- window can reach back over it while someone's own run takes their words).
      continue when latest is null or exists (select 1 from public.jobs j where j.question_id = latest);
      insert into public.jobs (table_id, chat_id, member_id, question_id, kind) values (l.table_id, l.chat_id, seat, latest, 'listen');
      n := n + 1;
      -- Plainly for the AI, and their own Claude is on: it starts now, beside the listener.
      if exists (select 1 from public.messages m join public.members me on me.id = m.member_id
                  where m.id = latest and me.role in ('owner', 'developer') and me.removed_at is null
                    and (m.body ~ '^\s*/[A-Za-z]' or m.body ~* '\m(ai|ais|claude|chatgpt|gpt|codex|table|longtable)\M'
                      or (m.body ~ '\?' and not exists (
                            select 1 from public.members o
                             where o.table_id = l.table_id and o.id <> who and o.removed_at is null
                               and char_length(split_part(btrim(o.display_name), ' ', 1)) >= 2
                               and m.body ~* ('\m' || regexp_replace(split_part(btrim(o.display_name), ' ', 1), '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\M')))))
         and exists (select 1 from public.connections cn
                      where cn.member_id = who and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds')
         and public.member_sees_chat(l.chat_id, who) then
        perform public.start_look(l.table_id, l.chat_id, latest, who, true);
      end if;
    end loop;
    if skipped is not null then
      insert into public.listens (chat_id, table_id, since, due_at) values (l.chat_id, l.table_id, skipped, now() + interval '5 seconds')
        on conflict (chat_id) do update set since = least(public.listens.since, excluded.since), due_at = least(public.listens.due_at, excluded.due_at);
    end if;
  end loop;
  return n;
end;
$_$;

--
-- Name: local_allowed(public.connections); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.local_allowed(c public.connections) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.revoked_at is null and c.kind = 'claude' and coalesce(c.full_claude, false)
     and exists (select 1 from public.members m where m.id = c.member_id and m.role in ('owner', 'developer')
                   and m.removed_at is null and not coalesce(m.test, false));
$$;

--
-- Name: log_activity(uuid, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_activity(t uuid, actor uuid, act text, subj uuid, info jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into public.activity (table_id, actor, action, subject, details) values (t, actor, act, subj, coalesce(info, '{}'::jsonb));
$$;

--
-- Name: log_line_visible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_line_visible(t uuid, c uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c is null or public.can_see_chat(c)
         or (not exists (select 1 from public.chats ch where ch.id = c) and not exists (select 1 from public.gone_private_chats g where g.chat_id = c));
$$;

--
-- Name: loose_query(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loose_query(question text) RETURNS tsquery
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when cardinality(lex) = 0 then null
              else to_tsquery('simple', array_to_string(array(
                     select quote_literal(l) from unnest(lex) l), ' | ')) end
  from (select tsvector_to_array(to_tsvector('english', coalesce(question, ''))) as lex) x;
$$;

--
-- Name: main_owner_first(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.main_owner_first() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.role = 'owner' then
    update public.tables set main_owner = new.id where id = new.table_id and main_owner is null;
  end if;
  return null;
end;
$$;

--
-- Name: make_chat(uuid, text, text, text, uuid[], boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.make_chat(t uuid, chat_name text, chat_about text, who text, people uuid[], take_notes boolean, ai_answers text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c uuid;
  me uuid := public.my_member_id(t);
begin
  if not public.is_team(t) then
    raise exception 'only the team can make chats';
  end if;
  if char_length(btrim(coalesce(chat_name, ''))) not between 1 and 60 then
    raise exception 'a chat needs a name of up to 60 characters';
  end if;
  if who not in ('everyone', 'some', 'me') then
    raise exception 'a chat is for everyone, some people, or just you';
  end if;
  -- Made private from its first moment, so the team's channel never carries its name, only that a chat changed.
  insert into public.chats (table_id, name, about, created_by, private, set_up)
    values (t, left(btrim(chat_name), 60), '', me, who <> 'everyone', false) returning id into c;
  insert into public.chat_people (chat_id, member_id) values (c, me) on conflict do nothing;
  -- One line in the log for a new chat: that it was made (setting it up in the same moment is part of making it).
  perform set_config('longtable.making_chat', '1', true);
  perform public.setup_chat(c, chat_name, chat_about, who, people, take_notes, ai_answers);
  perform set_config('longtable.making_chat', '', true);
  perform public.log_activity(t, me, 'chat.created', c, jsonb_build_object('name', left(btrim(chat_name), 60)));
  return c;
end;
$$;

--
-- Name: mark_pasted(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_pasted(m uuid, ranges jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  msg public.messages;
  clean jsonb;
begin
  select * into msg from public.messages where id = m;
  if not found or msg.by_ai or msg.member_id is distinct from public.my_member_id(msg.table_id) then
    raise exception 'only your own message can be marked';
  end if;
  if msg.created_at < now() - interval '5 minutes' then
    raise exception 'that message was sent too long ago to mark';
  end if;
  -- At most ten, each inside the message.
  select coalesce(jsonb_agg(jsonb_build_array((r ->> 0)::int, (r ->> 1)::int)), '[]'::jsonb) into clean
    from (select r from jsonb_array_elements(case when jsonb_typeof(ranges) = 'array' then ranges else '[]'::jsonb end) r
           where jsonb_typeof(r) = 'array' and jsonb_array_length(r) = 2
             and (r ->> 0) ~ '^\d{1,6}$' and (r ->> 1) ~ '^\d{1,6}$'
             and (r ->> 0)::int + (r ->> 1)::int <= char_length(msg.body) and (r ->> 1)::int > 0
           limit 10) picked;
  if jsonb_array_length(clean) = 0 then
    return;
  end if;
  update public.messages set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('pasted', clean) where id = m;
end;
$_$;

--
-- Name: may(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.may(t uuid, what text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.is_owner(t) or exists (
    select 1 from public.members m where m.table_id = t and m.user_id = auth.uid() and m.role = 'developer' and m.removed_at is null
      and case what when 'settings' then m.can_settings when 'invite' then m.can_invite when 'clients' then m.can_clients else false end);
$$;

--
-- Name: member_sees_chat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.member_sees_chat(c uuid, m uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.chats ch join public.members mem on mem.id = m and mem.table_id = ch.table_id and mem.removed_at is null
                  where ch.id = c and (not ch.private or exists (select 1 from public.chat_people p where p.chat_id = c and p.member_id = m)));
$$;

--
-- Name: message_no_ai(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_no_ai() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    new.no_ai := old.no_ai or new.no_ai;
    return new;
  end if;
  new.no_ai := new.no_ai or exists (select 1 from public.chats ch where ch.id = new.chat_id and ch.answers = 'off');
  return new;
end;
$$;

--
-- Name: message_taken(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_taken(m uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.delivered_messages d join public.jobs dj on dj.id = d.job_id
                  where d.message_id = m and (d.confirmed or (dj.status = 'running' and dj.lease_until > now())));
$$;

--
-- Name: message_time_is_now(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.message_time_is_now() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- A person writing through the app gets the server's clock; the database's own functions keep theirs.
  if current_user in ('authenticated', 'anon') then
    new.created_at := now();
  end if;
  return new;
end;
$$;

--
-- Name: my_commands(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_commands(t uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select c.commands from public.connections c join public.members m on m.id = c.member_id
                    where c.table_id = t and m.table_id = t and m.user_id = auth.uid() and m.removed_at is null
                      and c.revoked_at is null
                    order by c.last_seen desc nulls last limit 1), '[]'::jsonb);
$$;

--
-- Name: my_join_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_join_requests() RETURNS TABLE(id uuid, table_id uuid, table_name text, status text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, r.table_id, t.name, r.status, r.created_at
    from public.join_requests r join public.tables t on t.id = r.table_id
   where r.user_id = auth.uid() and r.status <> 'cancelled' and r.created_at > now() - interval '30 days'
   order by r.created_at desc limit 20;
$$;

--
-- Name: my_local(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_local(t uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select c.local from public.connections c join public.members m on m.id = c.member_id
   where c.table_id = t and m.table_id = t and m.user_id = auth.uid() and c.local is not null
     and public.local_allowed(c) and c.last_seen > now() - interval '2 minutes'
   order by c.last_seen desc limit 1;
$$;

--
-- Name: my_loose_uploads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_loose_uploads() RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select count(*)::integer from storage.objects o
   where o.bucket_id = 'attachments' and o.owner_id = auth.uid()::text
     and not exists (select 1 from public.attachments a where a.path = o.name);
$$;

--
-- Name: my_member_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_member_id(t uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select m.id from public.members m where m.table_id = t and m.user_id = auth.uid() and m.removed_at is null;
$$;

--
-- Name: my_visible_chats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_visible_chats() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select ch.id
    from public.members m join public.chats ch on ch.table_id = m.table_id
   where m.user_id = auth.uid() and m.removed_at is null and m.role in ('owner', 'developer')
     and (not ch.private or exists (select 1 from public.chat_people p where p.chat_id = ch.id and p.member_id = m.id));
$$;

--
-- Name: new_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.new_code() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  abc constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  raw bytea;
  c text;
begin
  loop
    raw := extensions.gen_random_bytes(8);
    c := '';
    for i in 0..7 loop
      c := c || substr(abc, 1 + (get_byte(raw, i) % 31), 1);
    end loop;
    exit when not exists (select 1 from public.table_joining where code = c);
  end loop;
  return c;
end;
$$;

--
-- Name: new_join_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.new_join_code(t uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c text := public.new_code();
begin
  if not public.is_owner(t) then raise exception 'only an owner changes the table code'; end if;
  insert into public.table_joining (table_id, code) values (t, c)
    on conflict (table_id) do update set code = excluded.code, made_at = now();
  perform public.log_activity(t, public.my_member_id(t), 'join.new_code', null, '{}'::jsonb);
  return c;
end;
$$;

--
-- Name: next_color(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_color(t uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (array['oklch(0.62 0.09 30)', 'oklch(0.62 0.09 250)', 'oklch(0.62 0.09 310)',
                'oklch(0.62 0.09 120)', 'oklch(0.62 0.09 70)', 'oklch(0.62 0.09 200)'])
         [1 + ((select count(*) from public.members m where m.table_id = t)::int % 6)];
$$;

--
-- Name: note_sandbox_open(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.note_sandbox_open(m uuid, ok boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid;
begin
  select s.table_id into t from public.sandboxes s where s.member_id = m;
  if t is null or not public.may(t, 'clients') then
    raise exception 'only an owner, or a teammate given the clients, checks a copy';
  end if;
  update public.sandboxes set checked_at = now(), open_ok = ok where member_id = m;
end;
$$;

--
-- Name: notes_now(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notes_now() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.chats;
  seat uuid;
  n integer := 0;
begin
  update public.jobs set status = 'skipped', lease_until = null, error = 'nobody picked it up'
   where kind = 'notes' and ((status = 'queued' and created_at < now() - interval '10 minutes')
                          or (status = 'running' and lease_until < now() - interval '2 minutes'));
  for ch in select * from public.chats c where c.notes and c.set_up and c.answers <> 'off' loop
    continue when exists (select 1 from public.jobs j where j.chat_id = ch.id and j.kind = 'notes' and j.status in ('queued', 'running'));
    continue when not exists (select 1 from public.messages m where m.chat_id = ch.id and m.kind in ('chat', 'answer')
                                and m.created_at > coalesce(ch.noted_at, '-infinity'::timestamptz));
    continue when (select max(m.created_at) from public.messages m where m.chat_id = ch.id) > now() - interval '60 seconds'
              and (select count(*) from public.messages m where m.chat_id = ch.id and m.kind in ('chat', 'answer')
                     and m.created_at > coalesce(ch.noted_at, '-infinity'::timestamptz)) < 15;
    select cn.member_id into seat
      from public.connections cn join public.members mem on mem.id = cn.member_id and mem.role in ('owner', 'developer') and mem.removed_at is null
     where cn.table_id = ch.table_id and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
       and public.member_sees_chat(ch.id, cn.member_id)
     order by (cn.member_id = ch.created_by) desc, cn.created_at
     limit 1;
    continue when seat is null;
    insert into public.jobs (table_id, chat_id, member_id, kind) values (ch.table_id, ch.id, seat, 'notes');
    n := n + 1;
  end loop;
  return n;
end;
$$;

--
-- Name: operator_bugs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operator_bugs() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.is_operator() then
    raise exception 'not found';
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'body', b.body, 'place', b.place, 'browser', b.browser, 'at', b.created_at) order by b.created_at desc)
    from (select * from public.bug_reports order by created_at desc limit 100) b), '[]'::jsonb);
end;
$$;

--
-- Name: operator_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operator_counts() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  week timestamptz := now() - interval '7 days';
  day timestamptz := now() - interval '1 day';
begin
  if not public.is_operator() then
    raise exception 'only the people running this Longtable see these counts';
  end if;
  return jsonb_build_object(
    'tables', (select count(*) from public.tables),
    'tables_active_7d', (select count(distinct table_id) from public.messages where created_at > week),
    'people', (select count(*) from public.members where removed_at is null),
    'clients', (select count(*) from public.members where removed_at is null and role = 'client'),
    'messages_24h', (select count(*) from public.messages where created_at > day),
    'messages_7d', (select count(*) from public.messages where created_at > week),
    'decisions_7d', (select count(*) from public.decisions where created_at > week),
    'client_requests_7d', (select count(*) from public.requests where created_at > week),
    'ai_on_now', (select count(*) from public.connections where revoked_at is null and last_seen > now() - interval '60 seconds'),
    'ai_connected', (select count(*) from public.connections where revoked_at is null),
    'ai_codex', (select count(*) from public.connections where revoked_at is null and kind = 'codex'),
    'jobs_done_7d', (select count(*) from public.jobs where status = 'done' and created_at > week),
    'jobs_failed_7d', (select count(*) from public.jobs where status = 'failed' and created_at > week),
    'answer_seconds_median_7d', (
      select round(percentile_cont(0.5) within group (order by extract(epoch from finished_at - created_at))::numeric, 1)
        from public.jobs where status = 'done' and kind in ('answer', 'combine', 'client') and created_at > week and finished_at is not null));
end;
$$;

--
-- Name: pages_for_job(public.jobs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pages_for_job(j public.jobs) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(x order by x.touched_at desc), '[]'::jsonb) from (
    select p.id, p.title, p.about, p.version, p.touched_at,
           (select left(v.html, 300000) from public.page_versions v where v.page_id = p.id and v.n = p.version) as html,
           (select coalesce(jsonb_agg(jsonb_build_object('from', mem.display_name, 'on', cm.anchor, 'said', cm.body) order by cm.created_at), '[]'::jsonb)
              from public.page_comments cm left join public.members mem on mem.id = cm.member_id
             where cm.page_id = p.id and cm.resolved_at is null and cm.deleted_at is null) as comments
      from public.pages p
     where p.chat_id = j.chat_id and p.table_id = j.table_id
     order by p.touched_at desc
     limit 3) x;
$$;

--
-- Name: pair_connection(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pair_connection(code text, device_label text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  p public.pairings;
  token text;
  conn uuid;
  who public.members;
  tname text;
  general uuid;
begin
  select * into p from public.pairings
    where code_hash = encode(extensions.digest(upper(btrim(code)), 'sha256'), 'hex')
    for update;
  if not found or p.used_at is not null or p.expires_at < now() then
    raise exception 'this connect code is not valid any more; press Connect again';
  end if;
  select * into who from public.members where id = p.member_id;
  if who.removed_at is not null then
    raise exception 'this connect code is not valid any more; press Connect again';
  end if;
  update public.pairings set used_at = now() where id = p.id;
  update public.connections set revoked_at = now()
    where member_id = p.member_id and revoked_at is null;
  token := encode(extensions.gen_random_bytes(32), 'hex');
  insert into public.connections (table_id, member_id, kind, token_hash, label, last_seen)
    values (p.table_id, p.member_id, p.kind, encode(extensions.digest(token, 'sha256'), 'hex'), left(btrim(coalesce(device_label, '')), 80), now())
    returning id into conn;
  select name into tname from public.tables where id = p.table_id;
  select id into general from public.chats where table_id = p.table_id and is_general;
  if who.role <> 'client' then
    -- Reconnecting is not arriving: an AI that introduced itself here in the last week is not asked to again.
    if not exists (select 1 from public.messages mm where mm.table_id = p.table_id and mm.member_id = p.member_id and mm.kind = 'intro'
                    and mm.created_at > now() - interval '7 days') then
      insert into public.jobs (table_id, chat_id, member_id, kind) values (p.table_id, general, p.member_id, 'intro');
    end if;
  end if;
  perform public.log_activity(p.table_id, p.member_id, 'connection.paired', conn, jsonb_build_object('kind', p.kind, 'name', who.display_name));
  return jsonb_build_object('token', token, 'table_id', p.table_id, 'table_name', tname,
    'member_id', p.member_id, 'member_name', who.display_name, 'kind', p.kind, 'role', who.role);
end;
$$;

--
-- Name: pass_on_request(uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pass_on_request(m uuid, words text, title text, line uuid, ack boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me public.members;
  req uuid := gen_random_uuid();
  msg uuid;
  landing uuid;
  clean text := left(btrim(words), 4000);
  heading text := left(regexp_replace(btrim(coalesce(nullif(btrim(coalesce(title, '')), ''), words)), '\s+', ' ', 'g'), 120);
begin
  select * into me from public.members where id = m;
  select coalesce(tb.client_chat, (select ch.id from public.chats ch where ch.table_id = me.table_id and ch.is_general))
    into landing from public.tables tb where tb.id = me.table_id;
  insert into public.messages (table_id, chat_id, member_id, body, kind, meta)
    values (me.table_id, landing, me.id, clean, 'client', jsonb_build_object('request', req))
    returning id into msg;
  insert into public.requests (id, table_id, member_id, title, body, message_id, from_line)
    values (req, me.table_id, me.id, heading, clean, msg, line);
  if line is not null then
    update public.client_lines set request_id = req where id = line;
  end if;
  perform public.add_request_event(req, 'You asked');
  if ack then
    insert into public.client_updates (table_id, request_id, body)
      values (me.table_id, req, 'Passed on to the team. You will hear here what they decide.');
  end if;
  perform public.log_activity(me.table_id, me.id, 'client.asked', req, jsonb_build_object('title', heading));
  return req;
end;
$$;

--
-- Name: pin_page(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.pin_page(p uuid, pinned boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
  me uuid := public.my_member_id(pg.table_id);
begin
  if pinned then
    insert into public.page_pins (member_id, page_id) values (me, pg.id) on conflict do nothing;
  else
    delete from public.page_pins where member_id = me and page_id = pg.id;
  end if;
end;
$$;

--
-- Name: prepare_client_sandbox(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_client_sandbox(m uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
  seat uuid;
  name text;
  repo text;
begin
  select * into who from public.members where id = m and removed_at is null;
  if not found or not public.may(who.table_id, 'clients') then
    raise exception 'only the owner sets a copy up';
  end if;
  if who.role <> 'client' then
    raise exception 'a copy is for a client';
  end if;
  seat := public.copy_seat(who.table_id);
  if seat is null and public.copy_builder(who.table_id) is not null then
    raise exception '%''s computer builds this table''s copies, and their Claude is not on right now',
      (select split_part(x.display_name, ' ', 1) from public.members x where x.id = public.copy_builder(who.table_id));
  end if;
  if seat is null then
    raise exception 'connect your team''s Claude first: it is what makes the copy';
  end if;
  select tc.repo_url into repo from public.table_code tc where tc.table_id = who.table_id;
  if repo is null then
    raise exception 'set where the code is first (Settings, General): a copy is a branch of the table''s repository, which your hosting builds';
  end if;
  if not exists (select 1 from public.connections cn where cn.member_id = seat and cn.revoked_at is null and cn.kind = 'claude'
                  and (public.same_repo(cn.use_repo, repo) or public.same_repo(cn.limits -> 'reads' ->> 'repo', repo))) then
    raise exception '%''s Claude has not said yes to %. In their AI window, press Use it, so the copy lands there, where your hosting builds it.',
      (select split_part(m.display_name, ' ', 1) from public.members m where m.id = seat), repo;
  end if;
  insert into public.sandboxes (member_id, table_id, mode, branch)
    values (m, who.table_id, 'chat', 'longtable/sandbox-'
      || coalesce(nullif(btrim(left(regexp_replace(lower(who.display_name), '[^a-z0-9]+', '-', 'g'), 30), '-'), ''), 'client')
      || '-' || left(m::text, 8))
    on conflict (member_id) do nothing;
  insert into public.table_sandbox (table_id) values (who.table_id) on conflict (table_id) do nothing;
  select s.branch into name from public.sandboxes s where s.member_id = m;
  if not exists (select 1 from public.jobs j where j.subject = m and j.kind = 'sandbox' and j.change_id is null and j.status in ('queued', 'running')) then
    insert into public.jobs (table_id, member_id, kind, subject) values (who.table_id, seat, 'sandbox', m);
  end if;
  return name;
end;
$$;

--
-- Name: release_rounds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_rounds() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  w public.jobs;
  n integer := 0;
begin
  for w in select * from public.jobs where kind in ('combine', 'look') and status = 'waiting' for update skip locked loop
    if not exists (select 1 from public.jobs v where v.round = w.round and v.kind = 'view' and v.status in ('queued', 'running'))
       or w.created_at < now() - interval '90 seconds' then
      update public.jobs set status = 'skipped', error = 'did not answer in time'
        where round = w.round and kind = 'view' and status = 'queued';
      -- A look is timed from when it can start, or the listener's 45 seconds would drop it at once.
      update public.jobs set status = 'queued', created_at = case when w.kind = 'look' then now() else created_at end where id = w.id;
      n := n + 1;
    end if;
  end loop;
  return n;
end;
$$;

--
-- Name: remember_gone_private(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remember_gone_private() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.private then
    insert into public.gone_private_chats (chat_id, table_id) values (old.id, old.table_id) on conflict do nothing;
  end if;
  return old;
end;
$$;

--
-- Name: remove_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_member(m uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
begin
  select * into who from public.members where id = m;
  if not found then
    raise exception 'only the owner takes people off the table';
  end if;
  -- One hand-over or removal at a table at a time, and the person read again once it is this one's turn: a
  -- hand-over to them that went first has made them the owner, who cannot be taken off.
  perform 1 from public.tables where id = who.table_id for update;
  select * into who from public.members where id = m for update;
  if not (public.is_owner(who.table_id) or (who.role = 'client' and public.may(who.table_id, 'clients'))) then
    raise exception 'only an owner takes people off the table';
  end if;
  if who.role = 'owner' and (exists (select 1 from public.tables where id = who.table_id and main_owner = who.id) or not public.is_main_owner(who.table_id)) then
    raise exception 'the main owner cannot be taken off, and only the main owner takes a co-owner off';
  end if;
  if who.removed_at is not null then
    return;
  end if;
  update public.members set removed_at = now() where id = m;
  update public.connections set revoked_at = now() where member_id = m and revoked_at is null;
  -- A connect code they made and have not used yet connects nothing now.
  update public.pairings set used_at = now() where member_id = m and used_at is null;
  -- A client's question their AI was answering for the team is passed on to the team, not dropped with them.
  if who.role <> 'client' then
    perform public.give_up_client_job(j.id, 'taken off the table')
       from public.jobs j where j.member_id = m and j.kind = 'client' and j.status in ('queued', 'running');
  end if;
  update public.jobs set status = 'skipped', lease_until = null, error = 'taken off the table'
   where member_id = m and status in ('queued', 'running', 'waiting');
  -- A client taken off is not answered any more either: a question of theirs a team AI is answering, and work on
  -- their copy, stop with them, or the answer still landed in their chat and passed a request on in their name.
  update public.jobs set status = 'skipped', lease_until = null, error = 'taken off the table'
   where subject = m and status in ('queued', 'running', 'waiting');
  update public.tables set final_seat = null where id = who.table_id and final_seat = m;
  if who.role = 'client' then
    perform realtime.send(jsonb_build_object('table', 'members', 'record', jsonb_build_object('id', m, 'removed_at', now())),
      'UPDATE', 'client:' || who.table_id::text || ':' || m::text, true);
  end if;
  perform public.log_activity(who.table_id, public.my_member_id(who.table_id), 'member.removed', m,
    jsonb_build_object('name', who.display_name, 'role', who.role));
end;
$$;

--
-- Name: remove_test_client(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_test_client(t uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not exists (select 1 from public.members o where o.table_id = t and o.user_id = auth.uid() and o.removed_at is null and o.role = 'owner') then
    raise exception 'only the owner removes the test client';
  end if;
  delete from public.client_updates u
   using public.requests r, public.members m
   where u.request_id = r.id and r.member_id = m.id and m.table_id = t and m.test;
  update public.decisions d set affects_client = false
    from public.requests r, public.members m
   where d.request_id = r.id and r.member_id = m.id and m.table_id = t and m.test and d.delivered_at is null;
  delete from public.members where table_id = t and test;
end;
$$;

--
-- Name: rename_chat(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_chat(c uuid, chat_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.chats;
  clean text := left(btrim(coalesce(chat_name, '')), 60);
begin
  select * into ch from public.chats where id = c;
  if not found or not public.can_see_chat(c) then
    raise exception 'only the team can rename a chat';
  end if;
  if clean = '' then
    raise exception 'a chat needs a name';
  end if;
  update public.chats set name = clean where id = c;
  perform public.log_activity(ch.table_id, public.my_member_id(ch.table_id), 'chat.renamed', c, jsonb_build_object('from', ch.name, 'name', clean));
end;
$$;

--
-- Name: rename_page(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_page(p uuid, title text, about text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
begin
  if char_length(btrim(coalesce(title, ''))) not between 1 and 120 then
    raise exception 'a page''s name is between 1 and 120 characters';
  end if;
  update public.pages set title = btrim(rename_page.title), about = coalesce(left(rename_page.about, 300), pages.about), touched_at = now()
   where id = pg.id;
end;
$$;

--
-- Name: report_bug(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_bug(t uuid, body text, place text DEFAULT ''::text, browser text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  me uuid := public.my_member_id(t);
begin
  if me is null then
    raise exception 'only someone at the table can report a bug from it';
  end if;
  if char_length(btrim(coalesce(body, ''))) = 0 then
    raise exception 'say what went wrong';
  end if;
  -- A handful an hour from one person is plenty.
  if (select count(*) from public.bug_reports b where b.member_id = me and b.created_at > now() - interval '1 hour') >= 10 then
    raise exception 'that is a lot of reports in an hour; try again later';
  end if;
  insert into public.bug_reports (table_id, member_id, body, place, browser)
    values (t, me, left(btrim(body), 4000), left(coalesce(place, ''), 300), left(coalesce(browser, ''), 300));
end;
$$;

--
-- Name: resolve_page_comment(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_page_comment(cm uuid, done boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  x public.page_comments;
begin
  select * into x from public.page_comments where id = cm;
  if not found or not exists (select 1 from public.pages p where p.id = x.page_id and public.can_see_chat(p.chat_id)) then
    raise exception 'that comment is not at a table you are on';
  end if;
  update public.page_comments
     set resolved_at = case when done then now() end, resolved_by = case when done then public.my_member_id(x.table_id) end
   where id = cm;
end;
$$;

--
-- Name: restore_page_version(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_page_version(p uuid, n integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages := public.team_page(p);
  old public.page_versions;
begin
  select * into old from public.page_versions where page_id = pg.id and page_versions.n = restore_page_version.n;
  if not found then
    raise exception 'that page has no such version';
  end if;
  update public.pages set version = version + 1, touched_at = now() where id = pg.id returning * into pg;
  insert into public.page_versions (page_id, table_id, n, html, made_by, by_ai, note)
    values (pg.id, pg.table_id, pg.version, old.html, public.my_member_id(pg.table_id), false, format('Back to version %s', old.n));
  return pg.version;
end;
$$;

--
-- Name: room_topic_chat_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.room_topic_chat_id(topic text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when topic ~ '^room:[0-9a-f-]{36}$' then substring(topic from 6)::uuid else null end;
$_$;

--
-- Name: runner_approval(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_approval(key text, a uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs := public.job_for_key(key);
  r public.approvals;
begin
  select * into r from public.approvals where id = a and job_id = j.id;
  if not found then
    raise exception 'no such request';
  end if;
  return jsonb_build_object('status', r.status, 'always', r.always, 'answer', r.answer);
end;
$$;

--
-- Name: runner_ask_approval(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_ask_approval(key text, tool text, summary text, why text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs := public.job_for_key(key);
  cn public.connections;
  a uuid;
begin
  select * into cn from public.connections where member_id = j.member_id and table_id = j.table_id and revoked_at is null and kind = 'claude'
   order by last_seen desc nulls last limit 1;
  if (select count(*) from public.approvals where job_id = j.id and status = 'waiting') >= 5
     or (select count(*) from public.approvals where connection_id = cn.id and status = 'waiting') >= 20
     or (select count(*) from public.approvals where connection_id = cn.id and created_at > now() - interval '1 hour') >= 60 then
    raise exception 'too many requests are waiting for an answer';
  end if;
  insert into public.approvals (table_id, connection_id, member_id, job_id, tool, summary, why)
    values (j.table_id, cn.id, j.member_id, j.id, public.kept_line(tool, 80), left(public.hide_secrets(left(coalesce(summary, ''), 4000)), 2000),
      -- Keys hidden before cutting: a key cut in half would no longer look like one.
      nullif(left(public.hide_secrets(regexp_replace(left(coalesce(why, ''), 2000), '\s+', ' ', 'g')), 200), ''))
    returning id into a;
  perform realtime.send(jsonb_build_object('table', 'approvals', 'record', jsonb_build_object('id', a, 'member_id', j.member_id)),
    'INSERT', 'team:' || j.table_id::text, true);
  return a;
end;
$$;

--
-- Name: runner_ask_question(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_ask_question(key text, question text, options jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs := public.job_for_key(key);
  cn public.connections;
  a uuid;
  opts jsonb;
begin
  -- Two to six choices, each a short label and an optional line about it, keys hidden.
  select coalesce(jsonb_agg(jsonb_build_object(
           'label', left(public.hide_secrets(left(coalesce(o ->> 'label', ''), 400)), 120),
           'about', nullif(left(public.hide_secrets(left(coalesce(o ->> 'about', ''), 1000)), 300), ''))), '[]'::jsonb)
    into opts
    from (select o from jsonb_array_elements(case when jsonb_typeof(options) = 'array' then options else '[]'::jsonb end) o
           where jsonb_typeof(o) = 'object' and btrim(coalesce(o ->> 'label', '')) <> '' limit 6) picked;
  if jsonb_array_length(opts) < 2 then
    raise exception 'a question needs at least two choices';
  end if;
  select * into cn from public.connections where member_id = j.member_id and table_id = j.table_id and revoked_at is null and kind = 'claude'
   order by last_seen desc nulls last limit 1;
  if (select count(*) from public.approvals where job_id = j.id and status = 'waiting') >= 5
     or (select count(*) from public.approvals where connection_id = cn.id and status = 'waiting') >= 20
     or (select count(*) from public.approvals where connection_id = cn.id and created_at > now() - interval '1 hour') >= 60 then
    raise exception 'too many requests are waiting for an answer';
  end if;
  insert into public.approvals (table_id, connection_id, member_id, job_id, tool, summary, kind, options)
    values (j.table_id, cn.id, j.member_id, j.id, 'question', left(public.hide_secrets(left(coalesce(question, ''), 4000)), 2000), 'question', opts)
    returning id into a;
  perform realtime.send(jsonb_build_object('table', 'approvals', 'record', jsonb_build_object('id', a, 'member_id', j.member_id)),
    'INSERT', 'team:' || j.table_id::text, true);
  return a;
end;
$$;

--
-- Name: runner_attach(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_attach(key text, path text, name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  j public.jobs := public.job_for_key(key);
  o record;
  mime text;
  made uuid;
begin
  if coalesce(path, '') !~ ('^' || j.table_id::text || '/ai-[0-9a-f]{32}/[0-9a-f-]{36}-[^/]{1,200}$')
     or not exists (select 1 from public.upload_slots s where s.job_id = j.id and s.key = substring(split_part(path, '/', 2) from 4)) then
    raise exception 'that file is not in this job''s place';
  end if;
  if (select count(*) from public.attachments where job_id = j.id) >= 8 then
    raise exception 'eight files at most in one answer';
  end if;
  select so.id, so.metadata into o from storage.objects so where so.bucket_id = 'attachments' and so.name = path;
  if not found then
    raise exception 'that file did not finish uploading';
  end if;
  mime := left(coalesce(nullif(o.metadata ->> 'mimetype', ''), 'application/octet-stream'), 120);
  insert into public.attachments (table_id, member_id, message_id, path, name, mime, size, kind, job_id)
    values (j.table_id, j.member_id, null, path, left(coalesce(nullif(btrim(name), ''), 'file'), 200), mime,
            coalesce((o.metadata ->> 'size')::bigint, 0),
            case when mime like 'image/%' then 'image' when mime like 'video/%' then 'video' when mime like 'audio/%' then 'audio' else 'file' end, j.id)
    returning id into made;
  return made;
end;
$_$;

--
-- Name: runner_attach_answer(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_attach_answer(token text, job uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  j public.jobs;
  files jsonb;
begin
  select * into j from public.jobs where id = job and member_id = c.member_id;
  if not found or j.result_message_id is null then
    return 0;
  end if;
  -- A part of a round (its work, a view, a review) writes to the back room: its files wait for the round's one answer,
  -- which takes the files of every part of the round.
  if j.round is not null and j.kind <> 'combine' then
    return 0;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'name', a.name, 'mime', a.mime, 'size', a.size, 'path', a.path, 'kind', a.kind) order by a.created_at), '[]'::jsonb)
    into files from public.attachments a
   where a.message_id is null and a.table_id = j.table_id
     and (a.job_id = j.id or (j.kind = 'combine' and j.round is not null and a.job_id in (select rj.id from public.jobs rj where rj.round = j.round)));
  if jsonb_array_length(files) = 0 then
    return 0;
  end if;
  update public.attachments a set message_id = j.result_message_id
   where a.message_id is null and a.table_id = j.table_id
     and (a.job_id = j.id or (j.kind = 'combine' and j.round is not null and a.job_id in (select rj.id from public.jobs rj where rj.round = j.round)));
  update public.messages set meta = coalesce(meta, '{}'::jsonb) || jsonb_build_object('files', coalesce(meta -> 'files', '[]'::jsonb) || files)
   where id = j.result_message_id;
  return jsonb_array_length(files);
end;
$$;

--
-- Name: runner_beat(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_beat(token text, job uuid, note text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
begin
  update public.jobs
     set lease_until = now() + interval '3 minutes', progress = nullif(left(public.hide_secrets(coalesce(note, '')), 120), '')
   where id = job and member_id = c.member_id and status = 'running';
  return found;
end;
$$;

--
-- Name: runner_claim(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_claim(token text, lane text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  j public.jobs;
  q public.messages;
  history jsonb;
  views jsonb := '[]'::jsonb;
  related jsonb := '[]'::jsonb;
  pinned jsonb;
begin
  select * into j from public.jobs
    where member_id = c.member_id
      and (status = 'queued' or (status = 'running' and lease_until < now()))
      and attempts < 3
      and (kind not in ('work', 'plan', 'sandbox') or c.kind = 'claude')
      and (chat_id is null or public.member_sees_chat(chat_id, member_id))
      and case lane when 'heavy' then kind in ('work', 'answer', 'sandbox') when 'light' then kind not in ('work', 'answer', 'sandbox')
               else kind in ('answer', 'view', 'combine', 'intro', 'client') end
    order by (kind in ('client', 'listen')) desc, (kind = 'sandbox'), (kind in ('combine', 'work', 'review')) desc, created_at
    limit 1
    for update skip locked;
  if not found then
    return null;
  end if;
  update public.jobs
     set status = 'running', attempts = attempts + 1, lease_until = now() + (case when j.kind in ('work', 'sandbox') then interval '12 minutes' when j.kind = 'listen' then interval '90 seconds' when j.kind = 'look' then interval '2 minutes' else interval '5 minutes' end),
         connection_id = c.id, started_at = now()
   where id = j.id;
  if j.kind = 'client' then
    -- A team AI that reads the code for a client's question reads it where the team keeps it. A client's own
    -- assistant is never told where the code is.
    return public.client_job_payload(j) || case when exists (select 1 from public.members mm where mm.id = c.member_id and mm.role <> 'client')
      then jsonb_build_object('repo', (select tc.repo_url from public.table_code tc where tc.table_id = j.table_id), 'use_repo', c.use_repo) else '{}'::jsonb end;
  end if;
  if j.kind = 'sandbox' then
    -- A client's copy is a branch of the team's repository too.
    return public.sandbox_job_payload(j) || jsonb_build_object('repo', (select tc.repo_url from public.table_code tc where tc.table_id = j.table_id), 'use_repo', c.use_repo);
  end if;
  select * into q from public.messages where id = j.question_id;

  select coalesce(jsonb_agg(x order by x.created_at), '[]'::jsonb) into history from (
    -- Each message's id, and for an AI's answer the job that wrote it, so a session can tell what it already has.
    select m.id, m.created_at, m.body, m.by_ai, m.kind = 'client' as client, case when m.kind = 'github' then 'GitHub' else mem.display_name end as name,
           (select jj.id from public.jobs jj where jj.result_message_id = m.id limit 1) as job_id,
           m.meta -> 'pasted' as pasted
      from public.messages m join public.members mem on mem.id = m.member_id
     where m.chat_id = j.chat_id and m.kind in ('chat', 'answer', 'client', 'github') and not m.no_ai
       -- A job with no question of its own (the note-taker's) gets the whole conversation.
       and m.created_at < coalesce(q.created_at, now()) and (j.question_id is null or m.id <> j.question_id)
     order by m.created_at desc
     -- The listener reads only the newest part (24,000 characters); the jobs that answer may read it all.
     limit case when j.kind = 'listen' then 150 else 400 end
  ) x;

  if j.kind in ('combine', 'work', 'review', 'plan') or (j.kind = 'look' and j.round is not null) then
    select coalesce(jsonb_agg(jsonb_build_object('name', mem.display_name, 'view', m.body, 'meta', m.meta) order by m.created_at), '[]'::jsonb)
      into views
      from public.messages m join public.members mem on mem.id = m.member_id
     where m.table_id = j.table_id and m.kind = 'view' and m.meta ->> 'round' = j.round::text;
  end if;

  if q.body is not null then
    select coalesce(jsonb_agg(x), '[]'::jsonb) into related from (
      select ch.name as chat, mem.display_name as name, m.by_ai, m.kind = 'client' as client, m.body,
             ts_rank(m.search, public.loose_query(q.body)) as rank
        from public.messages m
        join public.members mem on mem.id = m.member_id
        join public.chats ch on ch.id = m.chat_id
       where m.table_id = j.table_id and m.kind in ('chat', 'answer', 'client') and m.id <> q.id and not m.no_ai
         and m.search @@ public.loose_query(q.body)
         and m.id not in (select m2.id from public.messages m2 where m2.chat_id = j.chat_id order by m2.created_at desc limit 21)
         and public.member_sees_chat(m.chat_id, c.member_id)
       order by rank desc
       limit 5
    ) x;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('kind', n.kind, 'title', n.title, 'body', n.body) order by n.kind desc, n.created_at), '[]'::jsonb)
    into pinned from public.notes n where n.table_id = j.table_id;

  return jsonb_build_object(
    'job_id', j.id,
    'kind', j.kind,
    'table_name', (select name from public.tables where id = j.table_id),
    'chat_id', j.chat_id, 'question_id', j.question_id,
    'chat_name', (select name from public.chats where id = j.chat_id),
    'chat_private', public.chat_is_private(j.chat_id),
    'me', (select display_name from public.members where id = c.member_id),
    'asker', (select display_name from public.members where id = q.member_id),
    -- Whether the one asking is this connection's own person, and has left on that their AI may open places on
    -- their own computer that they point at. Never true for anyone else's message.
    'own_paths', coalesce(q.member_id = c.member_id and c.open_paths, false),
    -- Whether what they point at may also be handed to the other AIs working on the same request.
    'share_paths', coalesce(q.member_id = c.member_id and c.open_paths and c.share_paths, false),
    -- What another person's AI read from their own computer and shared for this request. Never this AI's own.
    'materials', (select coalesce(jsonb_agg(jsonb_build_object('from', mem.display_name, 'name', rm.name, 'body', rm.body) order by rm.created_at), '[]'::jsonb)
                    from public.round_materials rm join public.members mem on mem.id = rm.member_id
                   where rm.question_id = q.id and rm.member_id <> c.member_id and mem.removed_at is null
                     and exists (select 1 from public.connections sc where sc.member_id = rm.member_id and sc.revoked_at is null
                                   and sc.open_paths and sc.share_paths)),
    -- What was attached to the message being answered, and to the few before it in the same chat.
    'attachments', (select coalesce(jsonb_agg(x order by x.created_at), '[]'::jsonb) from (
                      select a.id, a.name, a.mime, a.size, a.kind, a.path, l.url, a.created_at, mem.display_name as "from"
                        from public.attachments a join public.attachment_links l on l.attachment_id = a.id
                        join public.messages am on am.id = a.message_id join public.members mem on mem.id = a.member_id
                       where am.chat_id = j.chat_id and am.created_at <= q.created_at and am.created_at > q.created_at - interval '2 hours'
                       order by a.created_at desc limit 8) x),
    -- A message that starts with "/" runs one of the asker's own AI's commands. Its name, and what it is for only to
    -- the asker's own AI (or for a command every Claude has built in): someone's own commands stay theirs.
    'command', (select jsonb_build_object('name', cmd ->> 'name', 'mine', q.member_id = c.member_id)
                       || case when q.member_id = c.member_id or cmd ->> 'kind' = 'builtin'
                               then jsonb_build_object('about', cmd ->> 'about') else '{}'::jsonb end
                  from public.connections ac, jsonb_array_elements(ac.commands) cmd
                 where ac.member_id = q.member_id and ac.revoked_at is null
                   and q.body ~ '^\s*/' and lower(cmd ->> 'name') = lower(substring(q.body from '^\s*/([A-Za-z0-9:_-]+)'))
                 order by ac.last_seen desc nulls last limit 1),
    -- The pages in this chat, with their newest HTML, so a page can be changed when asked.
    'pages', case when j.kind in ('look', 'answer', 'work', 'combine', 'notes') then public.pages_for_job(j) else '[]'::jsonb end,
    -- The person's own choices for their AI's runs.
    'effort', c.effort, 'fast', c.fast, 'mode', c.mode, 'in_folder', c.in_folder, 'push_anywhere', c.push_anywhere, 'browser', c.browser, 'use_repo', c.use_repo,
    -- Where the team shares its code, as the owner set it: the connection reads and lands work there when its own
    -- copy of the project knows that repository.
    'repo', (select tc.repo_url from public.table_code tc where tc.table_id = j.table_id),
    -- The person runs their AI as their full Claude Code (their own rules, approvals on their screen), and only for
    -- their own request: a teammate's or a client's message never drives their full Claude Code.
    'full', coalesce(c.kind = 'claude' and c.full_claude and q.member_id = c.member_id and j.kind not in ('intro', 'combine'), false),
    'question', q.body, 'question_pasted', q.meta -> 'pasted',
    'history', history,
    'views', views,
    'stage', j.stage,
    'brief', j.brief,
    'reference', (select tk.reference from public.tasks tk where tk.id = j.task_id),
    'task_title', (select tk.title from public.tasks tk where tk.id = j.task_id),
    'branch', (select tk.branch from public.tasks tk where tk.id = j.task_id),
    'team', (select coalesce(jsonb_agg(distinct mem.display_name), '[]'::jsonb)
               from public.connections cn join public.members mem on mem.id = cn.member_id and mem.role in ('owner', 'developer')
              where cn.table_id = j.table_id and cn.revoked_at is null and cn.kind = 'claude'
                and cn.last_seen > now() - interval '60 seconds' and cn.member_id <> c.member_id
                and (j.chat_id is null or public.member_sees_chat(j.chat_id, cn.member_id))),
    -- Who is at the table, and what its clients have asked for that is still open: plain facts every AI here may
    -- need, the quick listener most of all.
    'people', (select coalesce(jsonb_agg(jsonb_build_object('name', mem.display_name, 'role', mem.role,
                 'ai', (select cn.kind from public.connections cn where cn.member_id = mem.id and cn.revoked_at is null
                          and cn.last_seen > now() - interval '60 seconds' order by cn.last_seen desc limit 1)) order by mem.created_at), '[]'::jsonb)
                 from public.members mem where mem.table_id = j.table_id and mem.removed_at is null),
    'requests', (select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb) from (
                   select mem.display_name as "from", left(r.title, 160) as title, r.status, r.created_at
                     from public.requests r join public.members mem on mem.id = r.member_id
                    where r.table_id = j.table_id and r.status not in ('done', 'decided')
                    order by r.created_at desc limit 15) x),
    'tasks', (select coalesce(jsonb_agg(x order by x.created_at), '[]'::jsonb) from (
                select tk.id, tk.title, tk.status, tk.created_at, mem.display_name as asked_by,
                       (select ch.name from public.chats ch where ch.id = tk.chat_id) as chat
                  from public.tasks tk left join public.members mem on mem.id = tk.member_id
                 where tk.table_id = j.table_id and (tk.status = 'working' or tk.created_at > now() - interval '3 days')
                   and public.member_sees_chat(tk.chat_id, c.member_id)
                 order by tk.created_at desc limit 8) x),
    'worker', (select mem.display_name from public.jobs w join public.members mem on mem.id = w.member_id where w.round = j.round and w.kind = 'work' limit 1),
    'work_read', (select m.meta ->> 'read' from public.jobs w join public.messages m on m.id = w.result_message_id
                   where w.round = j.round and w.kind = 'work' and w.status = 'done' and coalesce((w.outcome ->> 'changed')::boolean, false)
                   order by w.stage desc limit 1),
    'related', related,
    'pinned', pinned);
end;
$$;

--
-- Name: runner_commands(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_commands(token text, list jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c public.connections := public.connection_for(token);
  clean jsonb;
begin
  select coalesce(jsonb_agg(jsonb_build_object(
           'name', left(x ->> 'name', 60),
           'about', left(public.hide_secrets(coalesce(x ->> 'about', '')), 200),
           'kind', case when x ->> 'kind' in ('command', 'skill', 'prompt', 'builtin') then x ->> 'kind' else 'command' end)), '[]'::jsonb)
    into clean
    from (select x from jsonb_array_elements(coalesce(list, '[]'::jsonb)) x
           where x ->> 'name' ~ '^[A-Za-z0-9][A-Za-z0-9:_-]{0,59}$' limit 300) s;
  update public.connections set commands = clean where id = c.id;
  return jsonb_array_length(clean);
end;
$_$;

--
-- Name: runner_fail(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_fail(token text, job uuid, reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  j public.jobs;
  rnd uuid;
begin
  select round into rnd from public.jobs where id = job;
  if rnd is not null then
    perform pg_advisory_xact_lock(hashtext(rnd::text));
  end if;
  select * into j from public.jobs where id = job for update;
  if not found or j.member_id <> c.member_id or j.status <> 'running' then
    raise exception 'this job is not yours';
  end if;
  if j.kind = 'client' then
    perform public.give_up_client_job(j.id, reason);
    return;
  end if;
  update public.jobs
     set status = case when j.attempts >= 3 or j.kind = 'listen' then 'failed'::public.job_status else 'queued'::public.job_status end,
         error = public.hide_secrets(left(coalesce(reason, ''), 500)), lease_until = null,
         created_at = case when j.attempts >= 3 or j.kind = 'listen' then created_at else now() end
   where id = j.id;
  if j.round is not null then
    perform public.advance_round(j.round);
  end if;
end;
$$;

--
-- Name: runner_finish(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_finish(token text, job uuid, answer text, info jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  looker uuid;
  c public.connections := public.connection_for(token);
  j public.jobs;
  sb public.sandboxes;
  msg uuid;
  clean text := public.hide_secrets(left(coalesce(answer, ''), 8000));
  who text;
  kind_out text;
  meta jsonb;
  line public.client_lines;
  passing boolean;
  req uuid;
  act text;
  q public.messages;
  parts jsonb := '[]'::jsonb;
  p jsonb;
  target uuid;
  matches integer;
  mine text;
  tk uuid;
  rnd uuid;
  ch public.sandbox_changes;
begin
  select round into rnd from public.jobs where id = job;
  if rnd is not null then
    perform pg_advisory_xact_lock(hashtext(rnd::text));
  end if;
  select * into j from public.jobs where id = job for update;
  if not found or j.member_id <> c.member_id or j.status <> 'running' then
    raise exception 'this job is not yours to finish';
  end if;

  if j.kind = 'client' then
    -- The team's assistant could not answer from what it has: a team Claude that can read the code answers the
    -- question it wrote, in its own words (stage 1). The client's own words never reach that AI.
    if j.subject is not null and coalesce(j.stage, 0) = 0 and coalesce((info ->> 'look')::boolean, false)
       and btrim(coalesce(info ->> 'ask', '')) <> '' then
      looker := public.client_look_seat(j.table_id);
      if looker is not null then
        update public.jobs set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage') where id = j.id;
        insert into public.jobs (table_id, member_id, kind, line_id, subject, stage, brief)
          values (j.table_id, looker, 'client', j.line_id, j.subject, 1, public.hide_secrets(left(btrim(info ->> 'ask'), 2000)));
        return null;
      end if;
    end if;
    -- Their words were meant for the person on the team talking with them: the assistant says nothing. The line is
    -- marked so their page stops showing the answer forming. Only ever while a person is talking there (team_talking).
    if j.subject is not null and coalesce(j.stage, 0) = 0 and coalesce((info ->> 'quiet')::boolean, false)
       and exists (select 1 from public.client_lines l where l.member_id = j.subject and l.who = 'team' and l.created_at > now() - interval '30 minutes') then
      update public.client_lines set quiet = true where id = j.line_id;
      update public.jobs set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage') where id = j.id;
      return null;
    end if;
    select * into line from public.client_lines where id = j.line_id;
    -- A change for a client's own copy: the team's assistant said so (copy), or a connection from before it could say
    -- so passed on a client who has a copy. Built in the copy like any change they make there; the copy's own words
    -- tell them how it went, so the assistant writes nothing. If the copy cannot take it now, it is passed on.
    if j.subject is not null and coalesce(j.stage, 0) = 0 and line.request_id is null
       and exists (select 1 from public.sandboxes s where s.member_id = j.subject and s.mode = 'sandbox')
       and (coalesce((info ->> 'copy')::boolean, false)
            or (not (info ? 'copy') and coalesce((info ->> 'pass_on')::boolean, true))) then
      target := public.copy_seat(j.table_id);
      select count(*)::integer into matches from public.sandbox_changes x where x.member_id = j.subject and x.created_at > now() - interval '24 hours' and not x.test;
      if target is not null and coalesce(matches < (select ts.cap from public.table_sandbox ts where ts.table_id = j.table_id), true) then
        insert into public.sandbox_changes (table_id, member_id, words)
          values (j.table_id, j.subject, coalesce(nullif(btrim(left(public.hide_secrets(info ->> 'change'), 2000)), ''), line.body)) returning * into ch;
        insert into public.jobs (table_id, member_id, kind, change_id) values (j.table_id, target, 'sandbox', ch.id);
        update public.jobs set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage') where id = j.id;
        return null;
      end if;
      -- The copy cannot take it now (no team Claude on, the computer that builds copies is off, or the day's changes
      -- used up): it goes to the team, and the
      -- client is told so instead of "trying it in your copy".
      passing := true;
      clean := case
        when target is not null then 'You''ve used today''s changes for your copy, so I''ve left the team a message about it. You''ll hear back here.'
        when public.copy_builder(j.table_id) is not null then
          (select split_part(m.display_name, ' ', 1) from public.members m where m.id = public.copy_builder(j.table_id))
          || '''s computer is off right now, so I''ve left them a message. You''ll hear back here.'
        else 'The team''s computers are off right now, so I''ve left them a message. You''ll hear back here.' end;
    end if;
    passing := coalesce(passing, false) or (coalesce((info ->> 'pass_on')::boolean, true) and not coalesce((info ->> 'copy')::boolean, false)) or btrim(clean) = '';
    -- Words that already reached the team (nobody's AI was on when they were said) are never passed on twice.
    if line.request_id is not null then
      passing := false;
    end if;
    if passing then
      req := public.pass_on_request(coalesce(j.subject, j.member_id), line.body, public.hide_secrets(left(coalesce(info ->> 'title', ''), 120)), line.id, false);
    end if;
    insert into public.client_lines (table_id, member_id, who, body, request_id, by_table)
      values (j.table_id, coalesce(j.subject, j.member_id), 'assistant',
              coalesce(nullif(btrim(left(clean, 4000)), ''), 'Passed on to the team. You will hear here what they decide.'), req, j.subject is not null)
      returning id into msg;
    update public.jobs
       set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage')
     where id = j.id;
    return msg;
  end if;

  -- A change in a client's sandbox. What the client reads is the plain summary; the files and the rest are the team's.
  -- A copy's newest commit, whenever one is pushed (made, caught up, a change, one taken back): "Try it" waits until the
  -- hosting has that one online. Unchanged, nothing is waited for.
  if j.kind = 'sandbox' and coalesce(info ->> 'commit', '') ~ '^[0-9a-f]{7,40}$' then
    update public.sandboxes
       set tip_at = case when public.same_commit(tip, info ->> 'commit') then tip_at else now() end,
           tip = info ->> 'commit'
     where member_id = j.subject or member_id = (select sc.member_id from public.sandbox_changes sc where sc.id = j.change_id);
  end if;
  -- Whether the copy could take in the team's latest. Falling behind is said once to the team in General (the client's
  -- page says it too); catching up again clears it.
  if j.kind = 'sandbox' and info ? 'stale' then
    select s.* into sb from public.sandboxes s
     where s.member_id = coalesce(j.subject, (select sc.member_id from public.sandbox_changes sc where sc.id = j.change_id)) for update;
    if found and coalesce((info ->> 'stale')::boolean, false) and sb.behind_since is null then
      update public.sandboxes set behind_since = now() where member_id = sb.member_id;
      insert into public.messages (table_id, chat_id, member_id, body, kind, meta)
        select sb.table_id, ch2.id, (select tb.main_owner from public.tables tb where tb.id = sb.table_id),
               (select split_part(m.display_name, ' ', 1) from public.members m where m.id = sb.member_id)
                 || '''s copy no longer fits your latest work: some of your changes clash with theirs, so their copy stays on an older version. They have been told. It catches up by itself once the two fit again.',
               'github', jsonb_build_object('event', 'copy_behind')
          from public.chats ch2 where ch2.table_id = sb.table_id and ch2.is_general;
    elsif found and not coalesce((info ->> 'stale')::boolean, false) and sb.behind_since is not null then
      update public.sandboxes set behind_since = null where member_id = sb.member_id;
    end if;
  end if;
  if j.kind = 'sandbox' and j.change_id is null then
    update public.sandboxes set opened_at = now() where member_id = j.subject;
    update public.jobs set status = 'done', finished_at = now(), lease_until = null where id = j.id;
    return null;
  end if;
  -- One change taken back out of the copy. A connection from before this answers without saying (it only looked), and
  -- then nothing happened: the change can be taken back again later.
  if j.kind = 'sandbox' and j.brief = 'undo' then
    update public.sandbox_changes
       set undone = case when info ? 'undone' then case when (info ->> 'undone')::boolean then 'undone' else 'stuck' end else null end
     where id = j.change_id and undone = 'undoing';
    update public.jobs set status = 'done', finished_at = now(), lease_until = null where id = j.id;
    return null;
  end if;
  if j.kind = 'sandbox' then
    select * into ch from public.sandbox_changes where id = j.change_id for update;
    if coalesce((info ->> 'pass_on')::boolean, false) and ch.test then
      update public.sandbox_changes set status = 'nothing', finished_at = now(), summary = left(clean, 1200),
             detail = public.hide_secrets(left(coalesce(info ->> 'detail', ''), 4000)) where id = ch.id;
    elsif coalesce((info ->> 'pass_on')::boolean, false) then
      -- Not a change to try out: a question, or something only the team can do. It goes to the team as a request.
      req := public.pass_on_request(ch.member_id, ch.words, public.hide_secrets(left(coalesce(info ->> 'title', ''), 120)), null, false);
      update public.sandbox_changes
         set status = 'passed', request_id = req, finished_at = now(),
             detail = public.hide_secrets(left(coalesce(info ->> 'detail', ''), 4000)),
             summary = coalesce(nullif(btrim(left(clean, 1200)), ''), 'That one is for the team, so I passed it on. You will hear here what they decide.')
       where id = ch.id;
    elsif coalesce((info ->> 'changed')::boolean, false) then
      update public.sandbox_changes
         set status = 'ready', finished_at = now(), summary = left(clean, 1200),
             detail = public.hide_secrets(left(coalesce(info ->> 'detail', ''), 4000)),
             files = public.kept_list(info -> 'files', 80),
             commit = case when coalesce(info ->> 'commit', '') ~ '^[0-9a-f]{7,40}$' then info ->> 'commit' else null end,
             stale = coalesce((info ->> 'stale')::boolean, false)
       where id = ch.id;
    else
      update public.sandbox_changes
         set status = 'nothing', finished_at = now(),
             summary = coalesce(nullif(btrim(left(clean, 1200)), ''), 'Nothing was changed.'),
             detail = public.hide_secrets(left(coalesce(info ->> 'detail', ''), 4000))
       where id = ch.id;
    end if;
    update public.jobs
       set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage')
     where id = j.id;
    return null;
  end if;

  if j.kind = 'notes' then
    update public.jobs set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage') where id = j.id;
    update public.chats set noted_at = j.created_at where id = j.chat_id and (noted_at is null or noted_at < j.created_at);
    return null;
  end if;

  if j.kind = 'listen' then
    act := case when info ->> 'act' in ('reply', 'look', 'work') then info ->> 'act' else 'silent' end;
    update public.jobs
       set status = 'done', finished_at = now(), lease_until = null, usage = public.kept_usage(info -> 'usage'),
           outcome = jsonb_build_object('act', act)
     where id = j.id;
    select * into q from public.messages where id = j.question_id;
    if act = 'reply' and btrim(clean) <> '' then
      insert into public.messages (table_id, chat_id, member_id, body, by_ai, kind, meta)
        values (j.table_id, j.chat_id, j.member_id, left(clean, 1500), true, 'answer',
                jsonb_build_object('job', j.id, 'model', public.kept_line(info ->> 'model', 80), 'sources', '[]'::jsonb, 'part', 'reply'))
        returning id into msg;
      update public.jobs set result_message_id = msg where id = j.id;
    end if;
    -- An early run that is not needed after all is stopped; one already under way as the look is kept.
    if act <> 'look' then
      update public.jobs set status = 'skipped', lease_until = null, error = 'not needed'
       where question_id = j.question_id and kind in ('look', 'view') and early and status in ('queued', 'running', 'waiting');
    end if;
    if act = 'look' and exists (select 1 from public.jobs e where e.question_id = j.question_id and e.kind = 'look' and e.early and e.status in ('queued', 'running', 'waiting', 'done')) then
      null;
    elsif act = 'look' then
      -- A look is done by the Claude of whoever asked, when it is on: it is the one that knows what they know. Else by
      -- the table's seat. The other AIs that are on give their views first.
      perform public.start_look(j.table_id, j.chat_id, j.question_id,
        coalesce((select cn.member_id from public.connections cn
                   where cn.member_id = q.member_id and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds' limit 1), j.member_id),
        false);
    elsif act = 'work' and q.id is not null then
      -- A follow-up goes on with the task it belongs to; anything else is a new task with its own branch.
      select t2.id into tk from public.tasks t2 where t2.table_id = j.table_id and t2.id::text = coalesce(info ->> 'task', '');
      perform public.start_round(j.table_id, j.chat_id, q.id, q.member_id, tk, public.hide_secrets(left(coalesce(info ->> 'title', ''), 80)));
    end if;
    return msg;
  end if;

  if btrim(clean) = '' then
    raise exception 'an answer cannot be empty';
  end if;
  select display_name into who from public.members where id = j.member_id;
  kind_out := case when j.kind in ('view', 'work', 'review', 'plan') then 'view' when j.kind = 'intro' then 'intro' else 'answer' end;
  meta := jsonb_build_object(
    'job', j.id, 'round', j.round, 'read', public.kept_line(info ->> 'read', 300), 'model', public.kept_line(info ->> 'model', 80),
    'sources', public.kept_list(info -> 'sources', 40),
    'how', public.hide_secrets(left(coalesce(info ->> 'how', ''), 4000)),
    'confidence', public.kept_line(info ->> 'confidence', 40),
    'part', j.kind, 'stage', j.stage, 'task', j.task_id, 'ok', info -> 'ok', 'changed', info -> 'changed',
    'hidden', clean <> left(coalesce(answer, ''), 8000));
  if j.kind = 'combine' or (j.kind = 'look' and j.round is not null) then
    meta := meta || jsonb_build_object('parts', (
      select coalesce(jsonb_agg(distinct v.member_id), '[]'::jsonb) from public.jobs v
       where v.round = j.round and v.kind in ('view', 'work', 'review') and v.status = 'done' and v.member_id <> j.member_id));
  end if;

  -- The plan: who does which part. A part goes to a person's Claude only when that Claude is on right now; anything
  -- handed to someone who is not there stays with the one who planned.
  if j.kind = 'plan' then
    mine := coalesce(info ->> 'mine', '');
    for p in select * from jsonb_array_elements(case when jsonb_typeof(info -> 'handoffs') = 'array' then info -> 'handoffs' else '[]'::jsonb end) loop
      continue when btrim(coalesce(p ->> 'what', '')) = '';
      -- A full name exactly; else a first name, only when exactly one person here has it.
      select mem.id into target
        from public.members mem join public.connections cn on cn.member_id = mem.id
       where mem.table_id = j.table_id and mem.role in ('owner', 'developer') and mem.id <> j.member_id and mem.removed_at is null and public.member_sees_chat(j.chat_id, mem.id)
         and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
         and lower(btrim(mem.display_name)) = lower(btrim(p ->> 'to'))
       limit 1;
      if target is null then
        select (array_agg(distinct mem.id))[1], count(distinct mem.id) into target, matches
          from public.members mem join public.connections cn on cn.member_id = mem.id
         where mem.table_id = j.table_id and mem.role in ('owner', 'developer') and mem.id <> j.member_id and mem.removed_at is null and public.member_sees_chat(j.chat_id, mem.id)
           and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
           and split_part(lower(btrim(mem.display_name)), ' ', 1) = lower(btrim(p ->> 'to'));
        if matches <> 1 then
          target := null;
        end if;
      end if;
      if target is null then
        mine := left(btrim(mine || E'\n' || left(p ->> 'what', 4000)), 12000);
      elsif exists (select 1 from jsonb_array_elements(parts) e where e ->> 'member' = target::text) then
        parts := (select jsonb_agg(case when e ->> 'member' = target::text
                    then jsonb_set(e, '{brief}', to_jsonb(left((e ->> 'brief') || E'\n' || public.hide_secrets(left(p ->> 'what', 4000)), 8000))) else e end) from jsonb_array_elements(parts) e);
      else
        parts := parts || jsonb_build_object('member', target, 'brief', public.hide_secrets(left(p ->> 'what', 4000)));
      end if;
    end loop;
    if jsonb_array_length(parts) > 0 and nullif(btrim(mine), '') is not null then
      parts := jsonb_build_object('member', j.member_id, 'brief', public.hide_secrets(left(btrim(mine), 4000))) || parts;
    end if;
  end if;

  insert into public.messages (table_id, chat_id, member_id, body, by_ai, kind, meta)
    values (j.table_id, j.chat_id, j.member_id, clean, true, kind_out, meta)
    returning id into msg;

  if j.kind = 'intro' then
    insert into public.notes (table_id, member_id, kind, title, body)
      values (j.table_id, j.member_id, 'intro', who || '''s Claude', left(clean, 4000))
      on conflict (table_id, member_id) where kind = 'intro'
      do update set body = excluded.body, updated_at = now();
    if coalesce(btrim(info ->> 'summary'), '') <> '' then
      insert into public.notes (table_id, member_id, kind, title, body)
        values (j.table_id, j.member_id, 'summary', 'The project', public.hide_secrets(left(info ->> 'summary', 4000)))
        on conflict (table_id) where kind = 'summary' do nothing;
    end if;
  end if;

  update public.jobs
     set status = 'done', result_message_id = msg, finished_at = now(), lease_until = null,
         usage = public.kept_usage(info -> 'usage'),
         outcome = jsonb_build_object('changed', coalesce((info ->> 'changed')::boolean, false), 'ok', coalesce((info ->> 'ok')::boolean, true), 'parts', parts)
   where id = j.id;
  if j.round is not null and j.kind = 'combine' then
    update public.jobs set status = 'skipped', lease_until = null, error = 'the answer was already given'
     where round = j.round and id <> j.id and status in ('queued', 'running', 'waiting');
  end if;
  if j.task_id is not null and j.kind in ('answer', 'combine') then
    update public.tasks set status = 'done', finished_at = now(), result = public.hide_secrets(left(info ->> 'read', 200))
     where id = j.task_id and status = 'working'
       and not exists (select 1 from public.jobs o where o.task_id = j.task_id and o.id <> j.id and o.status in ('queued', 'running', 'waiting'));
  end if;
  if j.round is not null then
    perform public.release_rounds();
    perform public.advance_round(j.round);
  end if;
  perform public.log_activity(j.table_id, j.member_id, 'ai.' || j.kind, msg, jsonb_build_object('job', j.id));
  return msg;
end;
$_$;

--
-- Name: runner_hello(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_hello(token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
begin
  return jsonb_build_object(
    'table_id', c.table_id,
    'table_name', (select name from public.tables where id = c.table_id),
    'member_id', c.member_id,
    'member_name', (select display_name from public.members where id = c.member_id),
    'role', (select role from public.members where id = c.member_id),
    'kind', c.kind);
end;
$$;

--
-- Name: runner_inbox(text, uuid, boolean, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_inbox(token text, job uuid, open boolean DEFAULT true, seen uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  j public.jobs;
  q public.messages;
  got jsonb;
  back timestamptz;
begin
  select * into j from public.jobs where id = job and member_id = c.member_id for update;
  if not found then
    raise exception 'that job is not this connection''s';
  end if;
  if not coalesce(open, true) then
    update public.jobs set taking = false where id = job;
    update public.delivered_messages set confirmed = true where job_id = job and message_id = any(coalesce(seen, '{}'::uuid[]));
    select min(m.created_at) into back from public.messages m
      join public.delivered_messages d on d.message_id = m.id and d.job_id = job and not d.confirmed;
    delete from public.delivered_messages where job_id = job and not confirmed;
    if back is not null then
      insert into public.listens (chat_id, table_id, since, due_at) values (j.chat_id, j.table_id, back, now() + interval '4 seconds')
        on conflict (chat_id) do update set since = least(public.listens.since, excluded.since), due_at = least(public.listens.due_at, excluded.due_at);
    end if;
    return '[]'::jsonb;
  end if;
  select * into q from public.messages where id = j.question_id;
  -- Only a run of the person's own request, while it runs.
  if j.status <> 'running' or q.id is null or q.member_id <> c.member_id then
    return '[]'::jsonb;
  end if;
  if not j.taking then
    -- A new attempt at this job (its connection restarted): what an earlier attempt was handed but never read is
    -- handed over again.
    delete from public.delivered_messages where job_id = job and not confirmed;
    update public.jobs set taking = true where id = job;
  end if;
  with fresh as (
    select m.id, m.body, m.created_at, m.meta -> 'pasted' as pasted from public.messages m
     where m.chat_id = j.chat_id and m.member_id = c.member_id and m.kind = 'chat' and not m.by_ai and not m.no_ai
       and m.created_at > q.created_at and m.id <> q.id
       -- Not one that is a request of its own (asked outright, or already heard), not a command, not one with files:
       -- those go to the table as usual.
       and not exists (select 1 from public.jobs jj where jj.question_id = m.id)
       and m.body !~ '^\s*/[A-Za-z]'
       and not exists (select 1 from public.attachments a where a.message_id = m.id)
       and not exists (select 1 from public.delivered_messages d where d.message_id = m.id)
     order by m.created_at limit 20
  ), kept as (
    insert into public.delivered_messages (message_id, job_id) select id, job from fresh on conflict do nothing returning message_id
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'body', f.body, 'at', f.created_at, 'pasted', f.pasted) order by f.created_at), '[]'::jsonb)
    into got from fresh f where f.id in (select message_id from kept);
  return got;
end;
$$;

--
-- Name: runner_job_key(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_job_key(token text, job uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  k text := encode(extensions.gen_random_bytes(24), 'hex');
  t uuid;
  m uuid;
begin
  if not c.full_claude then
    raise exception 'this AI is not set to run as full Claude Code';
  end if;
  update public.jobs set approval_key = encode(extensions.digest(k, 'sha256'), 'hex')
   where id = job and member_id = c.member_id and table_id = c.table_id and status = 'running'
   returning table_id, member_id into t, m;
  if not found then
    raise exception 'that job is not running on this connection';
  end if;
  if exists (select 1 from public.approvals where job_id = job and status = 'waiting') then
    update public.approvals set status = 'expired', decided_at = now() where job_id = job and status = 'waiting';
    perform realtime.send(jsonb_build_object('table', 'approvals', 'record', jsonb_build_object('member_id', m)), 'UPDATE', 'team:' || t::text, true);
  end if;
  return k;
end;
$$;

--
-- Name: runner_leave(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_leave(token text, reason text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
begin
  update public.connections set revoked_at = now() where id = c.id and revoked_at is null;
  update public.jobs set status = 'failed', lease_until = null, finished_at = now(), error = coalesce(public.kept_line(reason, 300), 'the connection did not finish setting up')
   where member_id = c.member_id and kind = 'intro' and status in ('queued', 'running');
  perform public.log_activity(c.table_id, c.member_id, 'connection.removed', c.id, jsonb_build_object('kind', c.kind, 'setup_failed', true));
end;
$$;

--
-- Name: runner_local(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_local(token text, port integer, key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c public.connections := public.connection_for(token);
  ok boolean := public.local_allowed(c);
  want jsonb;
begin
  if port is null or port not between 1024 and 65535 or key is null or key !~ '^[A-Za-z0-9_-]{32,64}$' then
    raise exception 'a bridge needs a port and a key';
  end if;
  want := case when ok then jsonb_build_object('port', port, 'key', key) end;
  update public.connections set local = want where id = c.id and local is distinct from want;
  return ok;
end;
$_$;

