--
-- Name: runner_report(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_report(token text, limits jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c public.connections := public.connection_for(token);
begin
  if runner_report.limits is null or jsonb_typeof(runner_report.limits) <> 'object' or octet_length(runner_report.limits::text) > 4000 then
    raise exception 'limits must be a small object';
  end if;
  update public.connections
     set limits = jsonb_build_object(
           'ai', coalesce(runner_report.limits ->> 'ai', c.limits ->> 'ai'),
           'plan', coalesce(left(runner_report.limits ->> 'plan', 40), c.limits ->> 'plan'),
           'model', coalesce(left(runner_report.limits ->> 'model', 60), c.limits ->> 'model'),
           'status', coalesce(runner_report.limits ->> 'status', c.limits ->> 'status'),
           -- The version of the connection itself, so its window shows it and an update can be seen to have taken.
           'version', case when runner_report.limits ->> 'version' ~ '^\d+\.\d+\.\d+$' then runner_report.limits ->> 'version' else c.limits ->> 'version' end,
           -- Whether longtable:// on that computer starts the connection, so the Reconnect window can start it.
           'wake', case when jsonb_typeof(runner_report.limits -> 'wake') = 'boolean' then runner_report.limits -> 'wake' else coalesce(c.limits -> 'wake', 'false'::jsonb) end,
           -- Which common tools its Claude finds on that computer: known names only.
           'tools', case when jsonb_typeof(runner_report.limits -> 'tools') = 'array' then coalesce((
               select jsonb_agg(distinct t) from jsonb_array_elements_text(runner_report.limits -> 'tools') t
                where t in ('git', 'node', 'npm', 'docker', 'python')), '[]'::jsonb)
             else c.limits -> 'tools' end,
           -- What it reads: the repository's address (only a plain one, never with a sign-in in it), the last part of
           -- its person's own folder, and whether the table's repository is one that computer knows.
           'reads', case when jsonb_typeof(runner_report.limits -> 'reads') = 'object' then jsonb_build_object(
               'repo', case when runner_report.limits -> 'reads' ->> 'repo' ~ '^(https://[A-Za-z0-9.-]+/[A-Za-z0-9/._~+-]{1,200}|git@[A-Za-z0-9.-]+:[A-Za-z0-9/._~+-]{1,200}|ssh://[A-Za-z0-9.-]+(:[0-9]+)?/[A-Za-z0-9/._~+-]{1,200})$'
                 then runner_report.limits -> 'reads' ->> 'repo' end,
               'folder', case when runner_report.limits -> 'reads' ->> 'folder' ~ '^[^/\\]{1,80}$'
                 then public.hide_secrets(runner_report.limits -> 'reads' ->> 'folder') end,
               'known', coalesce(runner_report.limits -> 'reads' ->> 'known', 'true') <> 'false')
             else c.limits -> 'reads' end,
           -- Whether fast mode can serve this AI, as its Claude Code said, and why not.
           'fast', case when runner_report.limits ->> 'fast' in ('off', 'on', 'cooldown') then runner_report.limits ->> 'fast' else c.limits ->> 'fast' end,
           'fast_why', case when runner_report.limits ? 'fast' then left(nullif(regexp_replace(coalesce(runner_report.limits ->> 'fast_why', ''), '[^a-z_]', '', 'g'), ''), 40) else c.limits ->> 'fast_why' end,
           'models', case when jsonb_typeof(runner_report.limits -> 'models') = 'array' then coalesce((
             select jsonb_agg(left(v, 40)) from (
               select v from jsonb_array_elements_text(runner_report.limits -> 'models') v limit 12) picked), '[]'::jsonb)
             else coalesce(c.limits -> 'models', '[]'::jsonb) end,
           'windows', case when jsonb_typeof(runner_report.limits -> 'windows') = 'array' then coalesce((
             select jsonb_agg(jsonb_build_object(
                      'name', left(w ->> 'name', 20),
                      'used', least(greatest(coalesce((w ->> 'used')::numeric, 0), 0), 100),
                      'resets', w ->> 'resets'))
               from jsonb_array_elements(runner_report.limits -> 'windows') w
              where jsonb_typeof(w) = 'object'), '[]'::jsonb)
             else coalesce(c.limits -> 'windows', '[]'::jsonb) end),
         limits_at = now()
   where id = c.id;
end;
$_$;

--
-- Name: runner_share(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_share(token text, job uuid, files jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections := public.connection_for(token);
  j public.jobs;
  q public.messages;
  f jsonb;
  n integer := 0;
  total integer := 0;
  have integer := 0;
begin
  select * into j from public.jobs where id = job and member_id = c.member_id and status = 'running';
  if not found then
    raise exception 'this job is not yours';
  end if;
  select * into q from public.messages where id = j.question_id;
  -- Only what the connection's own person pointed at, and only while they leave sharing on.
  if q.id is null or q.member_id <> c.member_id or not (c.open_paths and c.share_paths) then
    return 0;
  end if;
  -- The limits are for the request, not for one call: what this connection already shared for it counts.
  select count(*), coalesce(sum(char_length(rm.body)), 0) into have, total
    from public.round_materials rm where rm.question_id = q.id and rm.member_id = c.member_id;
  for f in select x from jsonb_array_elements(coalesce(files, '[]'::jsonb)) x limit 8 loop
    continue when char_length(coalesce(f ->> 'name', '')) not between 1 and 400 or char_length(coalesce(f ->> 'body', '')) = 0;
    continue when char_length(f ->> 'body') > 120000 or total + char_length(f ->> 'body') > 360000;
    -- A ninth name is left out; one already shared may still be replaced.
    continue when have >= 8 and not exists (select 1 from public.round_materials rm
      where rm.question_id = q.id and rm.member_id = c.member_id and rm.name = f ->> 'name');
    insert into public.round_materials (table_id, question_id, member_id, name, body)
      values (j.table_id, q.id, c.member_id, f ->> 'name', public.hide_secrets(f ->> 'body'))
      on conflict (question_id, member_id, name) do update set body = excluded.body, created_at = now();
    select count(*) into have from public.round_materials rm where rm.question_id = q.id and rm.member_id = c.member_id;
    total := total + char_length(f ->> 'body');
    n := n + 1;
  end loop;
  return n;
end;
$$;

--
-- Name: runner_upload_slot(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.runner_upload_slot(key text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs := public.job_for_key(key);
  k text := encode(extensions.gen_random_bytes(16), 'hex');
begin
  if (select count(*) from public.attachments where job_id = j.id) >= 8 or (select count(*) from public.upload_slots where job_id = j.id) >= 12 then
    raise exception 'eight files at most in one answer';
  end if;
  insert into public.upload_slots (key, job_id, table_id, expires_at) values (k, j.id, j.table_id, now() + interval '10 minutes');
  delete from public.upload_slots where expires_at < now() - interval '1 day';
  return j.table_id::text || '/ai-' || k || '/';
end;
$$;

--
-- Name: same_commit(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.same_commit(a text, b text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(char_length(a) >= 7 and char_length(b) >= 7 and (starts_with(a, b) or starts_with(b, a)), false);
$$;

--
-- Name: same_repo(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.same_repo(a text, b text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select coalesce(regexp_replace(lower(btrim(a)), '(\.git)?/*$', '') = regexp_replace(lower(btrim(b)), '(\.git)?/*$', ''), false);
$_$;

