    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.url is distinct from old.url then
    new.open_ok := null;
    new.checked_at := null;
  end if;
  return new;
end;
$$;

--
-- Name: sandbox_job_payload(public.jobs); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sandbox_job_payload(j public.jobs) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.sandbox_changes;
  who public.members;
begin
  if j.change_id is null then
    -- Only the place is being made: the branch, pushed as it stands, so the hosting puts it up.
    return jsonb_build_object('job_id', j.id, 'kind', 'sandbox', 'probe', true, 'fresh', coalesce(j.brief = 'fresh', false),
      'refresh', coalesce(j.brief = 'refresh', false),
      'table_name', (select name from public.tables where id = j.table_id),
      'me', (select display_name from public.members where id = j.member_id),
      'branch', (select s.branch from public.sandboxes s where s.member_id = j.subject));
  end if;
  select * into ch from public.sandbox_changes where id = j.change_id;
  select * into who from public.members where id = ch.member_id;
  if j.brief = 'undo' then
    -- Taking one change back out: its commit, and the words it was for (for the commit's message). Marked a probe
    -- too, so a connection from before undo existed only looks at the branch and changes nothing.
    return jsonb_build_object('job_id', j.id, 'kind', 'sandbox', 'undo', true, 'probe', true, 'commit', ch.commit, 'words', ch.words,
      'me', (select display_name from public.members where id = j.member_id),
      'branch', (select s.branch from public.sandboxes s where s.member_id = ch.member_id));
  end if;
  return jsonb_build_object(
    'job_id', j.id,
    'kind', 'sandbox',
    'table_name', (select name from public.tables where id = j.table_id),
    'me', (select display_name from public.members where id = j.member_id),
    'client', who.display_name,
    'words', ch.words,
    'test', ch.test,
    'branch', (select s.branch from public.sandboxes s where s.member_id = ch.member_id),
    'paths', coalesce((select ts.paths from public.table_sandbox ts where ts.table_id = j.table_id), ''),
    'scope', coalesce((select ts.scope from public.table_sandbox ts where ts.table_id = j.table_id), 'screens'),
    'blocked', coalesce((select ts.blocked from public.table_sandbox ts where ts.table_id = j.table_id), ''),
    'earlier', (select coalesce(jsonb_agg(jsonb_build_object('words', left(c.words, 600), 'summary', left(coalesce(c.summary, ''), 400), 'status', c.status,
                  'verdict', c.verdict, 'note', c.note) order by c.created_at), '[]'::jsonb)
                  from (select * from public.sandbox_changes x where x.member_id = ch.member_id and x.id <> ch.id and x.status <> 'working'
                         order by x.created_at desc limit 12) c));
end;
$$;

--
-- Name: seat_alive(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seat_alive(m uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.members mb join public.connections cn on cn.member_id = mb.id
                  where mb.id = m and mb.removed_at is null and cn.revoked_at is null);
$$;

--
-- Name: send_with_files(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_with_files(c uuid, body text, files jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid;
  me uuid;
  q uuid;
  words text := btrim(coalesce(body, ''));
  got jsonb;
begin
  select ch.table_id into t from public.chats ch where ch.id = c;
  if t is null or not public.can_see_chat(c) or not (select ch.set_up from public.chats ch where ch.id = c) then
    raise exception 'only the team writes here';
  end if;
  if coalesce(jsonb_array_length(files), 0) = 0 then
    raise exception 'nothing is attached';
  end if;
  me := public.my_member_id(t);
  if char_length(words) = 0 then
    words := left((select string_agg(f ->> 'name', ', ') from jsonb_array_elements(files) f), 500);
  end if;
  insert into public.messages (table_id, chat_id, member_id, body) values (t, c, me, left(words, 8000)) returning id into q;
  got := public.take_files(t, me, files, q);
  update public.messages set meta = meta || jsonb_build_object('files', got) where id = q;
  return q;
end;
$$;

--
-- Name: set_ai_mode(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ai_mode(conn uuid, mode text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections;
begin
  select * into c from public.connections where id = conn and revoked_at is null;
  if not found or c.member_id is distinct from public.my_member_id(c.table_id) then
    raise exception 'only its own person sets how their AI asks';
  end if;
  if set_ai_mode.mode not in ('manual', 'acceptEdits', 'auto', 'plan', 'bypass') then
    raise exception 'mode is manual, acceptEdits, auto, plan or bypass';
  end if;
  update public.connections set mode = set_ai_mode.mode where id = conn;
end;
$$;

--
-- Name: set_ai_speed(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ai_speed(conn uuid, effort text DEFAULT NULL::text, fast boolean DEFAULT NULL::boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  cn public.connections;
begin
  select * into cn from public.connections where id = conn and revoked_at is null for update;
  if not found or cn.member_id <> public.my_member_id(cn.table_id) then
    raise exception 'these are yours to set only for your own AI';
  end if;
  if set_ai_speed.effort is not null and set_ai_speed.effort not in ('', 'low', 'medium', 'high', 'xhigh', 'max') then
    raise exception 'effort is low, medium, high, xhigh or max';
  end if;
  update public.connections
     set effort = case when set_ai_speed.effort is null then connections.effort else nullif(set_ai_speed.effort, '') end,
         fast = coalesce(set_ai_speed.fast, connections.fast)
   where id = conn;
end;
$$;

--
-- Name: set_browser(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_browser(conn uuid, on_ boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections;
begin
  select * into c from public.connections where id = conn and revoked_at is null;
  if not found or c.member_id is distinct from public.my_member_id(c.table_id) then
    raise exception 'only its own person decides whether their AI opens pages';
  end if;
  update public.connections set browser = coalesce(on_, false) where id = conn;
end;
$$;

--
-- Name: set_client_answerer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_client_answerer(m uuid, who text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.members;
begin
  select * into c from public.members where id = m and role = 'client' and removed_at is null;
  if not found or not public.may(c.table_id, 'clients') then
    raise exception 'only the owner sets who answers a client';
  end if;
  if who not in ('own', 'table') then
    raise exception 'a client is answered by their own assistant or by the table';
  end if;
  insert into public.client_settings (member_id, table_id, answered_by) values (c.id, c.table_id, who)
    on conflict (member_id) do update set answered_by = excluded.answered_by, updated_at = now();
end;
$$;

--
-- Name: set_client_sandbox(uuid, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_client_sandbox(m uuid, enabled boolean, made_up_data boolean DEFAULT false, no_real_keys boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
  seat uuid;
begin
  select * into who from public.members where id = m and removed_at is null;
  if not found or not public.may(who.table_id, 'clients') then
    raise exception 'only the owner decides what a client can do';
  end if;
  if who.role <> 'client' then
    raise exception 'a sandbox is for a client';
  end if;
  if enabled and not exists (select 1 from public.sandboxes s where s.member_id = m and s.url is not null) then
    raise exception 'set the copy up first: it needs an address to open at';
  end if;
  -- Only the owner can answer these two, and a copy is not given until they have.
  if enabled and not (coalesce(made_up_data, false) and coalesce(no_real_keys, false)) then
    raise exception 'a copy is given only once you have said its previews run on made-up data and hold no real keys';
  end if;
  insert into public.sandboxes (member_id, table_id, mode, branch)
    values (m, who.table_id, case when enabled then 'sandbox' else 'chat' end, 'longtable/sandbox-'
      || coalesce(nullif(btrim(left(regexp_replace(lower(who.display_name), '[^a-z0-9]+', '-', 'g'), 30), '-'), ''), 'client')
      || '-' || left(m::text, 8))
    on conflict (member_id) do update set mode = excluded.mode;
  if enabled then
    update public.sandboxes set ticked_by = public.my_member_id(who.table_id), ticked_at = now() where member_id = m;
  end if;
  insert into public.table_sandbox (table_id) values (who.table_id) on conflict (table_id) do nothing;
  -- What the owner tried in the copy while setting it up is not the client's: the copy goes back to the product as
  -- it stands before it is theirs. The connection does it, with no AI asked anything.
  if enabled and exists (select 1 from public.sandbox_changes c where c.member_id = m and c.test and c.status = 'ready')
     and not exists (select 1 from public.sandbox_changes c where c.member_id = m and not c.test) then
    select cn.member_id into seat
      from public.connections cn join public.members mm on mm.id = cn.member_id and mm.role in ('owner', 'developer')
     where cn.table_id = who.table_id and cn.revoked_at is null and cn.kind = 'claude'
     order by (cn.last_seen > now() - interval '60 seconds') desc, (cn.member_id = public.final_seat_now(who.table_id)) desc, cn.created_at limit 1;
    if seat is not null then
      insert into public.jobs (table_id, member_id, kind, subject, brief) values (who.table_id, seat, 'sandbox', m, 'fresh');
    end if;
  end if;
  -- The client's page hears that what it can do has changed.
  perform realtime.send(jsonb_build_object('table', 'sandbox_changes', 'record', jsonb_build_object('id', m, 'status', 'mode')),
    'UPDATE', 'client:' || who.table_id::text || ':' || m::text, true);
  perform public.log_activity(who.table_id, public.my_member_id(who.table_id), case when enabled then 'sandbox.given' else 'sandbox.taken' end, m,
    jsonb_build_object('name', who.display_name));
end;
$$;

--
-- Name: set_co_owner(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_co_owner(m uuid, co boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
begin
  select * into who from public.members where id = m;
  if not found then raise exception 'only the main owner makes co-owners'; end if;
  perform 1 from public.tables where id = who.table_id for update;
  select * into who from public.members where id = m for update;
  if not public.is_main_owner(who.table_id) then raise exception 'only the main owner makes co-owners'; end if;
  if who.removed_at is not null then raise exception 'they are not at the table'; end if;
  if exists (select 1 from public.tables where id = who.table_id and main_owner = who.id) then raise exception 'that is the main owner'; end if;
  if co and who.role <> 'developer' then raise exception 'only a developer can become a co-owner'; end if;
  if not co and who.role <> 'owner' then raise exception 'they are not a co-owner'; end if;
  update public.members set role = case when co then 'owner'::public.member_role else 'developer'::public.member_role end where id = m;
  perform public.log_activity(who.table_id, public.my_member_id(who.table_id), case when co then 'member.co_owner' else 'member.not_co_owner' end, m,
    jsonb_build_object('name', who.display_name));
end;
$$;

