    AS $$
declare
  cn public.connections;
begin
  select * into cn from public.connections where id = conn and revoked_at is null for update;
  if not found or cn.member_id <> public.my_member_id(cn.table_id) then
    raise exception 'these are yours to set only for your own AI';
  end if;
  update public.connections set open_paths = coalesce(open, open_paths), share_paths = coalesce(share, share_paths) where id = conn;
end;
$$;

--
-- Name: set_copy_builder(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_copy_builder(t uuid, m uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.may(t, 'clients') then
    raise exception 'only the owner sets this';
  end if;
  if m is not null and not exists (select 1 from public.members x where x.id = m and x.table_id = t
                                     and x.role in ('owner', 'developer') and x.removed_at is null) then
    raise exception 'copies are built on the computer of someone on the team';
  end if;
  insert into public.table_sandbox (table_id, builder) values (t, m)
    on conflict (table_id) do update set builder = excluded.builder;
  -- Copy jobs still waiting go to the new builder.
  if m is not null then
    update public.jobs set member_id = m where table_id = t and kind = 'sandbox' and status = 'queued' and member_id <> m;
  end if;
  perform public.log_activity(t, public.my_member_id(t), 'sandbox.builder', null, jsonb_build_object('builder', m));
end;
$$;

--
-- Name: set_copy_rules(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_copy_rules(t uuid, scope text, blocked text DEFAULT ''::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  clean text;
begin
  if not public.may(t, 'clients') then
    raise exception 'only the owner sets this';
  end if;
  if scope not in ('screens', 'code') then
    raise exception 'a copy changes screens only, or screens and the code behind them';
  end if;
  select coalesce(string_agg(f, ', '), '') into clean from (
    select btrim(x) as f from regexp_split_to_table(coalesce(blocked, ''), '[,\n]') x) y where f <> '';
  if clean ~ '[^A-Za-z0-9._/, *-]' or clean ~ '(^|[/ ])\.\.([/, ]|$)' then
    raise exception 'blocked paths are plain paths like prisma/ or proxy.ts, separated by commas';
  end if;
  insert into public.table_sandbox (table_id, scope, blocked) values (t, scope, left(clean, 2000))
    on conflict (table_id) do update set scope = excluded.scope, blocked = excluded.blocked;
  perform public.log_activity(t, public.my_member_id(t), 'sandbox.rules', null, jsonb_build_object('scope', scope));
end;
$_$;

--
-- Name: set_final_seat(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_final_seat(t uuid, seat uuid, offline text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.may(t, 'settings') then
    raise exception 'only the owner changes who writes the final answer';
  end if;
  if seat is not null and not exists (select 1 from public.members where id = seat and table_id = t and role in ('owner', 'developer') and removed_at is null) then
    raise exception 'the final answer has to come from someone on the team';
  end if;
  if offline not in ('wait', 'next') then
    raise exception 'unknown choice';
  end if;
  update public.tables set final_seat = seat, when_final_offline = offline where id = t;
  perform public.log_activity(t, public.my_member_id(t), 'settings.final_seat', seat, jsonb_build_object('offline', offline));
end;
$$;

