    AS $$
declare
  who public.members;
begin
  select * into who from public.members where id = m and removed_at is null;
  if not found or not public.is_owner(who.table_id) then raise exception 'only an owner changes what a teammate may do'; end if;
  if who.role <> 'developer' then raise exception 'only a developer''s access is set: owners have it all, clients none'; end if;
  update public.members set can_settings = coalesce(settings, can_settings), can_invite = coalesce(invite, can_invite),
    can_clients = coalesce(clients, can_clients) where id = m;
  perform public.log_activity(who.table_id, public.my_member_id(who.table_id), 'member.access', m,
    jsonb_build_object('name', who.display_name, 'settings', coalesce(settings, who.can_settings), 'invite', coalesce(invite, who.can_invite), 'clients', coalesce(clients, who.can_clients)));
end;
$$;

--
-- Name: set_model(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_model(conn uuid, model text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  cn public.connections;
  clean text := btrim(coalesce(model, ''));
begin
  select * into cn from public.connections where id = conn and revoked_at is null for update;
  if not found or cn.member_id <> public.my_member_id(cn.table_id) then
    raise exception 'you can only choose the model for your own AI';
  end if;
  if clean !~ '^[A-Za-z0-9._ -]{0,60}$' then
    raise exception 'that is not a model name';
  end if;
  update public.connections set model_choice = nullif(clean, '') where id = conn;
end;
$_$;

--
-- Name: set_page_state(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_page_state(p uuid, key text, value jsonb) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  pg public.pages := public.team_page(p);
  at timestamptz := now();
begin
  if key !~ '^[A-Za-z0-9_.:-]{1,100}$' then
    raise exception 'a key is letters, numbers and . _ : - only, up to 100';
  end if;
  if pg_column_size(value) > 65536 then
    raise exception 'one value is at most 64 KB';
  end if;
  if value is null or value = 'null'::jsonb then
    delete from public.page_state where page_id = pg.id and page_state.key = set_page_state.key;
    return at;
  end if;
  if not exists (select 1 from public.page_state where page_id = pg.id and page_state.key = set_page_state.key)
     and (select count(*) from public.page_state where page_id = pg.id) >= 300 then
    raise exception 'a page keeps at most 300 values';
  end if;
  insert into public.page_state (page_id, table_id, key, value, updated_by, updated_at)
    values (pg.id, pg.table_id, key, value, public.my_member_id(pg.table_id), at)
    on conflict on constraint page_state_pkey do update set value = excluded.value, updated_by = excluded.updated_by, updated_at = excluded.updated_at;
  return at;
end;
$_$;

