-- Name: set_work_in_folder(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_work_in_folder(conn uuid, on_ boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.connections;
begin
  select * into c from public.connections where id = conn and revoked_at is null;
  if not found or c.member_id is distinct from public.my_member_id(c.table_id) then
    raise exception 'only its own person sets where their AI works';
  end if;
  update public.connections set in_folder = coalesce(on_, true) where id = conn;
end;
$$;

--
-- Name: setup_chat(uuid, text, text, text, uuid[], boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.setup_chat(c uuid, chat_name text, chat_about text, who text, people uuid[], take_notes boolean, ai_answers text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ch public.chats;
  me uuid;
  clean text := left(btrim(coalesce(chat_name, '')), 60);
begin
  select * into ch from public.chats where id = c for update;
  if not found or not public.can_see_chat(c) then
    raise exception 'that chat is not at a table you are on';
  end if;
  me := public.my_member_id(ch.table_id);
  if not (coalesce(ch.created_by = me, false) or public.is_owner(ch.table_id)) then
    raise exception 'only the person who made this chat, or an owner, can set it up';
  end if;
  if ch.is_general and who <> 'everyone' then
    raise exception 'General is everyone''s';
  end if;
  if char_length(clean) = 0 then
    raise exception 'a chat needs a name';
  end if;
  if char_length(btrim(coalesce(chat_about, ''))) > 140 then
    raise exception 'what a chat is for takes up to 140 characters';
  end if;
  if who not in ('everyone', 'some', 'me') then
    raise exception 'a chat is for everyone, some people, or just you';
  end if;
  if coalesce(ai_answers, '') not in ('normal', 'named', 'silent', 'off') then
    raise exception 'the AIs answer normally, when named, never, or no AI hears the chat';
  end if;
  if ai_answers = 'off' and ch.is_general then
    raise exception 'General is where the AIs work; make a new chat for talk no AI may hear';
  end if;
  if who = 'some' and exists (select 1 from unnest(coalesce(people, '{}')) p
                               where not exists (select 1 from public.members m where m.id = p and m.table_id = ch.table_id
                                                   and m.role in ('owner', 'developer') and m.removed_at is null)) then
    raise exception 'only people on the team can be in a chat';
  end if;
  update public.chats set name = clean, about = btrim(coalesce(chat_about, '')), private = who <> 'everyone',
         notes = coalesce(take_notes, false) and ai_answers <> 'off', answers = ai_answers, set_up = true,
         created_by = coalesce(created_by, me)
   where id = c;
  delete from public.chat_people where chat_id = c;
  if who <> 'everyone' then
    insert into public.chat_people (chat_id, member_id)
      select c, x from (select me as x union select ch.created_by where ch.created_by is not null
                          and exists (select 1 from public.members mm where mm.id = ch.created_by and mm.removed_at is null)
                        union select unnest(coalesce(people, '{}')) where who = 'some') s on conflict do nothing;
    -- Open work of someone now outside the room: views and reviews are dropped, anything else goes to someone inside.
    update public.jobs set status = 'skipped', lease_until = null, error = 'not in the room any more'
     where chat_id = c and status in ('queued', 'running', 'waiting') and kind in ('view', 'review') and not public.member_sees_chat(c, member_id);
    update public.jobs set member_id = member_id
     where chat_id = c and status in ('queued', 'waiting') and not public.member_sees_chat(c, member_id);
    update public.jobs set status = 'skipped', lease_until = null, error = 'not in the room any more'
     where chat_id = c and status in ('queued', 'running', 'waiting') and not public.member_sees_chat(c, member_id);
  end if;
  if ai_answers = 'off' then
    -- Everything already said here is kept from the AIs for good, and any work they had in it ends now.
    update public.messages set no_ai = true where chat_id = c and not no_ai;
    update public.jobs set status = 'skipped', lease_until = null, error = 'no AI hears this chat'
     where chat_id = c and status in ('queued', 'running', 'waiting');
    delete from public.listens where chat_id = c;
    update public.tables set client_chat = null where id = ch.table_id and client_chat = c;
  end if;
  -- Nobody may be left reading a room from the requests side: a private chat never takes clients' requests.
  update public.tables set client_chat = null where id = ch.table_id and client_chat = c and who <> 'everyone';
  if coalesce(current_setting('longtable.making_chat', true), '') <> '1' then
    perform public.log_activity(ch.table_id, me, 'chat.set_up', c, jsonb_build_object('name', clean));
  end if;
end;
$$;

--
-- Name: start_look(uuid, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_look(t uuid, c uuid, q uuid, writer uuid, early_ boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r uuid := gen_random_uuid();
  s uuid;
  others integer := 0;
begin
  for s in select distinct cn.member_id
             from public.connections cn join public.members m on m.id = cn.member_id
            where cn.table_id = t and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds'
              and m.role in ('owner', 'developer') and m.removed_at is null and public.member_sees_chat(c, m.id)
              and cn.member_id <> writer loop
    insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, early) values (t, c, s, q, 'view', r, early_);
    others := others + 1;
  end loop;
  -- With nobody else on, the look starts now; else it waits for the views (release_rounds, at most 90 seconds).
  insert into public.jobs (table_id, chat_id, member_id, question_id, kind, early, round, status)
    values (t, c, writer, q, 'look', early_, case when others > 0 then r end,
            case when others > 0 then 'waiting'::public.job_status else 'queued'::public.job_status end);
end;
$$;

--
-- Name: start_pairing(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_pairing(t uuid, ai_kind text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  raw text;
  me uuid := public.my_member_id(t);
begin
  if me is null then
    raise exception 'only people at this table can connect an AI';
  end if;
  if ai_kind not in ('claude', 'codex') then
    raise exception 'unknown kind of AI';
  end if;
  if (select count(*) from public.pairings p where p.member_id = me and p.created_at > now() - interval '1 hour') >= 10 then
    raise exception 'that is ten connect codes this hour; try again in a while';
  end if;
  raw := upper(encode(extensions.gen_random_bytes(10), 'hex'));
  insert into public.pairings (table_id, member_id, kind, code_hash)
    values (t, me, ai_kind, encode(extensions.digest(raw, 'sha256'), 'hex'));
  return raw;
end;
$$;

--
-- Name: start_round(uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_round(t uuid, c uuid, q uuid, me uuid, task uuid DEFAULT NULL::uuid, title text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  seats uuid[];
  final uuid;
  offline text;
  online_seat uuid;
  r uuid := gen_random_uuid();
  s uuid;
  worker uuid;
  claudes integer;
  name text;
begin
  select array_agg(cn.member_id order by cn.created_at) into seats
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and public.member_sees_chat(c, m.id)
   where cn.table_id = t and cn.revoked_at is null;
  if seats is null then
    return jsonb_build_object('message_id', q, 'answered_by', null);
  end if;

  if task is null then
    name := btrim(public.hide_secrets(coalesce(nullif(btrim(title), ''), (select left(split_part(m.body, E'\n', 1), 70) from public.messages m where m.id = q), 'Work')));
    task := gen_random_uuid();
    insert into public.tasks (id, table_id, chat_id, member_id, title, branch)
      values (task, t, c, me, left(coalesce(nullif(name, ''), 'Work'), 120),
              'longtable/' || coalesce(nullif(btrim(left(regexp_replace(lower(name), '[^a-z0-9]+', '-', 'g'), 40), '-'), ''), 'work') || '-' || left(task::text, 8));
  else
    update public.tasks set status = 'working', finished_at = null where id = task;
  end if;

  select cn.member_id into online_seat
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and public.member_sees_chat(c, m.id)
   where cn.table_id = t and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds'
   order by cn.created_at limit 1;
  select coalesce(tb.final_seat, tb.main_owner), tb.when_final_offline
    into final, offline from public.tables tb where tb.id = t;
  if not (final = any (seats)) then
    final := coalesce(online_seat, seats[1]);
  elsif offline = 'next' and online_seat is not null and not exists (
      select 1 from public.connections cn where cn.member_id = final and cn.revoked_at is null
        and cn.last_seen > now() - interval '60 seconds') then
    final := online_seat;
  end if;

  if array_length(seats, 1) = 1 then
    insert into public.jobs (table_id, chat_id, member_id, question_id, kind, task_id) values (t, c, final, q, 'answer', task);
    perform public.log_activity(t, me, 'table.asked', q, jsonb_build_object('answered_by', final, 'task', task));
    return jsonb_build_object('message_id', q, 'answered_by', final, 'task', task);
  end if;

  select cn.member_id into worker
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and public.member_sees_chat(c, m.id)
   where cn.table_id = t and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
   order by (cn.member_id = me) desc, cn.created_at limit 1;
  select count(distinct cn.member_id) into claudes
    from public.connections cn join public.members m on m.id = cn.member_id and m.role in ('owner', 'developer') and public.member_sees_chat(c, m.id)
   where cn.table_id = t and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds';
  if worker is not null then
    foreach s in array seats loop
      -- Only an AI that is on right now is asked for its view: one whose computer is closed would hold everyone up.
      if s <> worker and exists (select 1 from public.connections cn where cn.member_id = s and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds') then
        insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id) values (t, c, s, q, 'view', r, task);
      end if;
    end loop;
    -- With another Claude there to hand parts to, the work starts with a plan.
    insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, status, task_id)
      values (t, c, worker, q, case when claudes >= 2 then 'plan' else 'work' end, r, 'waiting', task);
    perform public.log_activity(t, me, 'table.asked', q, jsonb_build_object('answered_by', final, 'worker', worker, 'round', r, 'task', task));
    return jsonb_build_object('message_id', q, 'answered_by', final, 'worker', worker, 'round', r, 'task', task);
  end if;

  foreach s in array seats loop
    if s <> final and exists (select 1 from public.connections cn where cn.member_id = s and cn.revoked_at is null and cn.last_seen > now() - interval '60 seconds') then
      insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, task_id) values (t, c, s, q, 'view', r, task);
    end if;
  end loop;
  insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, status, task_id)
    values (t, c, final, q, 'combine', r, 'waiting', task);
  perform public.log_activity(t, me, 'table.asked', q, jsonb_build_object('answered_by', final, 'round', r, 'task', task));
  return jsonb_build_object('message_id', q, 'answered_by', final, 'round', r, 'task', task);
end;
$$;

--
-- Name: start_table(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_table(table_name text, my_name text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t uuid;
  me uuid;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if (select count(*) from public.tables x where x.created_by = auth.uid() and x.created_at > now() - interval '1 day') >= 10 then
    raise exception 'that is ten new tables today; try again tomorrow';
  end if;
  insert into public.tables (name, created_by) values (btrim(table_name), auth.uid()) returning id into t;
  insert into public.members (table_id, user_id, role, display_name, color)
    values (t, auth.uid(), 'owner', btrim(my_name), public.next_color(t)) returning id into me;
  insert into public.chats (table_id, name, about, is_general, created_by) values (t, 'General', 'Everyone on the team', true, me);
  insert into public.chats (table_id, name, about, set_up) values (t, 'Chat room', '', false);
  perform public.log_activity(t, me, 'table.started', t, jsonb_build_object('name', btrim(table_name)));
  return t;
end;
$$;

--
-- Name: stop_job(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stop_job(job uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j public.jobs;
  me uuid;
  who text;
begin
  select * into j from public.jobs where id = job;
  if j.round is not null then
    perform pg_advisory_xact_lock(hashtext(j.round::text));
  end if;
  select * into j from public.jobs where id = job for update;
  if not found or not public.is_team(j.table_id) or (j.chat_id is not null and not public.can_see_chat(j.chat_id)) or j.kind in ('client', 'intro') then
    raise exception 'that is not yours to stop';
  end if;
  me := public.my_member_id(j.table_id);
  select display_name into who from public.members where id = me;
  update public.jobs set status = 'skipped', lease_until = null, error = 'stopped by ' || who
   where status in ('queued', 'running', 'waiting') and (id = j.id or (j.round is not null and round = j.round));
  if j.round is not null and not exists (select 1 from public.jobs where round = j.round and kind = 'combine') then
    insert into public.jobs (table_id, chat_id, member_id, question_id, kind, round, status, error)
      values (j.table_id, j.chat_id, j.member_id, j.question_id, 'combine', j.round, 'skipped', 'stopped by ' || who);
  end if;
  update public.tasks set status = 'stopped', finished_at = now() where id = j.task_id and status = 'working'
     and not exists (select 1 from public.jobs o where o.task_id = j.task_id and o.status in ('queued', 'running', 'waiting'));
  perform public.log_activity(j.table_id, me, 'ai.stopped', j.id, jsonb_build_object('kind', j.kind));
end;
$$;

--
-- Name: subject_visible(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.subject_visible(s uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select public.can_see_chat(x.c) from (
           select ch.id as c from public.chats ch where ch.id = s
           union all select m.chat_id from public.messages m where m.id = s
           union all select d.chat_id from public.decisions d where d.id = s
           union all select tk.chat_id from public.tasks tk where tk.id = s
           union all select pg.chat_id from public.pages pg where pg.id = s
           union all select j.chat_id from public.jobs j where j.id = s and j.chat_id is not null) x limit 1), true);
$$;

--
-- Name: table_is_locked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.table_is_locked(t uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select locked from public.table_joining where table_id = t), false);
$$;

--
-- Name: take_files(uuid, uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.take_files(t uuid, owner uuid, files jsonb, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  me uuid := public.my_member_id(t);
  f jsonb;
  o record;
  made uuid;
  mime text;
  out jsonb := '[]'::jsonb;
  n integer := 0;
  used bigint;
begin
  if me is null then
    raise exception 'you are not at this table';
  end if;
  -- What this person already keeps at this table, from their own folder.
  select coalesce(sum(a.size), 0) into used from public.attachments a where a.table_id = t and a.path like t::text || '/' || me::text || '/%';
  for f in select x from jsonb_array_elements(coalesce(files, '[]'::jsonb)) x loop
    n := n + 1;
    if n > 10 then
      raise exception 'ten attachments at most in one message';
    end if;
    if coalesce(f ->> 'path', '') !~ ('^' || t::text || '/' || me::text || '/[0-9a-f-]{36}-[^/]{1,200}$') then
      raise exception 'that attachment is not yours';
    end if;
    select so.id, so.metadata into o from storage.objects so where so.bucket_id = 'attachments' and so.name = f ->> 'path';
    if not found then
      raise exception 'that attachment did not finish uploading';
    end if;
    -- The address an AI will fetch it from must be this very file's signed address, nothing else.
    if position('/storage/v1/object/sign/attachments/' || replace(f ->> 'path', ' ', '%20') || '?token=' in coalesce(f ->> 'url', '')) = 0
       and position('/storage/v1/object/sign/attachments/' || (f ->> 'path') || '?token=' in coalesce(f ->> 'url', '')) = 0 then
      raise exception 'that attachment has no address';
    end if;
    used := used + coalesce((o.metadata ->> 'size')::bigint, 0);
    if used > 200 * 1024 * 1024 then
      raise exception 'that would be more than 200 MB of attachments from you at this table, which is the most each person keeps';
    end if;
    mime := left(coalesce(nullif(o.metadata ->> 'mimetype', ''), f ->> 'mime', 'application/octet-stream'), 120);
    insert into public.attachments (table_id, member_id, message_id, path, name, mime, size, kind)
      values (t, owner, msg, f ->> 'path', left(coalesce(nullif(btrim(f ->> 'name'), ''), 'file'), 200), mime,
              coalesce((o.metadata ->> 'size')::bigint, 0),
              case when mime like 'image/%' then 'image' when mime like 'video/%' then 'video' when mime like 'audio/%' then 'audio' else 'file' end)
      returning id into made;
    insert into public.attachment_links (attachment_id, url) values (made, f ->> 'url');
    out := out || (select jsonb_build_object('id', a.id, 'name', a.name, 'mime', a.mime, 'size', a.size, 'path', a.path, 'kind', a.kind) from public.attachments a where a.id = made);
  end loop;
  return out;
end;
$_$;

--
-- Name: pages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    chat_id uuid NOT NULL,
    job_id uuid,
    made_by uuid,
    title text NOT NULL,
    about text DEFAULT ''::text NOT NULL,
    icon text DEFAULT 'page'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    touched_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT pages_about_check CHECK ((char_length(about) <= 300)),
    CONSTRAINT pages_icon_check CHECK ((icon ~ '^[a-z]{1,24}$'::text)),
    CONSTRAINT pages_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 120)))
);

--
-- Name: team_page(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_page(p uuid) RETURNS public.pages
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  pg public.pages;
begin
  select * into pg from public.pages where id = p;
  if not found or not public.can_see_chat(pg.chat_id) then
    raise exception 'that page is not at a table you are on';
  end if;
  return pg;
end;
$$;

--
-- Name: team_sandbox_change(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_sandbox_change(m uuid, body text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  sb public.sandboxes;
  words text := btrim(coalesce(body, ''));
  seat uuid;
  change uuid;
begin
  select * into sb from public.sandboxes where member_id = m;
  if not found or not public.may(sb.table_id, 'clients') or not exists (select 1 from public.members x where x.id = m and x.removed_at is null) then
    raise exception 'that copy is not yours to try';
  end if;
  if char_length(words) = 0 or char_length(words) > 4000 then
    raise exception 'say what to change, in up to 4,000 characters';
  end if;
  if (select count(*) from public.sandbox_changes c where c.member_id = m and c.test and c.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'that is a lot of tests in one hour';
  end if;
  select cn.member_id into seat
    from public.connections cn join public.members mem on mem.id = cn.member_id and mem.role in ('owner', 'developer')
   where cn.table_id = sb.table_id and cn.revoked_at is null and cn.kind = 'claude' and cn.last_seen > now() - interval '60 seconds'
   order by (cn.member_id = public.my_member_id(sb.table_id)) desc, cn.created_at limit 1;
  if seat is null then
    raise exception 'connect your team''s Claude first';
  end if;
  insert into public.sandbox_changes (table_id, member_id, words, test) values (sb.table_id, m, words, true) returning id into change;
  insert into public.jobs (table_id, member_id, kind, change_id) values (sb.table_id, seat, 'sandbox', change);
  return change;
end;
$$;

--
-- Name: team_say(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.team_say(m uuid, words text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
  me public.members;
  clean text := public.hide_secrets(btrim(coalesce(words, '')));
  line uuid;
begin
  select * into who from public.members where id = m and role = 'client' and removed_at is null;
  if not found or not public.may(who.table_id, 'clients') then raise exception 'you cannot write in this chat'; end if;
  if clean = '' then raise exception 'there is nothing to send'; end if;
  if char_length(clean) > 4000 then raise exception 'that is too long to send'; end if;
  select * into me from public.members where table_id = who.table_id and user_id = auth.uid() and removed_at is null;
  insert into public.client_lines (table_id, member_id, who, body, by_table, from_name)
    values (who.table_id, who.id, 'team', clean, true, me.display_name) returning id into line;
  -- Words waiting for a team AI to come on have now been answered by a person: the client is no longer told to wait, and
  -- no AI answers them hours later. They already reached the team as a request.
  update public.client_lines set waiting = false where member_id = who.id and waiting;
  perform public.log_activity(who.table_id, me.id, 'client.team_said', null, jsonb_build_object('client', who.id));
  return line;
end;
$$;

--
-- Name: tick(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tick() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s integer := extract(epoch from now())::integer;
begin
  begin perform public.listen_now(); exception when others then raise warning 'tripwire: listen_now %', sqlerrm; end;
  if s % 2 = 0 then
    begin perform public.release_rounds(); exception when others then raise warning 'tripwire: release_rounds %', sqlerrm; end;
    begin perform public.advance_rounds(); exception when others then raise warning 'tripwire: advance_rounds %', sqlerrm; end;
    begin perform public.deliver_due(); exception when others then raise warning 'tripwire: deliver_due %', sqlerrm; end;
  end if;
  if s % 5 = 0 then
    begin perform public.client_job_timeouts(); exception when others then raise warning 'tripwire: client_job_timeouts %', sqlerrm; end;
  end if;
  if s % 10 = 0 then
    begin perform public.close_sandbox(); exception when others then raise warning 'tripwire: close_sandbox %', sqlerrm; end;
  end if;
end;
$$;

--
-- Name: topic_table_id(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.topic_table_id(topic text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when topic ~ '^team:[0-9a-f-]{36}$' then substring(topic from 6)::uuid else null end;
$_$;

--
-- Name: transfer_ownership(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_ownership(m uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  who public.members;
  me uuid;
begin
  select * into who from public.members where id = m;
  if not found then
    raise exception 'only the owner can hand the table over';
  end if;
  -- One hand-over or removal at a table at a time, and the person read again once it is this one's turn.
  perform 1 from public.tables where id = who.table_id for update;
  select * into who from public.members where id = m for update;
  if not public.is_main_owner(who.table_id) then
    raise exception 'only the owner can hand the table over';
  end if;
  me := public.my_member_id(who.table_id);
  if who.id = me then
    raise exception 'you already own this table';
  end if;
  if who.removed_at is not null or who.role <> 'developer' then
    raise exception 'the table can only be handed to a developer who is at it';
  end if;
  update public.members set role = 'developer' where id = me;
  update public.members set role = 'owner' where id = who.id;
  update public.tables set main_owner = who.id where id = who.table_id;
  perform public.log_activity(who.table_id, me, 'table.handed_over', who.id, jsonb_build_object('name', who.display_name));
end;
$$;

--
-- Name: undo_decision(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_decision(d uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  dec public.decisions;
begin
  select * into dec from public.decisions where id = d for update;
  if not found or not public.can_see_chat(dec.chat_id) then
    raise exception 'only the team can undo';
  end if;
  if dec.status <> 'decided' or dec.delivered_at is not null or dec.deliver_after <= now() then
    raise exception 'too late to undo';
  end if;
  update public.decisions
     set status = 'open', chosen = null, decided_by = null, decided_at = null, deliver_after = null
   where id = d;
  perform public.log_activity(dec.table_id, public.my_member_id(dec.table_id), 'decision.undone', d, jsonb_build_object('title', dec.title));
end;
$$;

--
-- Name: sandbox_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sandbox_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    table_id uuid NOT NULL,
    member_id uuid NOT NULL,
    words text NOT NULL,
    status text DEFAULT 'working'::text NOT NULL,
    summary text,
    detail text,
    files jsonb DEFAULT '[]'::jsonb NOT NULL,
    commit text,
    stale boolean DEFAULT false NOT NULL,
    request_id uuid,
    verdict text,
    note text,
    decided_by uuid,
    decided_at timestamp with time zone,
    task_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    test boolean DEFAULT false NOT NULL,
    undone text,
    CONSTRAINT sandbox_changes_note_check CHECK (((note IS NULL) OR (char_length(note) <= 1000))),
    CONSTRAINT sandbox_changes_status_check CHECK ((status = ANY (ARRAY['working'::text, 'ready'::text, 'nothing'::text, 'passed'::text, 'failed'::text, 'stopped'::text]))),
    CONSTRAINT sandbox_changes_undone_check CHECK ((undone = ANY (ARRAY['undoing'::text, 'undone'::text, 'stuck'::text]))),
    CONSTRAINT sandbox_changes_verdict_check CHECK ((verdict = ANY (ARRAY['take'::text, 'differently'::text, 'no'::text]))),
    CONSTRAINT sandbox_changes_words_check CHECK (((char_length(btrim(words)) >= 1) AND (char_length(btrim(words)) <= 4000)))
);

--
-- Name: undo_in_copy(public.sandbox_changes); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_in_copy(ch public.sandbox_changes) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  seat uuid := public.copy_seat(ch.table_id);
begin
  if seat is null or ch.commit is null or ch.status <> 'ready' or ch.undone is not null or ch.test then
    return false;
  end if;
  update public.sandbox_changes set undone = 'undoing' where id = ch.id;
  insert into public.jobs (table_id, member_id, kind, subject, change_id, brief) values (ch.table_id, seat, 'sandbox', ch.member_id, ch.id, 'undo');
  return true;
end;
$$;

--
-- Name: unpin_note(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unpin_note(n uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  note public.notes;
begin
  select * into note from public.notes where id = n;
  if not found or not public.is_team(note.table_id) then
    raise exception 'only the team can unpin a note';
  end if;
  delete from public.notes where id = n;
  perform public.log_activity(note.table_id, public.my_member_id(note.table_id), 'note.unpinned', n, jsonb_build_object('title', note.title, 'kind', note.kind));
  perform realtime.send(jsonb_build_object('table', 'notes', 'record', jsonb_build_object('id', n, 'deleted', true)),
    'UPDATE', 'team:' || note.table_id::text, true);
end;
$$;

--
-- Name: update_profile(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_profile(t uuid, new_name text, new_color text, new_name_color text, new_avatar text, new_status text, new_bubble text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  me uuid := public.my_member_id(t);
  clean text := left(btrim(coalesce(new_name, '')), 60);
begin
  if me is null then
    raise exception 'you are not at this table';
  end if;
  if clean = '' then
    raise exception 'you need a name';
  end if;
  if new_color is null or new_color !~ '^(#[0-9a-fA-F]{6}|oklch\([0-9. ]{5,30}\))$' then
    raise exception 'that is not a colour';
  end if;
  if new_bubble is not null and new_bubble <> all (array['rose', 'peach', 'sand', 'lime', 'mint', 'teal', 'sky', 'blue', 'iris', 'lilac', 'pink', 'stone']) then
    raise exception 'that is not one of the bubble colours';
  end if;
  if new_bubble is not null and exists (select 1 from public.members m where m.table_id = t and m.bubble = new_bubble and m.id <> me and m.removed_at is null) then
    raise exception 'someone else at the table has that bubble colour';
  end if;
  update public.members
     set display_name = clean,
         color = new_color,
         name_color = nullif(btrim(coalesce(new_name_color, '')), ''),
         avatar = nullif(coalesce(new_avatar, ''), ''),
         status = left(btrim(coalesce(new_status, '')), 80),
         bubble = coalesce(new_bubble, bubble)
   where id = me and removed_at is null;
end;
$_$;

--
-- Name: update_table(uuid, text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_table(t uuid, table_name text, undo integer, requests_chat uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not public.may(t, 'settings') then
    raise exception 'only the owner changes the settings';
  end if;
  if char_length(btrim(coalesce(table_name, ''))) not between 1 and 80 then
    raise exception 'the table needs a name of up to 80 characters';
  end if;
  if undo is null or undo not between 5 and 300 then
    raise exception 'the undo window is 5 to 300 seconds';
  end if;
  if requests_chat is not null and not exists (select 1 from public.chats c where c.id = requests_chat and c.table_id = t and not c.private and c.set_up) then
    raise exception 'that chat is not at this table';
  end if;
  update public.tables set name = btrim(table_name), undo_seconds = undo, client_chat = requests_chat where id = t;
  perform public.log_activity(t, public.my_member_id(t), 'settings.changed', t,
    jsonb_build_object('name', btrim(table_name), 'undo_seconds', undo, 'client_chat', requests_chat));
end;
$$;

--
-- Name: upload_slot_open(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upload_slot_open(t text, folder text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select folder ~ '^ai-[0-9a-f]{32}$' and exists (select 1 from public.upload_slots s
    where s.key = substring(folder from 4) and s.table_id::text = t and s.expires_at > now())
    and not exists (select 1 from storage.objects o where o.bucket_id = 'attachments' and o.name like t || '/' || folder || '/%');
$_$;

