    created_at timestamp with time zone DEFAULT now() NOT NULL,
    tip text,
    opened_at timestamp with time zone,
    checked_at timestamp with time zone,
    open_ok boolean,
    ticked_by uuid,
    ticked_at timestamp with time zone,
    live_sha text,
    failed_sha text,
    deploys_seen boolean DEFAULT false NOT NULL,
    tip_at timestamp with time zone,
    refreshed_at timestamp with time zone,
    behind_since timestamp with time zone,
    CONSTRAINT sandboxes_mode_check CHECK ((mode = ANY (ARRAY['chat'::text, 'sandbox'::text]))),
    CONSTRAINT sandboxes_url_check CHECK (((url IS NULL) OR (char_length(url) <= 300)))
);

