--
-- Name: table_sandbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.table_sandbox (
    table_id uuid NOT NULL,
    preview_url text,
    cap integer DEFAULT 20,
    paths text DEFAULT ''::text NOT NULL,
    scope text DEFAULT 'screens'::text NOT NULL,
    blocked text DEFAULT ''::text NOT NULL,
    builder uuid,
    CONSTRAINT table_sandbox_cap_check CHECK (((cap IS NULL) OR ((cap >= 1) AND (cap <= 1000)))),
    CONSTRAINT table_sandbox_paths_check CHECK ((char_length(paths) <= 600)),
    CONSTRAINT table_sandbox_preview_url_check CHECK (((preview_url IS NULL) OR (char_length(preview_url) <= 300))),
    CONSTRAINT table_sandbox_scope_check CHECK ((scope = ANY (ARRAY['screens'::text, 'code'::text])))
);

--
-- Name: tables; Type: TABLE; Schema: public; Owner: -
