CREATE TABLE public.tables (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    undo_seconds integer DEFAULT 10 NOT NULL,
    final_seat uuid,
    when_final_offline text DEFAULT 'wait'::text NOT NULL,
    client_chat uuid,
    main_owner uuid,
    CONSTRAINT tables_name_check CHECK (((char_length(btrim(name)) >= 1) AND (char_length(btrim(name)) <= 80))),
    CONSTRAINT tables_undo_seconds_check CHECK (((undo_seconds >= 5) AND (undo_seconds <= 300))),
    CONSTRAINT tables_when_final_offline_check CHECK ((when_final_offline = ANY (ARRAY['wait'::text, 'next'::text])))
);

