    chat_id uuid NOT NULL,
    member_id uuid,
    title text NOT NULL,
    branch text NOT NULL,
    status text DEFAULT 'working'::text NOT NULL,
    result text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    reference jsonb,
    CONSTRAINT tasks_status_check CHECK ((status = ANY (ARRAY['working'::text, 'done'::text, 'stopped'::text]))),
    CONSTRAINT tasks_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120)))
);

