--

CREATE POLICY "the team and the asker read the timeline" ON public.request_events FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.requests r
  WHERE ((r.id = request_events.request_id) AND (public.is_team(r.table_id) OR (r.member_id = public.my_member_id(r.table_id)))))));

--
-- Name: decision_options the team reads decision options; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads decision options" ON public.decision_options FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.decisions d
  WHERE ((d.id = decision_options.decision_id) AND public.is_team(d.table_id)))));

--
-- Name: chats the team reads its chats, a private one only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads its chats, a private one only its people" ON public.chats FOR SELECT USING (public.can_see_chat(id));

--
-- Name: decisions the team reads its decisions, a private chat's only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads its decisions, a private chat's only its people" ON public.decisions FOR SELECT USING (public.can_see_chat(chat_id));

--
-- Name: activity the team reads its log, a private chat's lines only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads its log, a private chat's lines only its people" ON public.activity FOR SELECT USING ((public.is_team(table_id) AND public.log_line_visible(table_id, chat_id)));

--
-- Name: messages the team reads its messages, a private chat's only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads its messages, a private chat's only its people" ON public.messages FOR SELECT USING ((chat_id IN ( SELECT public.my_visible_chats() AS my_visible_chats)));

--
-- Name: notes the team reads its notes; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads its notes" ON public.notes FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: table_ai the team reads the table's model; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads the table's model" ON public.table_ai FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: client_lines the team reads what its own assistant said to a client; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads what its own assistant said to a client" ON public.client_lines FOR SELECT TO authenticated USING ((by_table AND public.is_team(table_id)));

--
-- Name: table_code the team reads where the code is; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team reads where the code is" ON public.table_code FOR SELECT TO authenticated USING (public.is_team(table_id));

