-- Name: page_comments the team sees its page comments, a private chat's only its peop; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees its page comments, a private chat's only its peop" ON public.page_comments FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.pages p
  WHERE ((p.id = page_comments.page_id) AND public.can_see_chat(p.chat_id)))));

--
-- Name: page_versions the team sees its page versions, a private chat's only its peop; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees its page versions, a private chat's only its peop" ON public.page_versions FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.pages p
  WHERE ((p.id = page_versions.page_id) AND public.can_see_chat(p.chat_id)))));

--
-- Name: page_state the team sees its pages' state, a private chat's only its peopl; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees its pages' state, a private chat's only its peopl" ON public.page_state FOR SELECT USING ((EXISTS ( SELECT 1
   FROM public.pages p
  WHERE ((p.id = page_state.page_id) AND public.can_see_chat(p.chat_id)))));

--
-- Name: pages the team sees its pages, a private chat's only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees its pages, a private chat's only its people" ON public.pages FOR SELECT USING (public.can_see_chat(chat_id));

--
-- Name: tasks the team sees its tasks, a private chat's only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees its tasks, a private chat's only its people" ON public.tasks FOR SELECT USING (public.can_see_chat(chat_id));

--
-- Name: sandbox_changes the team sees the sandbox changes; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees the sandbox changes" ON public.sandbox_changes FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: table_sandbox the team sees the sandbox settings; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees the sandbox settings" ON public.table_sandbox FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: sandboxes the team sees the sandboxes; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees the sandboxes" ON public.sandboxes FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: jobs the team sees the team's jobs, a private chat's only its people; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees the team's jobs, a private chat's only its people" ON public.jobs FOR SELECT USING (((public.is_team(table_id) AND (kind <> 'client'::text) AND ((chat_id IS NULL) OR public.can_see_chat(chat_id))) OR (member_id = public.my_member_id(table_id))));

--
-- Name: attachments the team sees what is attached at its table, in a private chat ; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees what is attached at its table, in a private chat " ON public.attachments FOR SELECT USING ((public.is_team(table_id) AND ((message_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.messages m
  WHERE ((m.id = attachments.message_id) AND public.can_see_chat(m.chat_id))))) AND ((job_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.jobs j
  WHERE ((j.id = attachments.job_id) AND ((j.chat_id IS NULL) OR public.can_see_chat(j.chat_id))))))));

--
-- Name: connections the team sees who is connected; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team sees who is connected" ON public.connections FOR SELECT TO authenticated USING (public.is_team(table_id));

--
-- Name: messages the team writes messages as itself, where it may; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team writes messages as itself, where it may" ON public.messages FOR INSERT WITH CHECK ((public.is_team(table_id) AND (member_id = public.my_member_id(table_id)) AND (NOT by_ai) AND (kind = 'chat'::text) AND (meta = '{}'::jsonb) AND public.can_see_chat(chat_id) AND COALESCE(( SELECT ch.set_up
   FROM public.chats ch
  WHERE (ch.id = messages.chat_id)), false)));

--
-- Name: client_updates the team, and the client it was said to, read client updates; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "the team, and the client it was said to, read client updates" ON public.client_updates FOR SELECT TO authenticated USING ((public.is_team(table_id) OR (public.is_member(table_id) AND ((request_id IS NULL) OR (EXISTS ( SELECT 1
   FROM public.requests r
  WHERE ((r.id = client_updates.request_id) AND (r.member_id = public.my_member_id(r.table_id)))))))));

